static void section_ensure(Section *s, int need) {
    if (s->data_offset + need <= s->data_allocated) return;
    int na = s->data_allocated ? s->data_allocated : 256;
    while (na < s->data_offset + need) na *= 2;
    s->data = tcc_realloc(s->data, na);
    memset(s->data + s->data_allocated, 0, na - s->data_allocated);
    s->data_allocated = na;
}

static int section_append(Section *s, const void *data, int len) {
    section_ensure(s, len + 1);
    int off = s->data_offset;
    if (data) memcpy(s->data + off, data, len);
    else memset(s->data + off, 0, len);
    s->data_offset += len;
    return off;
}

