typedef struct IncludeGuard {
    char *filename;
    char *macro_name;  /* guard macro */
    struct IncludeGuard *next;
} IncludeGuard;

/* Include file state */
typedef struct BufferState {
    const char *buf;      /* source buffer */
    int buf_len;
    int idx;              /* current position */
    char *filename;       /* source filename */
    int line_num;         /* current line number */
    int is_string;        /* 1 if string buffer (not file) */
    int iflevel;          /* #if nesting level at start */
    struct BufferState *prev;
} BufferState;

/* Current token */
typedef struct {
    int tok;          /* token type */
    int line_num;     /* line number */
    CString tok_str;  /* token string (for TOK_STR etc) */
    union {
        int i;
        unsigned int ui;
        long long ll;
        unsigned long long ull;
        double d;
        long double ld;
        float f;
    };
} Token;

/* Scope entry */
typedef struct Scope {
    Symbol *syms;      /* symbols in this scope */
    struct Scope *prev;
} Scope;

/* Label */
typedef struct Label {
    char *name;
    int section;    /* which section it's in */
    int offset;     /* offset in section */
    int defined;    /* 1 if defined */
    int refs;       /* number of references */
    /* forward references */
    struct LabelRef *refs_list;
    struct Label *hash_next;
} Label;

typedef struct LabelRef {
    int section;
    int offset;     /* offset of the 4-byte patch location */
    struct LabelRef *next;
} LabelRef;

/* Switch statement info */
typedef struct SwitchCase {
    long long val;    /* case value */
    int label_off;    /* offset of case label */
    struct SwitchCase *next;
} SwitchCase;

typedef struct SwitchState {
    SwitchCase *cases;
    int default_off;   /* offset of default case, -1 if none */
    int break_label;   /* label for break */
    struct SwitchState *prev;
} SwitchState;

/* Compilation context for a single function */
typedef struct FuncCtx {
    int loc;           /* current stack size (negative from rbp) */
    int func_vt;       /* function return type */
    int ret_label;     /* label for return */
    int *break_labels;
    int nb_break;
    int *cont_labels;
    int nb_cont;
    SwitchState *sw;   /* current switch state */
} FuncCtx;

/* The main compiler state */
struct TCCState {
    /* Output type */
    int output_type;
    int output_format;
    char *outfile;

    /* Paths */
    char *tcc_lib_path;
    char **include_paths;
    int nb_include_paths;
    char **sys_include_paths;
    int nb_sys_include_paths;
    char **library_paths;
    int nb_library_paths;
    char **linked_libs;
    int nb_linked_libs;

    /* Input files */
    char **files;
    int nb_files;
    int *file_types;

    /* Flags */
    int verbose;
    int nostdinc;
    int nostdlib;
    int static_link;
    int rdynamic;
    int symbolic;
    int pic;
    int shared;
    int relocatable;
    int char_is_unsigned;
    int leading_underscore;
    int ms_extensions;
    int dollars_in_identifiers;
    int reverse_funcargs;
    int ms_bitfields;
    int no_sse;
    int gnu89_inline;
    int asynchronous_unwind_tables;
    int test_coverage;

    /* Warnings */
    int warn_none;
    int warn_all;
    int warn_error;
    int warn_write_strings;
    int warn_unsupported;
    int warn_implicit_function_declaration;
    int warn_discarded_qualifiers;
    int warn_specific[32]; /* per-warning control */

    /* Debug */
    int do_debug;
    int dwarf;
    int dwarf_version;
    int do_bounds_check;
    int bt_num;

    /* Misc */
    int do_bench;
    int do_run;
    int pp_only;
    int pp_lineno_mode;  /* -P, -P1 */
    int pp_dD;           /* -dD */
    int pp_dM;           /* -dM */
    int pp_debug;        /* -dt */
    int gen_deps;
    int include_sys_deps;
    char *deps_outfile;
    char *rstdin_file;
    int do_ar;
    int std_version;     /* __STDC_VERSION__ */
    int no_asm;          /* -x n */

    /* Linker options */
    char *init_sym;
    char *fini_sym;
    uint64_t text_addr;
    int has_text_addr;
    uint64_t section_align;
    char *rpath;
    int enable_new_dtags;
    char *soname;
    char *elf_interp;
    int whole_archive;
    int alacarte_link;
    int oformat;
    char *mapfile;

    /* Preprocessor state */
    Macro *macros[MACRO_HASH_SIZE]; /* macro hash table */
    IncludeGuard *include_guards;   /* include guard cache */
    char **pragma_once_files;
    int nb_pragma_once_files;

    /* Lexer state */
    BufferState *bs;    /* current buffer state */
    Token tok;          /* current token */
    int tok_flags;
    char ch;            /* current character */

    /* if/else stack */
    int *iflevel_stack; /* stack of if/else states */
    int iflevel;        /* current #if nesting level */
    struct {
        int tok;   /* TOK_IF, TOK_ELIF, TOK_ELSE_PP */
        int had_true; /* had a true branch */
