        TypeDef *def;
        struct TagSym *hash_next;
    } *tags[256];

    /* Labels */
    Label *labels[256];

    /* Sections */
    Section *text_section;
    Section *data_section;
    Section *data_ro_section;
    Section *bss_section;
    Section *symtab_section;
    Section *strtab_section;
