    return s->data_offset;
}

static int strtab_put(Section *strtab, const char *str) {
    int idx = strtab->data_offset;
    section_append(strtab, str, strlen(str)+1);
    return idx;
}

/* ============================================================
 * SYMBOL TABLE
 * ============================================================ */

#define SYM_HASH_SIZE 2048
#define SYM_HASH_MASK (SYM_HASH_SIZE-1)

typedef struct TccSym {
    char *name;
    int section;      /* 0=undef, -1=abs, -2=common, else section idx */
    uint64_t value;
    uint64_t size;
    int type;         /* STT_* */
    int bind;         /* STB_* */
    int vis;          /* STV_* */
    int elf_index;    /* index in ELF symtab */
    int is_weak;
    struct TccSym *hash_next;
} TccSym;

typedef struct SymTable {
    TccSym *buckets[SYM_HASH_SIZE];
    TccSym **list;
    int count, cap;
} SymTable;

static unsigned sym_hashfn(const char *s) {
    unsigned h = 5381;
    while (*s) h = (h*33) ^ (unsigned char)*s++;
    return h & SYM_HASH_MASK;
}

static TccSym *sym_lookup(SymTable *t, const char *name) {
    TccSym *s = t->buckets[sym_hashfn(name)];
    while (s) { if (!strcmp(s->name, name)) return s; s = s->hash_next; }
    return NULL;
}

static TccSym *sym_add(SymTable *t, const char *name) {
    TccSym *s = calloc(1, sizeof(TccSym));
    s->name = tcc_strdup(name);
    unsigned h = sym_hashfn(name);
    s->hash_next = t->buckets[h];
    t->buckets[h] = s;
    if (t->count >= t->cap) {
        t->cap = t->cap ? t->cap*2 : 64;
        t->list = tcc_realloc(t->list, t->cap*sizeof(TccSym*));
    }
    t->list[t->count++] = s;
    return s;
}

static void sym_free(SymTable *t) {
    for (int i = 0; i < t->count; i++) {
        free(t->list[i]->name);
        free(t->list[i]);
    }
    free(t->list);
    memset(t, 0, sizeof(*t));
}

