/* ============================================================
 * ERROR HANDLING
 * ============================================================ */

static TCCState *g_tcc = NULL; /* global state for error reporting */

static void tcc_error_v(TCCState *s, int is_error, const char *fmt, va_list ap) {
    if (s->bs && s->bs->filename) {
        fprintf(stderr, "%s:%d: ", s->bs->filename, s->bs->line_num);
    } else if (s->current_filename) {
        fprintf(stderr, "%s: ", s->current_filename);
    }
    if (is_error) {
        fprintf(stderr, "error: ");
    } else {
        fprintf(stderr, "warning: ");
    }
    vfprintf(stderr, fmt, ap);
    fprintf(stderr, "\n");

    if (is_error) {
        s->nb_errors++;
        if (s->error_set) {
            longjmp(s->error_jmp, 1);
        }
    }
}

static void tcc_error(TCCState *s, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    tcc_error_v(s, 1, fmt, ap);
    va_end(ap);
    /* If we can't longjmp, just exit */
    exit(1);
}

static void tcc_warning(TCCState *s, const char *fmt, ...) {
    if (s->warn_none) return;
    va_list ap;
    va_start(ap, fmt);
    if (s->warn_error) {
        tcc_error_v(s, 1, fmt, ap);
    } else {
        tcc_error_v(s, 0, fmt, ap);
    }
    va_end(ap);
}

static void tcc_errorf(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    fprintf(stderr, "tcc: error: ");
    vfprintf(stderr, fmt, ap);
    fprintf(stderr, "\n");
    va_end(ap);
    exit(1);
}

/* ============================================================
 * MACRO HANDLING
 * ============================================================ */

static unsigned macro_hashfn(const char *s) {
    unsigned h = 5381;
    while (*s) h = (h*33) ^ (unsigned char)*s++;
    return h & MACRO_HASH_MASK;
}

static Macro *macro_find(TCCState *s, const char *name) {
    Macro *m = s->macros[macro_hashfn(name)];
    while (m) { if (!strcmp(m->name, name)) return m; m = m->hash_next; }
    return NULL;
}

static void macro_define(TCCState *s, const char *name, const char *body,
                          char **params, int nb_params, int is_variadic) {
    Macro *m = macro_find(s, name);
    if (m) {
        /* Redefine: update */
        free(m->body);
        m->body = body ? tcc_strdup(body) : tcc_strdup("");
        if (m->params) {
            for (int i = 0; i < m->nb_params; i++) free(m->params[i]);
            free(m->params);
        }
        m->params = params;
        m->nb_params = nb_params;
        m->is_variadic = is_variadic;
        m->is_undef = 0;
        return;
    }
    m = calloc(1, sizeof(Macro));
    m->name = tcc_strdup(name);
    m->body = body ? tcc_strdup(body) : tcc_strdup("");
    m->params = params;
    m->nb_params = nb_params;
    m->is_variadic = is_variadic;
    unsigned h = macro_hashfn(name);
    m->hash_next = s->macros[h];
    s->macros[h] = m;
}

static void macro_undef(TCCState *s, const char *name) {
    Macro *m = macro_find(s, name);
    if (m) {
        free(m->body);
        m->body = NULL;
        m->is_undef = 1;
    }
}

/* Parse -D definition: name[=value] */
static void parse_define(TCCState *s, const char *str) {
    /* Find = */
    const char *eq = strchr(str, '=');
    char name[256];
    const char *val;
    if (eq) {
        int nlen = eq - str;
        if (nlen >= (int)sizeof(name)) nlen = sizeof(name)-1;
        strncpy(name, str, nlen);
        name[nlen] = 0;
        val = eq + 1;
    } else {
        strncpy(name, str, sizeof(name)-1);
        name[sizeof(name)-1] = 0;
        val = "1";
    }
    macro_define(s, name, val, NULL, 0, 0);
}

/* ============================================================
 * INCLUDE PATH MANAGEMENT
