static void add_include_path(TCCState *s, const char *path) {
    char **paths = tcc_realloc(s->include_paths, (s->nb_include_paths+1)*sizeof(char*));
    s->include_paths = paths;
    s->include_paths[s->nb_include_paths++] = tcc_strdup(path);
}

