    int tok;
    struct KwHash *next;
} KwHash;

static KwHash kw_hashtable[KW_HASH_SIZE];
static int kw_initialized = 0;

static int kw_hashfn(const char *s) {
    unsigned h = 5381;
    while (*s) h = (h*33)^(unsigned char)*s++;
    return h & KW_HASH_MASK;
}

static void kw_init(void) {
    for (int i = 0; kw_table[i].name; i++) {
        int h = kw_hashfn(kw_table[i].name);
        KwHash *e = malloc(sizeof(KwHash));
        e->name = kw_table[i].name;
        e->tok = kw_table[i].tok;
        e->next = kw_hashtable[h].next;
        kw_hashtable[h].next = e;
        if (!kw_hashtable[h].name) {
            kw_hashtable[h].name = kw_table[i].name;
            kw_hashtable[h].tok = kw_table[i].tok;
        }
    }
    kw_initialized = 1;
}

static int kw_lookup(const char *name) {
    int h = kw_hashfn(name);
    KwHash *e = &kw_hashtable[h];
    if (!e->name) return TOK_IDENT;
    do {
        if (!strcmp(e->name, name)) return e->tok;
        e = e->next;
    } while (e);
    return TOK_IDENT;
}

/* ============================================================
 * PREPROCESSOR
 * The preprocessor processes source files, handles macros,
 * includes, and conditional compilation.
 * ============================================================ */

/* Get current character and advance */
static void bs_adv(TCCState *s) {
    if (!s->bs) { s->ch = 0; return; }
    if (s->bs->idx >= s->bs->buf_len) {
        s->ch = 0;
        return;
    }
    s->ch = s->bs->buf[s->bs->idx++];
    if (s->ch == '\n') s->bs->line_num++;
}

/* Peek next char without advancing */
static int bs_peek(TCCState *s) {
    if (!s->bs || s->bs->idx >= s->bs->buf_len) return 0;
    return (unsigned char)s->bs->buf[s->bs->idx];
}

/* Push a new buffer (file or string) */
static void push_buffer(TCCState *s, const char *buf, int len, const char *filename, int is_string) {
    BufferState *bs = calloc(1, sizeof(BufferState));
    bs->buf = buf;
    bs->buf_len = len;
    bs->idx = 0;
    bs->filename = filename ? tcc_strdup(filename) : NULL;
    bs->line_num = 1;
    bs->is_string = is_string;
    bs->iflevel = s->iflevel;
    bs->prev = s->bs;
    s->bs = bs;
    /* Initialize current char */
    if (len > 0) {
        s->ch = buf[0];
        bs->idx = 1;
    } else {
        s->ch = 0;
    }
}

static void pop_buffer(TCCState *s) {
    if (!s->bs) return;
    BufferState *old = s->bs;
    s->bs = old->prev;
    free(old->filename);
    free(old);
    if (s->bs) {
        /* Restore current char */
        if (s->bs->idx > 0 && s->bs->idx <= s->bs->buf_len) {
            /* current char is already at s->ch from before push */
        }
    } else {
        s->ch = 0;
    }
}

/* Skip whitespace (not newlines) */
static void skip_spaces(TCCState *s) {
    while (s->ch == ' ' || s->ch == '\t' || s->ch == '\r' || s->ch == '\v' || s->ch == '\f') {
        bs_adv(s);
    }
}

/* Skip to end of line (for #if/#else/#endif processing) */
static void skip_line(TCCState *s) {
    while (s->ch && s->ch != '\n') bs_adv(s);
}

/* Skip block comment */
static void skip_block_comment(TCCState *s) {
    while (s->ch) {
        if (s->ch == '*') {
            bs_adv(s);
            if (s->ch == '/') {
                bs_adv(s);
                return;
            }
        } else {
            bs_adv(s);
        }
    }
    /* Unterminated comment */
    tcc_error(s, "unterminated comment");
}

/* Read until end of line, return new string */
static char *read_line(TCCState *s) {
    CString cs;
    memset(&cs, 0, sizeof(cs));
    /* Skip leading whitespace */
    while (s->ch == ' ' || s->ch == '\t') bs_adv(s);
    while (s->ch && s->ch != '\n') {
        /* Handle line continuation */
        if (s->ch == '\\' && bs_peek(s) == '\n') {
            bs_adv(s); bs_adv(s); /* skip \ and \n */
            continue;
        }
        /* Handle block comments */
        if (s->ch == '/' && bs_peek(s) == '*') {
            bs_adv(s); bs_adv(s);
            skip_block_comment(s);
            cstr_ccat(&cs, ' ');
            continue;
        }
        if (s->ch == '/' && bs_peek(s) == '/') {
            skip_line(s);
            break;
        }
        cstr_ccat(&cs, s->ch);
        bs_adv(s);
    }
    return cs.buf ? cs.buf : tcc_strdup("");
}

/* Find a file in include paths */
static int find_include_file(TCCState *s, const char *filename, int is_sys,
                              const char *current_file, char *result, int result_size) {
    /* Absolute path */
    if (filename[0] == '/') {
        if (access(filename, R_OK) == 0) {
            snprintf(result, result_size, "%s", filename);
            return 1;
        }
        return 0;
    }

    /* For "filename" (non-system), first check current directory */
    if (!is_sys && current_file) {
        /* Get directory of current file */
        char dir[512];
        const char *slash = strrchr(current_file, '/');
        if (slash) {
            int dlen = slash - current_file;
            if (dlen >= (int)sizeof(dir)) dlen = sizeof(dir)-1;
            strncpy(dir, current_file, dlen);
            dir[dlen] = 0;
            snprintf(result, result_size, "%s/%s", dir, filename);
            if (access(result, R_OK) == 0) return 1;
        } else {
            snprintf(result, result_size, "%s", filename);
            if (access(result, R_OK) == 0) return 1;
        }
    }

    /* Search include paths */
    if (!is_sys) {
        for (int i = 0; i < s->nb_include_paths; i++) {
            snprintf(result, result_size, "%s/%s", s->include_paths[i], filename);
            if (access(result, R_OK) == 0) return 1;
        }
    }

    /* Search system include paths */
    for (int i = 0; i < s->nb_sys_include_paths; i++) {
        snprintf(result, result_size, "%s/%s", s->sys_include_paths[i], filename);
        if (access(result, R_OK) == 0) return 1;
    }

    return 0;
}

/* Check if file was included with #pragma once */
static int is_pragma_once(TCCState *s, const char *filename) {
    for (int i = 0; i < s->nb_pragma_once_files; i++) {
        if (!strcmp(s->pragma_once_files[i], filename)) return 1;
    }
    return 0;
}

static void add_pragma_once(TCCState *s, const char *filename) {
    s->pragma_once_files = tcc_realloc(s->pragma_once_files,
                                        (s->nb_pragma_once_files+1)*sizeof(char*));
    s->pragma_once_files[s->nb_pragma_once_files++] = tcc_strdup(filename);
}

/* Read a file into memory */
static char *read_file(const char *filename, int *size_out) {
    FILE *f = fopen(filename, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(size + 2);
    if (!buf) { fclose(f); return NULL; }
    fread(buf, 1, size, f);
    fclose(f);
    buf[size] = '\n';
    buf[size+1] = 0;
    if (size_out) *size_out = size + 1;
    return buf;
}

/* ============================================================
 * PREPROCESSOR: MACRO EXPANSION
 * The macro expander handles:
 * - Object-like macros
 * - Function-like macros
 * - # and ## operators
 * - __VA_ARGS__
 * ============================================================ */

/* Simple macro expander - returns expanded text */
static char *macro_expand(TCCState *s, const char *text, int depth);

static char *expand_macro_args(TCCState *s, Macro *m, const char *args_start, int depth);

/* Collect function macro arguments */
static int collect_macro_args(const char *p, char **args, int max_args, int *nb_args_out, int is_variadic) {
    /* p should point to '(' */
    if (*p != '(') return -1;
    p++;
    *nb_args_out = 0;
    /* Empty args */
    while (*p == ' ' || *p == '\t') p++;
    if (*p == ')') {
        *nb_args_out = 0;
        return (int)(p - (p - 1)); /* return consumed */
    }

    CString cur;
    int depth = 0;
    int arg_idx = 0;

    memset(&cur, 0, sizeof(cur));
    const char *start = p;
    int in_str = 0, in_char = 0;

    while (*p) {
        char c = *p;
        if (!in_str && !in_char) {
            if (c == '(') depth++;
            else if (c == ')') {
                if (depth == 0) {
                    /* End of args */
                    if (arg_idx < max_args) {
                        /* Trim trailing spaces */
                        while (cur.len > 0 && (cur.buf[cur.len-1] == ' ' || cur.buf[cur.len-1] == '\t')) cur.len--;
                        if (cur.buf) cur.buf[cur.len] = 0;
                        args[arg_idx++] = cur.buf ? tcc_strdup(cur.buf) : tcc_strdup("");
                        cstr_reset(&cur);
                    }
                    *nb_args_out = arg_idx;
                    p++;
                    return (int)(p - start + 1); /* +1 for opening ( */
                } else depth--;
            } else if (c == ',' && depth == 0 && (!is_variadic || arg_idx < max_args - 1)) {
                /* New argument */
                if (arg_idx < max_args) {
                    while (cur.len > 0 && (cur.buf[cur.len-1] == ' ' || cur.buf[cur.len-1] == '\t')) cur.len--;
                    if (cur.buf) cur.buf[cur.len] = 0;
                    args[arg_idx++] = cur.buf ? tcc_strdup(cur.buf) : tcc_strdup("");
                    cstr_reset(&cur);
                }
                p++;
                /* Skip leading spaces */
                while (*p == ' ' || *p == '\t') p++;
                continue;
            } else if (c == '"') in_str = 1;
            else if (c == '\'') in_char = 1;
        } else if (in_str) {
            if (c == '\\') { cstr_ccat(&cur, c); p++; if (*p) { cstr_ccat(&cur, *p); p++; } continue; }
            if (c == '"') in_str = 0;
        } else if (in_char) {
            if (c == '\\') { cstr_ccat(&cur, c); p++; if (*p) { cstr_ccat(&cur, *p); p++; } continue; }
            if (c == '\'') in_char = 0;
        }
        cstr_ccat(&cur, c);
        p++;
    }
    cstr_reset(&cur);
    return -1; /* error: no closing ) */
}

/* Stringify a macro argument */
static char *stringify_arg(const char *arg) {
    CString cs;
    memset(&cs, 0, sizeof(cs));
    cstr_ccat(&cs, '"');
    for (const char *p = arg; *p; p++) {
        if (*p == '\\' || *p == '"') cstr_ccat(&cs, '\\');
        cstr_ccat(&cs, *p);
    }
    cstr_ccat(&cs, '"');
    return cs.buf ? cs.buf : tcc_strdup("\"\"");
}

static char *macro_expand(TCCState *s, const char *text, int depth) {
    if (depth > 50) return tcc_strdup(text); /* prevent infinite recursion */

    CString result;
    memset(&result, 0, sizeof(result));
    const char *p = text;

    while (*p) {
        /* Skip whitespace */
        if (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') {
            cstr_ccat(&result, *p++);
            continue;
        }

        /* String literals */
        if (*p == '"') {
            cstr_ccat(&result, *p++);
            while (*p && *p != '"') {
                if (*p == '\\' && *(p+1)) { cstr_ccat(&result, *p++); }
                cstr_ccat(&result, *p++);
            }
            if (*p) cstr_ccat(&result, *p++);
            continue;
        }

        /* Char literals */
        if (*p == '\'') {
            cstr_ccat(&result, *p++);
            while (*p && *p != '\'') {
                if (*p == '\\' && *(p+1)) { cstr_ccat(&result, *p++); }
                cstr_ccat(&result, *p++);
            }
            if (*p) cstr_ccat(&result, *p++);
            continue;
        }

        /* Identifiers - check for macros */
        if (is_idstart[(unsigned char)*p]) {
            CString name;
            memset(&name, 0, sizeof(name));
            while (is_idstart[(unsigned char)*p] || (*p >= '0' && *p <= '9')) {
                cstr_ccat(&name, *p++);
            }
            /* Check if it's a macro */
            Macro *m = name.buf ? macro_find(s, name.buf) : NULL;
            if (!m || m->is_undef) {
                /* Not a macro, output as-is */
                if (name.buf) cstr_cat(&result, name.buf, -1);
            } else if (m->params == NULL) {
                /* Object-like macro */
                char *expanded = macro_expand(s, m->body, depth+1);
                if (expanded) { cstr_cat(&result, expanded, -1); free(expanded); }
            } else {
                /* Function-like macro - need ( */
                const char *q = p;
                while (*q == ' ' || *q == '\t') q++;
                if (*q == '(') {
                    /* Collect arguments */
                    char *args[128];
                    int nb_args = 0;
                    int consumed = collect_macro_args(q, args, 128, &nb_args, m->is_variadic);
                    if (consumed > 0) {
                        p = q + consumed;
                        /* Expand macro with args */
                        char *expanded = expand_macro_args(s, m, NULL, depth+1);
                        /* Build body with arg substitution */
                        CString body;
                        memset(&body, 0, sizeof(body));
                        const char *bp = m->body;
                        while (*bp) {
                            if (*bp == '#' && *(bp+1) == '#') {
                                /* Token paste */
                                bp += 2;
                                while (*bp == ' ' || *bp == '\t') bp++;
                                /* Remove trailing spaces from result */
                                while (body.len > 0 && (body.buf[body.len-1] == ' ' || body.buf[body.len-1] == '\t'))
                                    body.len--;
                                if (body.buf) body.buf[body.len] = 0;
                                continue;
                            }
                            if (*bp == '#' && is_idstart[(unsigned char)*(bp+1)]) {
                                /* Stringify */
                                bp++;
                                CString argname;
                                memset(&argname, 0, sizeof(argname));
                                while (is_idstart[(unsigned char)*bp] || (*bp >= '0' && *bp <= '9')) {
                                    cstr_ccat(&argname, *bp++);
                                }
                                /* Find arg index */
                                int found = -1;
                                for (int i = 0; i < m->nb_params; i++) {
                                    if (argname.buf && !strcmp(m->params[i], argname.buf)) { found = i; break; }
                                }
                                if (found >= 0 && found < nb_args) {
                                    char *str = stringify_arg(args[found]);
                                    cstr_cat(&body, str, -1);
                                    free(str);
                                } else if (!strcmp("__VA_ARGS__", argname.buf ? argname.buf : "")) {
                                    /* Stringify variadic args */
                                    if (nb_args > m->nb_params) {
                                        char *str = stringify_arg(args[nb_args-1]);
                                        cstr_cat(&body, str, -1);
                                        free(str);
                                    }
                                }
                                cstr_reset(&argname);
                                continue;
                            }
                            if (is_idstart[(unsigned char)*bp]) {
                                CString pname;
                                memset(&pname, 0, sizeof(pname));
                                while (is_idstart[(unsigned char)*bp] || (*bp >= '0' && *bp <= '9')) {
                                    cstr_ccat(&pname, *bp++);
                                }
                                /* Check if it's a parameter */
                                int found = -1;
                                if (pname.buf) {
                                    for (int i = 0; i < m->nb_params; i++) {
                                        if (!strcmp(m->params[i], pname.buf)) { found = i; break; }
                                    }
                                    if (!strcmp(pname.buf, "__VA_ARGS__") && m->is_variadic) {
                                        /* Combine variadic args */
                                        for (int i = m->nb_params; i < nb_args; i++) {
                                            if (i > m->nb_params) cstr_ccat(&body, ',');
                                            char *expanded2 = macro_expand(s, args[i], depth+1);
                                            if (expanded2) { cstr_cat(&body, expanded2, -1); free(expanded2); }
                                        }
                                        cstr_reset(&pname);
                                        continue;
                                    }
                                }
                                if (found >= 0 && found < nb_args) {
                                    char *expanded2 = macro_expand(s, args[found], depth+1);
                                    if (expanded2) { cstr_cat(&body, expanded2, -1); free(expanded2); }
                                } else if (found >= nb_args) {
                                    /* Missing arg - empty */
                                } else {
                                    /* Not a param - output as-is (might be another macro) */
                                    if (pname.buf) cstr_cat(&body, pname.buf, -1);
                                }
                                cstr_reset(&pname);
                                continue;
                            }
                            cstr_ccat(&body, *bp++);
                        }
                        /* Expand the resulting body */
                        if (body.buf) {
                            char *final = macro_expand(s, body.buf, depth+1);
                            if (final) { cstr_cat(&result, final, -1); free(final); }
                            cstr_reset(&body);
                        }
                        /* Free args */
                        for (int i = 0; i < nb_args; i++) free(args[i]);
                        free(expanded);
                    } else {
                        /* Can't expand */
                        if (name.buf) cstr_cat(&result, name.buf, -1);
                    }
                } else {
                    /* Function-like macro without () - output as-is */
                    if (name.buf) cstr_cat(&result, name.buf, -1);
                }
            }
            cstr_reset(&name);
            continue;
        }

        /* Other characters */
        cstr_ccat(&result, *p++);
    }

    return result.buf ? result.buf : tcc_strdup("");
}

static char *expand_macro_args(TCCState *s, Macro *m, const char *args_str, int depth) {
    return tcc_strdup(m->body ? m->body : "");
}

