        while (s->ch == ' ' || s->ch == '\t') bs_adv(s);

        int is_sys = 0;
        CString filename;
        memset(&filename, 0, sizeof(filename));

        if (s->ch == '<') {
            is_sys = 1;
            bs_adv(s);
            while (s->ch && s->ch != '>') {
                cstr_ccat(&filename, s->ch);
                bs_adv(s);
            }
            if (s->ch == '>') bs_adv(s);
        } else if (s->ch == '"') {
            bs_adv(s);
            while (s->ch && s->ch != '"') {
                cstr_ccat(&filename, s->ch);
                bs_adv(s);
            }
            if (s->ch == '"') bs_adv(s);
        } else {
            /* Computed include - expand and re-parse */
            char *line = read_line(s);
            char *expanded = macro_expand(s, line, 0);
            /* Re-parse */
            const char *p = expanded;
            while (*p == ' ' || *p == '\t') p++;
            if (*p == '<') {
                is_sys = 1;
                p++;
                while (*p && *p != '>') cstr_ccat(&filename, *p++);
            } else if (*p == '"') {
                p++;
                while (*p && *p != '"') cstr_ccat(&filename, *p++);
            }
            free(line);
            free(expanded);
        }

        skip_line(s);

        if (filename.buf) {
            char found_path[1024];
            const char *cur_file = s->bs ? s->bs->filename : NULL;

            /* Check pragma once */
            char full_path[1024];
            if (find_include_file(s, filename.buf, is_sys, cur_file, full_path, sizeof(full_path))) {
                if (!is_pragma_once(s, full_path)) {
                    /* Track dependency */
                    if (s->gen_deps) {
                        da_add(&dep_files, tcc_strdup(full_path));
                    }

                    if (pp_out) {
                        /* In -E mode, output line directive */
                        if (s->pp_lineno_mode != 2) {
                            fprintf(pp_out, "# 1 \"%s\" 1\n", full_path);
                        }
                    }

                    process_include(s, full_path, is_sys, pp_out);

                    if (pp_out && s->pp_lineno_mode != 2) {
                        /* Restore line directive */
                        if (s->bs) {
                            fprintf(pp_out, "# %d \"%s\" 2\n",
                                    s->bs->line_num,
                                    s->bs->filename ? s->bs->filename : "");
                        }
                    }
                }
            } else {
                tcc_error(s, "include file '%s' not found", filename.buf);
            }
        }
        cstr_reset(&filename);

    } else if (!strcmp(dn, "if")) {
        char *expr = read_line(s);
        int result = pp_expr_true(s, expr);
        free(expr);
        if (s->iflevel < 255) {
            s->ifstack[s->iflevel].tok = TOK_PP_IF;
            s->ifstack[s->iflevel].had_true = result;
            s->ifstack[s->iflevel].skip = !result;
            s->iflevel++;
        }
    } else if (!strcmp(dn, "ifdef")) {
        while (s->ch == ' ' || s->ch == '\t') bs_adv(s);
        CString mname;
        memset(&mname, 0, sizeof(mname));
        while (is_idstart[(unsigned char)s->ch] || (s->ch >= '0' && s->ch <= '9')) {
            cstr_ccat(&mname, s->ch);
            bs_adv(s);
        }
        skip_line(s);
        int result = 0;
        if (mname.buf) {
            Macro *m = macro_find(s, mname.buf);
            result = (m && !m->is_undef);
        }
        cstr_reset(&mname);
        if (s->iflevel < 255) {
            s->ifstack[s->iflevel].tok = TOK_IFDEF;
            s->ifstack[s->iflevel].had_true = result;
            s->ifstack[s->iflevel].skip = !result;
            s->iflevel++;
        }
    } else if (!strcmp(dn, "ifndef")) {
        while (s->ch == ' ' || s->ch == '\t') bs_adv(s);
        CString mname;
        memset(&mname, 0, sizeof(mname));
        while (is_idstart[(unsigned char)s->ch] || (s->ch >= '0' && s->ch <= '9')) {
            cstr_ccat(&mname, s->ch);
            bs_adv(s);
        }
        skip_line(s);
        int result = 0;
        if (mname.buf) {
            Macro *m = macro_find(s, mname.buf);
            result = !(m && !m->is_undef);
        }
        cstr_reset(&mname);
        if (s->iflevel < 255) {
            s->ifstack[s->iflevel].tok = TOK_IFNDEF;
            s->ifstack[s->iflevel].had_true = result;
            s->ifstack[s->iflevel].skip = !result;
            s->iflevel++;
        }
    } else if (!strcmp(dn, "elif")) {
        if (s->iflevel <= 0) {
            tcc_error(s, "#elif without #if");
            skip_line(s);
        } else {
            char *expr = read_line(s);
            int lvl = s->iflevel - 1;
            if (s->ifstack[lvl].had_true) {
                s->ifstack[lvl].skip = 1;
            } else {
                int result = pp_expr_true(s, expr);
                s->ifstack[lvl].skip = !result;
                if (result) s->ifstack[lvl].had_true = 1;
            }
            free(expr);
        }
    } else if (!strcmp(dn, "else")) {
        skip_line(s);
        if (s->iflevel <= 0) {
            tcc_error(s, "#else without #if");
        } else {
            int lvl = s->iflevel - 1;
            s->ifstack[lvl].skip = s->ifstack[lvl].had_true;
        }
    } else if (!strcmp(dn, "endif")) {
        skip_line(s);
        if (s->iflevel <= 0) {
            tcc_error(s, "#endif without #if");
        } else {
            s->iflevel--;
        }
    } else if (!strcmp(dn, "error")) {
        char *msg = read_line(s);
        tcc_error(s, "#error %s", msg ? msg : "");
        free(msg);
    } else if (!strcmp(dn, "warning")) {
        char *msg = read_line(s);
        tcc_warning(s, "#warning %s", msg ? msg : "");
        free(msg);
    } else if (!strcmp(dn, "pragma")) {
        char *line = read_line(s);
        /* Handle #pragma once */
        if (line) {
            const char *p = line;
            while (*p == ' ' || *p == '\t') p++;
            if (strncmp(p, "once", 4) == 0 && (!p[4] || p[4] == ' ' || p[4] == '\t')) {
                if (s->bs && s->bs->filename) {
                    add_pragma_once(s, s->bs->filename);
                }
            }
            free(line);
        }
    } else if (!strcmp(dn, "line")) {
        char *line = read_line(s);
        /* # line N "filename" */
        if (line && s->bs) {
            char *p = line;
            while (*p == ' ' || *p == '\t') p++;
            if (isdigit(*p)) {
                s->bs->line_num = atoi(p) - 1;
                while (isdigit(*p)) p++;
                while (*p == ' ' || *p == '\t') p++;
                if (*p == '"') {
                    p++;
                    CString fn;
                    memset(&fn, 0, sizeof(fn));
                    while (*p && *p != '"') cstr_ccat(&fn, *p++);
                    if (fn.buf) {
                        free(s->bs->filename);
                        s->bs->filename = tcc_strdup(fn.buf);
                        cstr_reset(&fn);
                    }
                }
            }
            free(line);
        }
    } else {
        /* Unknown directive - warn if -Wunsupported */
        skip_line(s);
    }

    cstr_reset(&dname);
}

/* Skip a block of code (for false #if branches) */
static void pp_skip_block(TCCState *s) {
    int depth = 1;
    while (s->ch && depth > 0) {
        /* Find next '#' at start of line */
        if (s->ch == '\n') {
            bs_adv(s);
            while (s->ch == ' ' || s->ch == '\t') bs_adv(s);
            if (s->ch == '#') {
                bs_adv(s);
                while (s->ch == ' ' || s->ch == '\t') bs_adv(s);
                /* Read directive name */
                CString dn;
                memset(&dn, 0, sizeof(dn));
                while (is_idstart[(unsigned char)s->ch]) {
                    cstr_ccat(&dn, s->ch);
                    bs_adv(s);
                }
                const char *d = dn.buf ? dn.buf : "";
                if (!strcmp(d, "if") || !strcmp(d, "ifdef") || !strcmp(d, "ifndef")) {
                    depth++;
                } else if (!strcmp(d, "endif")) {
                    depth--;
                    if (depth == 0) {
                        if (s->iflevel > 0) s->iflevel--;
                    }
                } else if (depth == 1 && (!strcmp(d, "else") || !strcmp(d, "elif"))) {
                    /* Handle else/elif at current depth */
                    if (!strcmp(d, "elif")) {
                        char *expr = read_line(s);
                        int lvl = s->iflevel - 1;
                        if (lvl >= 0 && !s->ifstack[lvl].had_true) {
                            int result = pp_expr_true(s, expr);
                            s->ifstack[lvl].skip = !result;
                            if (result) s->ifstack[lvl].had_true = 1;
                        } else if (lvl >= 0) {
                            s->ifstack[lvl].skip = 1;
                        }
                        free(expr);
                        cstr_reset(&dn);
                        return;
                    } else { /* else */
                        skip_line(s);
                        int lvl = s->iflevel - 1;
                        if (lvl >= 0) {
                            s->ifstack[lvl].skip = s->ifstack[lvl].had_true;
                        }
                        cstr_reset(&dn);
                        return;
                    }
                }
                cstr_reset(&dn);
                skip_line(s);
            }
        } else {
            bs_adv(s);
        }
    }
}

