/* ============================================================
 * PREPROCESSOR: MAIN LOOP
 * Process source text and produce preprocessed output
 * ============================================================ */

/* Process a file or buffer through the preprocessor.
 * If pp_out != NULL: write preprocessed text to pp_out
 * Otherwise: feed tokens to the parser
 */
static int process_include(TCCState *s, const char *filename, int is_sys, FILE *pp_out) {
    int flen;
    char *buf = read_file(filename, &flen);
    if (!buf) {
        tcc_error(s, "cannot open file '%s'", filename);
        return -1;
    }

    if (s->verbose >= 2) {
        fprintf(stderr, "-> %s\n", filename);
    }

    push_buffer(s, buf, flen, filename, 0);

    /* Main preprocessing loop */
    preprocess_buffer(s, pp_out, 0);

    pop_buffer(s);
    free(buf);
    return 0;
}

/* The main preprocessing loop.
 * Reads source text and:
 * - Expands macros
 * - Processes directives (#define, #include, etc.)
 * - Outputs preprocessed text (if pp_out != NULL)
 * - Or feeds tokens to parser
 */
static void preprocess_buffer(TCCState *s, FILE *pp_out, int in_macro) {
    int at_line_start = 1;
    int last_output_line = -1;
    const char *last_output_file = NULL;

    while (s->ch) {
        /* Handle #if block skipping */
        if (s->iflevel > 0 && s->ifstack[s->iflevel-1].skip) {
            /* We're in a false #if block */
            /* Need to scan for #else/#elif/#endif */
            if (at_line_start && s->ch == '#') {
                bs_adv(s);
                while (s->ch == ' ' || s->ch == '\t') bs_adv(s);
                CString dn;
                memset(&dn, 0, sizeof(dn));
                while (is_idstart[(unsigned char)s->ch]) {
                    cstr_ccat(&dn, s->ch);
                    bs_adv(s);
                }
                const char *d = dn.buf ? dn.buf : "";
                if (!strcmp(d, "if") || !strcmp(d, "ifdef") || !strcmp(d, "ifndef")) {
                    /* Nested if - push */
                    if (s->iflevel < 255) {
                        s->ifstack[s->iflevel].skip = 1;
                        s->ifstack[s->iflevel].had_true = 0;
                        s->iflevel++;
                    }
                    skip_line(s);
                } else if (!strcmp(d, "endif")) {
                    skip_line(s);
                    if (s->iflevel > 0) s->iflevel--;
                } else if (!strcmp(d, "elif") || !strcmp(d, "else")) {
                    /* Process this to potentially leave skip mode */
                    s->ch = '#'; /* re-process with handle_directive */
                    /* Actually, put back the directive name */
                    /* This is tricky - let's just call handle_directive directly */
                    /* We need to undo what we did */
                    /* For simplicity, rebuild the directive line */
                    if (!strcmp(d, "elif")) {
                        char *expr = read_line(s);
                        int lvl = s->iflevel - 1;
                        if (lvl >= 0 && !s->ifstack[lvl].had_true) {
                            int result = pp_expr_true(s, expr);
                            s->ifstack[lvl].skip = !result;
                            if (result) s->ifstack[lvl].had_true = 1;
                        } else if (lvl >= 0) {
                            s->ifstack[lvl].skip = 1;
                        }
                        free(expr);
                    } else {
                        skip_line(s);
                        int lvl = s->iflevel - 1;
                        if (lvl >= 0) {
                            s->ifstack[lvl].skip = s->ifstack[lvl].had_true;
                        }
                    }
                } else {
                    skip_line(s);
                }
                cstr_reset(&dn);
                at_line_start = 1;
                if (s->ch == '\n') { bs_adv(s); }
                continue;
            }
            /* Skip this character */
            if (s->ch == '\n') {
                bs_adv(s);
                at_line_start = 1;
            } else {
                bs_adv(s);
                at_line_start = 0;
            }
            continue;
        }

        /* Process character */
        char c = s->ch;

        /* Newline */
        if (c == '\n') {
            if (pp_out) fprintf(pp_out, "\n");
            bs_adv(s);
            at_line_start = 1;
            continue;
        }

        at_line_start = (c == '#' && at_line_start);

        /* Line continuation */
        if (c == '\\') {
            int next = bs_peek(s);
            if (next == '\n') {
                bs_adv(s); bs_adv(s); /* skip \ and \n */
                at_line_start = 0;
                continue;
            }
        }

        /* Preprocessor directive */
        if (c == '#') {
            /* Check if this is at start of line (after whitespace) */
            /* Actually at_line_start was set above */
            bs_adv(s); /* consume # */
            handle_directive(s, pp_out);
            at_line_start = 1;
            /* Consume newline after directive */
            if (s->ch == '\n') {
                if (pp_out) fprintf(pp_out, "\n");
                bs_adv(s);
            }
            continue;
        }

        /* Not in a directive context anymore */
        at_line_start = 0;

        /* Comments */
        if (c == '/' && (bs_peek(s) == '/' || bs_peek(s) == '*')) {
            int next = bs_peek(s);
            bs_adv(s); bs_adv(s);
            if (next == '/') {
                /* Line comment */
                if (pp_out) fprintf(pp_out, " ");
                while (s->ch && s->ch != '\n') {
                    if (s->ch == '\\' && bs_peek(s) == '\n') {
                        bs_adv(s); bs_adv(s);
                    } else {
                        bs_adv(s);
                    }
                }
            } else {
                /* Block comment */
                if (pp_out) fprintf(pp_out, " ");
                skip_block_comment(s);
            }
            continue;
        }

        /* String literal */
        if (c == '"' || (c == 'L' && bs_peek(s) == '"') ||
            (c == 'u' && bs_peek(s) == '"') ||
            (c == 'U' && bs_peek(s) == '"') ||
            (c == 'u' && bs_peek(s) == '8') ) {
            if (pp_out) {
                /* Check for line change */
                if (s->bs && (last_output_file != s->bs->filename || 
                              last_output_line != s->bs->line_num)) {
                    /* Don't insert line directives in middle of code */
                }
            }
            if (pp_out) fputc(c, pp_out);
            bs_adv(s);
            /* Handle u8 prefix */
            if (c == 'u' && s->ch == '8') {
                if (pp_out) fputc('8', pp_out);
                bs_adv(s);
            }
            if (s->ch == '"') {
                if (pp_out) fputc('"', pp_out);
                bs_adv(s);
                /* Copy string content */
                while (s->ch && s->ch != '"') {
                    if (s->ch == '\n') break;
                    if (pp_out) fputc(s->ch, pp_out);
                    if (s->ch == '\\') {
                        bs_adv(s);
                        if (pp_out) fputc(s->ch, pp_out);
                    }
                    bs_adv(s);
                }
                if (s->ch == '"') {
                    if (pp_out) fputc('"', pp_out);
                    bs_adv(s);
                }
            }
            continue;
        }

        /* Char literal */
        if (c == '\'' || (c == 'L' && bs_peek(s) == '\'')) {
            if (pp_out) fputc(c, pp_out);
            bs_adv(s);
            if (s->ch == '\'') {
                if (pp_out) fputc('\'', pp_out);
                bs_adv(s);
                while (s->ch && s->ch != '\'') {
                    if (s->ch == '\n') break;
                    if (pp_out) fputc(s->ch, pp_out);
                    if (s->ch == '\\') {
                        bs_adv(s);
                        if (pp_out) fputc(s->ch, pp_out);
                    }
                    bs_adv(s);
                }
                if (s->ch == '\'') {
                    if (pp_out) fputc('\'', pp_out);
                    bs_adv(s);
                }
            }
            continue;
        }

        /* Identifier or keyword - check for macro expansion */
        if (is_idstart[(unsigned char)c]) {
            CString word;
            memset(&word, 0, sizeof(word));
            while (is_idstart[(unsigned char)s->ch] || (s->ch >= '0' && s->ch <= '9')) {
                cstr_ccat(&word, s->ch);
                bs_adv(s);
            }

            if (!word.buf) { continue; }

            /* Check for special macros */
            if (!strcmp(word.buf, "__FILE__")) {
                if (pp_out) {
                    fprintf(pp_out, "\"%s\"", s->bs && s->bs->filename ? s->bs->filename : "");
                }
                cstr_reset(&word);
                continue;
            }
            if (!strcmp(word.buf, "__LINE__")) {
                if (pp_out) {
                    fprintf(pp_out, "%d", s->bs ? s->bs->line_num : 0);
                }
                cstr_reset(&word);
                continue;
            }
            if (!strcmp(word.buf, "__BASE_FILE__")) {
                if (pp_out) {
                    /* Find outermost file */
                    BufferState *bs = s->bs;
                    while (bs->prev) bs = bs->prev;
                    fprintf(pp_out, "\"%s\"", bs->filename ? bs->filename : "");
                }
                cstr_reset(&word);
                continue;
            }

            /* Try macro expansion */
            Macro *m = macro_find(s, word.buf);
            if (m && !m->is_undef) {
                if (m->params == NULL) {
                    /* Object-like macro */
                    char *expanded = macro_expand(s, m->body, 0);
                    /* Push expanded text as a new buffer */
                    if (expanded && *expanded) {
                        push_buffer(s, expanded, strlen(expanded), NULL, 1);
                        free(expanded);
                    } else {
                        free(expanded);
                    }
                } else {
                    /* Function-like macro - check for ( */
                    /* Skip whitespace */
                    while (s->ch == ' ' || s->ch == '\t') bs_adv(s);
                    if (s->ch == '(') {
                        /* Collect arguments from current buffer */
                        /* We need to read the args from the current buffer */
                        CString args_str;
                        memset(&args_str, 0, sizeof(args_str));
                        cstr_ccat(&args_str, '(');
                        bs_adv(s); /* skip ( */
                        int depth2 = 1;
                        while (s->ch && depth2 > 0) {
                            if (s->ch == '(') depth2++;
                            else if (s->ch == ')') depth2--;
                            if (depth2 > 0) cstr_ccat(&args_str, s->ch);
                            else cstr_ccat(&args_str, ')');
                            if (depth2 > 0) bs_adv(s);
                            else bs_adv(s);
                        }
                        /* Now expand */
                        char *args2[128];
                        int nb_args2 = 0;
                        char *body_copy = NULL;

                        if (args_str.buf) {
                            collect_macro_args(args_str.buf, args2, 128, &nb_args2, m->is_variadic);
                        }

                        /* Build expanded body */
                        CString exp_body;
                        memset(&exp_body, 0, sizeof(exp_body));

                        /* Do argument substitution in macro body */
                        const char *bp = m->body;
                        while (bp && *bp) {
                            if (*bp == '#' && *(bp+1) == '#') {
                                /* Token paste - remove space */
                                bp += 2;
                                while (*bp == ' ' || *bp == '\t') bp++;
                                /* Remove trailing whitespace */
                                while (exp_body.len > 0 && (exp_body.buf[exp_body.len-1] == ' ' || exp_body.buf[exp_body.len-1] == '\t'))
                                    exp_body.len--;
                                if (exp_body.buf) exp_body.buf[exp_body.len] = 0;
                                continue;
                            }
                            if (*bp == '#' && is_idstart[(unsigned char)*(bp+1)]) {
                                bp++;
                                CString aname;
                                memset(&aname, 0, sizeof(aname));
                                while (is_idstart[(unsigned char)*bp] || (*bp >= '0' && *bp <= '9')) {
                                    cstr_ccat(&aname, *bp++);
                                }
                                int ai = -1;
                                if (aname.buf) {
                                    for (int i = 0; i < m->nb_params; i++) {
                                        if (!strcmp(m->params[i], aname.buf)) { ai = i; break; }
                                    }
                                }
                                if (ai >= 0 && ai < nb_args2) {
                                    char *str = stringify_arg(args2[ai]);
                                    cstr_cat(&exp_body, str, -1);
                                    free(str);
                                }
                                cstr_reset(&aname);
                                continue;
                            }
                            if (is_idstart[(unsigned char)*bp]) {
                                CString pn;
                                memset(&pn, 0, sizeof(pn));
                                while (is_idstart[(unsigned char)*bp] || (*bp >= '0' && *bp <= '9')) cstr_ccat(&pn, *bp++);
                                int ai = -1;
                                if (pn.buf) {
                                    for (int i = 0; i < m->nb_params; i++) {
                                        if (!strcmp(m->params[i], pn.buf)) { ai = i; break; }
                                    }
                                    if (m->is_variadic && !strcmp("__VA_ARGS__", pn.buf)) {
                                        /* Combine variadic args */
                                        for (int i = m->nb_params; i < nb_args2; i++) {
                                            if (i > m->nb_params) cstr_ccat(&exp_body, ',');
                                            if (args2[i]) {
                                                char *earg = macro_expand(s, args2[i], 0);
                                                cstr_cat(&exp_body, earg, -1);
                                                free(earg);
                                            }
                                        }
                                        cstr_reset(&pn);
                                        continue;
                                    }
                                }
                                if (ai >= 0 && ai < nb_args2) {
                                    char *earg = macro_expand(s, args2[ai] ? args2[ai] : "", 0);
                                    cstr_cat(&exp_body, earg, -1);
                                    free(earg);
                                } else {
                                    if (pn.buf) cstr_cat(&exp_body, pn.buf, -1);
                                }
                                cstr_reset(&pn);
                                continue;
                            }
                            cstr_ccat(&exp_body, *bp++);
                        }

                        /* Expand the result */
                        if (exp_body.buf && *exp_body.buf) {
                            char *final = macro_expand(s, exp_body.buf, 0);
                            if (final && *final) {
                                push_buffer(s, final, strlen(final), NULL, 1);
                            }
                            free(final);
                        }
                        cstr_reset(&exp_body);
                        cstr_reset(&args_str);
                        for (int i = 0; i < nb_args2; i++) free(args2[i]);
                    } else {
                        /* No (, output as-is */
                        if (pp_out) fprintf(pp_out, "%s", word.buf);
                    }
                }
            } else {
                /* Not a macro, output as-is */
                if (pp_out) fprintf(pp_out, "%s", word.buf);
            }
