                        if (exp_body.buf && *exp_body.buf) {
                            char *final = macro_expand(s, exp_body.buf, 0);
                            if (final && *final) {
                                push_buffer(s, final, strlen(final), NULL, 1);
                            }
                            free(final);
                        }
