            if (s->ch == '\n') {
                if (pp_out) fprintf(pp_out, "\n");
                bs_adv(s);
            }
            continue;
        }

        /* Not in a directive context anymore */
        at_line_start = 0;

        /* Comments */
        if (c == '/' && (bs_peek(s) == '/' || bs_peek(s) == '*')) {
            int next = bs_peek(s);
            bs_adv(s); bs_adv(s);
            if (next == '/') {
