        if (c == '"' || (c == 'L' && bs_peek(s) == '"') ||
            (c == 'u' && bs_peek(s) == '"') ||
            (c == 'U' && bs_peek(s) == '"') ||
            (c == 'u' && bs_peek(s) == '8') ) {
