                        /* We need to read the args from the current buffer */
                        CString args_str;
                        memset(&args_str, 0, sizeof(args_str));
                        cstr_ccat(&args_str, '(');
                        bs_adv(s); /* skip ( */
                        int depth2 = 1;
                        while (s->ch && depth2 > 0) {
                            if (s->ch == '(') depth2++;
                            else if (s->ch == ')') depth2--;
                            if (depth2 > 0) cstr_ccat(&args_str, s->ch);
                            else cstr_ccat(&args_str, ')');
                            if (depth2 > 0) bs_adv(s);
                            else bs_adv(s);
                        }
