                                while (is_idstart[(unsigned char)*bp] || (*bp >= '0' && *bp <= '9')) {
                                    cstr_ccat(&aname, *bp++);
                                }
                                int ai = -1;
                                if (aname.buf) {
                                    for (int i = 0; i < m->nb_params; i++) {
                                        if (!strcmp(m->params[i], aname.buf)) { ai = i; break; }
