/* ============================================================
 * ELF WRITER
 * Writes ELF object files and executables
 * ============================================================ */

/* ELF string table management */
#define SHN_UNDEF  0
#define SHN_ABS    0xfff1
#define SHN_COMMON 0xfff2

/* ELF relocation types for x86_64 */
#define R_X86_64_NONE     0
#define R_X86_64_64       1   /* Direct 64 bit */
#define R_X86_64_PC32     2   /* PC relative 32 bit signed */
#define R_X86_64_GOT32    3   /* 32 bit GOT entry */
#define R_X86_64_PLT32    4   /* 32 bit PLT address */
#define R_X86_64_COPY     5   /* Copy symbol at runtime */
#define R_X86_64_GLOB_DAT 6   /* Create GOT entry */
#define R_X86_64_JUMP_SLOT 7  /* Create PLT entry */
#define R_X86_64_RELATIVE 8   /* Adjust by program base */
#define R_X86_64_GOTPCREL 9   /* 32 bit signed PC relative offset to GOT */
#define R_X86_64_32      10   /* Direct 32 bit zero extended */
#define R_X86_64_32S     11   /* Direct 32 bit sign extended */

/* Compilation unit - holds all data for one object file */
typedef struct CompUnit {
    Section *text;      /* .text section */
    Section *data;      /* .data section */
    Section *data_ro;   /* .data.ro section */
    Section *bss;       /* .bss section */
    Section *symtab;    /* .symtab section */
    Section *strtab;    /* .strtab section */
    Section *shstrtab;  /* .shstrtab section */
    Section *eh_frame;  /* .eh_frame section */
    Section *rela_text; /* .rela.text section */
    Section *rela_data; /* .rela.data section */
    Section *rela_data_ro; /* .rela.data.ro section */
    Section *rela_eh_frame; /* .rela.eh_frame section */
    char *filename;     /* source filename */
    SymTable syms;      /* symbol table */
    int nb_syms;        /* number of symbols in ELF symtab */
} CompUnit;

static CompUnit *cu_new(const char *filename) {
    CompUnit *cu = calloc(1, sizeof(CompUnit));
    cu->text     = new_section(".text",     SHT_PROGBITS, SHF_ALLOC|SHF_EXECINSTR);
    cu->data     = new_section(".data",     SHT_PROGBITS, SHF_ALLOC|SHF_WRITE);
    cu->data_ro  = new_section(".data.ro",  SHT_PROGBITS, SHF_ALLOC);
    cu->bss      = new_section(".bss",      SHT_NOBITS,   SHF_ALLOC|SHF_WRITE);
    cu->symtab   = new_section(".symtab",   SHT_SYMTAB,   0);
    cu->strtab   = new_section(".strtab",   SHT_STRTAB,   0);
    cu->shstrtab = new_section(".shstrtab", SHT_STRTAB,   0);
    cu->eh_frame = new_section(".eh_frame", SHT_PROGBITS, SHF_ALLOC);

    cu->text->sh_addralign = 8;
    cu->data->sh_addralign = 8;
    cu->data_ro->sh_addralign = 8;
    cu->bss->sh_addralign = 8;
    cu->symtab->sh_addralign = 8;
    cu->symtab->sh_entsize = sizeof(Elf64_Sym);
    cu->strtab->sh_addralign = 1;
    cu->eh_frame->sh_addralign = 8;

    if (filename) cu->filename = tcc_strdup(filename);

    /* Init strtab with null byte */
    section_put1(cu->strtab, 0);
    /* Init shstrtab with null byte */
    section_put1(cu->shstrtab, 0);

    return cu;
}

/* Add a relocation entry */
static void cu_add_rela(Section **rela_sec_ptr, const char *name, Section *target,
                         int offset, int sym_idx, int type, int64_t addend) {
    if (!*rela_sec_ptr) {
        char rela_name[80];
        snprintf(rela_name, sizeof(rela_name), ".rela%s", target->name);
        *rela_sec_ptr = new_section(rela_name, SHT_RELA, SHF_INFO_LINK);
