 * CODE GENERATOR - x86_64
 * Generates x86_64 machine code into the .text section
 * ============================================================ */

/* Code generation state */
typedef struct CodeGen {
    CompUnit *cu;       /* current compilation unit */
    int func_start;     /* offset of current function start */
    int stack_size;     /* current function's stack frame size */
    int loc;            /* current local variable offset (negative from rbp) */
    int frame_size_patch; /* offset to patch the frame size */
    char *func_name;    /* current function name */
    int return_label;   /* patch list for return jumps */
    /* Jump labels - linked list of patch locations */
    int *label_defs;    /* label definitions (offset in .text) */
    int *label_refs;    /* label reference lists (patch locations) */
    int nb_labels_cg;   /* number of labels */
    int max_labels;
    Section *rela_text; /* .rela.text section */
    Section *rela_eh;   /* .rela.eh_frame section */
} CodeGen;

#define CG_MAX_LABELS 4096

static CodeGen *cg_new(CompUnit *cu) {
    CodeGen *cg = calloc(1, sizeof(CodeGen));
    cg->cu = cu;
    cg->max_labels = CG_MAX_LABELS;
    cg->label_defs = calloc(CG_MAX_LABELS, sizeof(int));
    cg->label_refs = calloc(CG_MAX_LABELS, sizeof(int));
    for (int i = 0; i < CG_MAX_LABELS; i++) {
        cg->label_defs[i] = -1;
        cg->label_refs[i] = 0; /* 0 means no refs */
    }
    return cg;
}

