static void emit1(CodeGen *cg, uint8_t b) {
    section_put1(cg->cu->text, b);
}

static void emit2(CodeGen *cg, uint8_t b1, uint8_t b2) {
    emit1(cg, b1); emit1(cg, b2);
}

static void emit3(CodeGen *cg, uint8_t b1, uint8_t b2, uint8_t b3) {
    emit1(cg, b1); emit1(cg, b2); emit1(cg, b3);
}

static void emit4(CodeGen *cg, uint32_t v) {
    section_put4(cg->cu->text, v);
}

static void emit8(CodeGen *cg, uint64_t v) {
    section_put8(cg->cu->text, v);
}

/* Get current text offset */
static int cg_cur(CodeGen *cg) {
    return cg->cu->text->data_offset;
}

/* Create a new label */
static int cg_new_label(CodeGen *cg) {
    int lbl = cg->nb_labels_cg++;
    if (lbl >= cg->max_labels) {
        cg->max_labels *= 2;
        cg->label_defs = tcc_realloc(cg->label_defs, cg->max_labels * sizeof(int));
        cg->label_refs = tcc_realloc(cg->label_refs, cg->max_labels * sizeof(int));
        memset(cg->label_defs + lbl, -1, (cg->max_labels - lbl) * sizeof(int));
        memset(cg->label_refs + lbl, 0, (cg->max_labels - lbl) * sizeof(int));
    }
    cg->label_defs[lbl] = -1;
    cg->label_refs[lbl] = 0;
    return lbl;
}

/* Define a label at current position */
static void cg_define_label(CodeGen *cg, int lbl) {
    int pos = cg_cur(cg);
    cg->label_defs[lbl] = pos;
    /* Patch any forward references */
    /* Each ref is stored as offset in text where 4-byte relative address needs patching */
    /* We store refs in a linked list via text section itself */
    int ref = cg->label_refs[lbl];
    while (ref != 0) {
        /* Read next in chain (stored at text[ref-4]) */
        uint32_t *next_ptr = (uint32_t *)(cg->cu->text->data + ref - 4);
        int next_ref = (int)*next_ptr;
        /* Patch the 4-byte offset */
        int rel = pos - (ref + 0); /* offset from end of instruction */
        /* Actually, ref points to AFTER the 4 bytes. The instruction is: opcode [ref-4..ref-1] */
        /* The relative offset = target - (ref_pos), where ref_pos is start of next instruction */
        /* At the time of emission, we stored: jmp/je to label -> emit4(0) and record ref = cur */
        /* The offset should be: pos - ref */
        *next_ptr = (uint32_t)(pos - ref);
        ref = next_ref;
    }
    cg->label_refs[lbl] = 0;
