/* Returns the position of the 4-byte field for later patching */
static int cg_emit_ref(CodeGen *cg, int lbl) {
    int pos = cg_cur(cg);
    if (cg->label_defs[lbl] >= 0) {
        /* Already defined - emit actual offset */
        int rel = cg->label_defs[lbl] - (pos + 4);
        emit4(cg, (uint32_t)rel);
    } else {
        /* Forward reference - chain it */
        int prev = cg->label_refs[lbl];
        emit4(cg, (uint32_t)prev); /* store prev in chain */
        cg->label_refs[lbl] = pos + 4; /* current ref position (after the 4 bytes) */
