    s->alacarte_link = 1;
    s->warn_implicit_function_declaration = 1;
    s->warn_discarded_qualifiers = 1;
    s->asynchronous_unwind_tables = 1;
    s->std_version = 199901; /* C99 */
    s->verbose = 0;
    return s;
}

