/* Create a TCCState with defaults */
static TCCState *tcc_state_new(void) {
    TCCState *s = calloc(1, sizeof(TCCState));
    s->output_type = TCC_OUTPUT_EXE;
    s->tcc_lib_path = tcc_strdup(CONFIG_TCCDIR);
    s->elf_interp = tcc_strdup(CONFIG_TCC_ELFINTERP);
    s->alacarte_link = 1;
    s->warn_implicit_function_declaration = 1;
    s->warn_discarded_qualifiers = 1;
    s->asynchronous_unwind_tables = 1;
    s->std_version = 199901; /* C99 */
    s->verbose = 0;
    return s;
}

/* Process a @listfile */
static void process_listfile(TCCState *s, const char *listfile, char ***pargv, int *pargc);

/* Process command line arguments */
/* Returns: 0 on success, 1 if should show help, -1 on error */
typedef struct {
    char **argv;
    int argc;
    int idx;
} ArgParser;

static const char *ap_next(ArgParser *ap) {
    if (ap->idx >= ap->argc) return NULL;
    return ap->argv[ap->idx++];
}

static const char *ap_peek(ArgParser *ap) {
    if (ap->idx >= ap->argc) return NULL;
    return ap->argv[ap->idx];
}

/* Handle -Wl, option */
static void handle_linker_option(TCCState *s, const char *opt) {
    if (!strncmp(opt, "-nostdlib", 9)) {
        s->nostdlib = 1;
    } else if (!strncmp(opt, "-rpath=", 7)) {
        s->rpath = tcc_strdup(opt + 7);
    } else if (!strncmp(opt, "-soname=", 8)) {
        s->soname = tcc_strdup(opt + 8);
    } else if (!strncmp(opt, "-Bsymbolic", 10)) {
        s->symbolic = 1;
    } else if (!strncmp(opt, "-export-all-symbols", 19) ||
               !strncmp(opt, "-export-dynamic", 15)) {
        s->rdynamic = 1;
    } else if (!strncmp(opt, "-whole-archive", 14)) {
        s->whole_archive = 1;
    } else if (!strncmp(opt, "-no-whole-archive", 17)) {
        s->whole_archive = 0;
    } else if (!strncmp(opt, "-image-base=", 12) || !strncmp(opt, "-Ttext=", 7)) {
        const char *p = strchr(opt, '=');
        if (p) {
            s->text_addr = strtoul(p+1, NULL, 0);
            s->has_text_addr = 1;
        }
    } else if (!strncmp(opt, "-section-alignment=", 19)) {
        s->section_align = strtoul(opt + 19, NULL, 0);
    } else if (!strncmp(opt, "-enable-new-dtags", 17)) {
        s->enable_new_dtags = 1;
    } else if (!strncmp(opt, "-dynamic-linker=", 16) || !strncmp(opt, "-Ipath,", 7)) {
        const char *p = strchr(opt, ',') ? strchr(opt, ',') + 1 : strchr(opt, '=') ? strchr(opt, '=') + 1 : NULL;
        if (p) {
            free(s->elf_interp);
            s->elf_interp = tcc_strdup(p);
        }
    } else if (!strncmp(opt, "-Map=", 5)) {
        s->mapfile = tcc_strdup(opt + 5);
    } else if (!strncmp(opt, "-init=", 6)) {
        s->init_sym = tcc_strdup(opt + 6);
    } else if (!strncmp(opt, "-fini=", 6)) {
        s->fini_sym = tcc_strdup(opt + 6);
    }
    /* Other options: -as-needed, -O, -z= are ignored */
}

static void add_file(TCCState *s, const char *filename, int type) {
    s->files = tcc_realloc(s->files, (s->nb_files+1)*sizeof(char*));
    s->file_types = tcc_realloc(s->file_types, (s->nb_files+1)*sizeof(int));
    s->files[s->nb_files] = tcc_strdup(filename);
    s->file_types[s->nb_files] = type;
    s->nb_files++;
}

/* File types */
#define FILETYPE_C    0
#define FILETYPE_ASM  1
#define FILETYPE_BIN  2
#define FILETYPE_NONE 3
#define FILETYPE_OBJ  4
#define FILETYPE_LIB  5

static int get_filetype(const char *filename) {
    const char *ext = strrchr(filename, '.');
    if (!ext) return FILETYPE_C;
    if (!strcmp(ext, ".c") || !strcmp(ext, ".i")) return FILETYPE_C;
    if (!strcmp(ext, ".s") || !strcmp(ext, ".S") || !strcmp(ext, ".asm")) return FILETYPE_ASM;
    if (!strcmp(ext, ".o") || !strcmp(ext, ".obj")) return FILETYPE_OBJ;
    if (!strcmp(ext, ".a")) return FILETYPE_LIB;
    if (!strcmp(ext, ".so") || !strcmp(ext, ".dll")) return FILETYPE_LIB;
    return FILETYPE_C;
}

/* Parse args from a string (for @listfile) */
static void expand_listfile(TCCState *s, const char *filename, char ***new_argv, int *new_argc) {
    FILE *f = fopen(filename, "r");
    if (!f) {
        fprintf(stderr, "tcc: error: cannot open listfile '%s'\n", filename);
        return;
    }
    char line[1024];
    while (fgets(line, sizeof(line), f)) {
        /* Remove newline */
        int len = strlen(line);
        while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) len--;
        line[len] = 0;
        if (len > 0) {
            *new_argv = tcc_realloc(*new_argv, (*new_argc+1)*sizeof(char*));
            (*new_argv)[(*new_argc)++] = tcc_strdup(line);
        }
    }
    fclose(f);
}

static int tcc_parse_args(TCCState *s, int argc, char **argv, int optind) {
    int file_type = -1; /* -1 = auto-detect */
    int show_help = 0;
    int show_hh = 0;

    /* First pass: expand @listfiles */
    char **expanded_argv = NULL;
    int expanded_argc = 0;
    for (int i = optind; i < argc; i++) {
        if (argv[i][0] == '@') {
            expand_listfile(s, argv[i]+1, &expanded_argv, &expanded_argc);
        } else {
            expanded_argv = tcc_realloc(expanded_argv, (expanded_argc+1)*sizeof(char*));
            expanded_argv[expanded_argc++] = tcc_strdup(argv[i]);
        }
    }

    for (int i = 0; i < expanded_argc; i++) {
        const char *arg = expanded_argv[i];

        if (arg[0] != '-') {
            /* Input file */
            int ft = (file_type >= 0) ? file_type : get_filetype(arg);
            add_file(s, arg, ft);
            file_type = -1; /* reset after each file */
            continue;
        }

        /* Options */
        if (!strcmp(arg, "-")) {
            /* stdin */
            add_file(s, "-", file_type >= 0 ? file_type : FILETYPE_C);
            file_type = -1;
        } else if (!strcmp(arg, "-h") || !strcmp(arg, "--help")) {
            show_help = 1;
        } else if (!strcmp(arg, "-hh")) {
            show_hh = 1;
        } else if (!strcmp(arg, "-v") || !strcmp(arg, "--version")) {
            print_version();
            for (int j = i+1; j < expanded_argc; j++) free(expanded_argv[j]);
            free(expanded_argv);
            return 0; /* handled, exit cleanly */
        } else if (!strcmp(arg, "-vv")) {
            s->verbose = 2;
            tcc_setup_defaults(s);
            print_search_dirs(s);
            for (int j = i+1; j < expanded_argc; j++) free(expanded_argv[j]);
            free(expanded_argv);
            return 0;
        } else if (!strcmp(arg, "-dumpversion")) {
            print_dumpversion();
            for (int j = i+1; j < expanded_argc; j++) free(expanded_argv[j]);
            free(expanded_argv);
            return 0;
        } else if (!strcmp(arg, "-print-search-dirs")) {
            tcc_setup_defaults(s);
            print_search_dirs(s);
            for (int j = i+1; j < expanded_argc; j++) free(expanded_argv[j]);
            free(expanded_argv);
            return 0;
        } else if (!strcmp(arg, "-c")) {
            s->output_type = TCC_OUTPUT_OBJ;
        } else if (!strcmp(arg, "-E")) {
            s->output_type = TCC_OUTPUT_PREPROCESS;
            s->pp_only = 1;
        } else if (!strcmp(arg, "-o")) {
            if (i+1 < expanded_argc) {
                free(s->outfile);
                s->outfile = tcc_strdup(expanded_argv[++i]);
            }
        } else if (!strncmp(arg, "-o", 2)) {
            free(s->outfile);
            s->outfile = tcc_strdup(arg + 2);
        } else if (!strcmp(arg, "-run")) {
            s->do_run = 1;
            s->output_type = TCC_OUTPUT_MEMORY;
        } else if (!strcmp(arg, "-rstdin")) {
            if (i+1 < expanded_argc) {
                s->rstdin_file = tcc_strdup(expanded_argv[++i]);
            }
        } else if (!strcmp(arg, "-bench")) {
            s->do_bench = 1;
        } else if (!strcmp(arg, "-w")) {
            s->warn_none = 1;
        } else if (!strcmp(arg, "-Wall")) {
            s->warn_all = 1;
            s->warn_implicit_function_declaration = 1;
            s->warn_discarded_qualifiers = 1;
        } else if (!strcmp(arg, "-Wno-all")) {
            s->warn_all = 0;
        } else if (!strncmp(arg, "-W", 2)) {
            const char *wopt = arg + 2;
            int is_no = !strncmp(wopt, "no-", 3);
            if (is_no) wopt += 3;
            if (!strcmp(wopt, "error")) {
                s->warn_error = !is_no;
            } else if (!strncmp(wopt, "error=", 6)) {
                s->warn_error = !is_no;
            } else if (!strcmp(wopt, "all")) {
                s->warn_all = !is_no;
            } else if (!strcmp(wopt, "write-strings")) {
                s->warn_write_strings = !is_no;
            } else if (!strcmp(wopt, "unsupported")) {
                s->warn_unsupported = !is_no;
            } else if (!strcmp(wopt, "implicit-function-declaration")) {
                s->warn_implicit_function_declaration = !is_no;
            } else if (!strcmp(wopt, "discarded-qualifiers")) {
                s->warn_discarded_qualifiers = !is_no;
            }
        } else if (!strncmp(arg, "-I", 2)) {
            const char *path = arg[2] ? arg+2 : (i+1 < expanded_argc ? expanded_argv[++i] : NULL);
            if (path) add_include_path(s, path);
        } else if (!strncmp(arg, "-isystem", 8)) {
            const char *path = arg[8] ? arg+8 : (i+1 < expanded_argc ? expanded_argv[++i] : NULL);
            if (path) add_sys_include_path(s, path);
        } else if (!strncmp(arg, "-D", 2)) {
            const char *def = arg[2] ? arg+2 : (i+1 < expanded_argc ? expanded_argv[++i] : NULL);
            if (def) parse_define(s, def);
        } else if (!strncmp(arg, "-U", 2)) {
            const char *sym = arg[2] ? arg+2 : (i+1 < expanded_argc ? expanded_argv[++i] : NULL);
            if (sym) macro_undef(s, sym);
        } else if (!strncmp(arg, "-L", 2)) {
            const char *path = arg[2] ? arg+2 : (i+1 < expanded_argc ? expanded_argv[++i] : NULL);
            if (path) add_library_path(s, path);
        } else if (!strncmp(arg, "-l", 2)) {
            const char *lib = arg[2] ? arg+2 : (i+1 < expanded_argc ? expanded_argv[++i] : NULL);
            if (lib) add_library(s, lib);
        } else if (!strcmp(arg, "-nostdinc")) {
            s->nostdinc = 1;
        } else if (!strcmp(arg, "-nostdlib")) {
            s->nostdlib = 1;
        } else if (!strcmp(arg, "-shared")) {
            s->shared = 1;
            s->output_type = TCC_OUTPUT_DLL;
        } else if (!strcmp(arg, "-static")) {
            s->static_link = 1;
        } else if (!strcmp(arg, "-rdynamic")) {
            s->rdynamic = 1;
        } else if (!strcmp(arg, "-r")) {
            s->relocatable = 1;
            s->output_type = TCC_OUTPUT_OBJ;
        } else if (!strcmp(arg, "-g")) {
            s->do_debug = 1;
        } else if (!strncmp(arg, "-gdwarf", 7)) {
            s->do_debug = 1;
            s->dwarf = 1;
            if (arg[7] == '-') {
                s->dwarf_version = atoi(arg+8);
            } else {
                s->dwarf_version = 4;
            }
        } else if (!strcmp(arg, "-b")) {
            s->do_bounds_check = 1;
            s->do_debug = 1;
        } else if (!strncmp(arg, "-bt", 3)) {
            s->bt_num = arg[3] ? atoi(arg+3) : 1;
        } else if (!strncmp(arg, "-B", 2)) {
            const char *path = arg[2] ? arg+2 : (i+1 < expanded_argc ? expanded_argv[++i] : NULL);
            if (path) {
                free(s->tcc_lib_path);
                s->tcc_lib_path = tcc_strdup(path);
            }
        } else if (!strncmp(arg, "-x", 2)) {
            char xc = arg[2] ? arg[2] : (i+1 < expanded_argc ? expanded_argv[i+1][0] : 0);
            if (!arg[2] && i+1 < expanded_argc) i++;
            switch (xc) {
            case 'c': file_type = FILETYPE_C; break;
            case 'a': file_type = FILETYPE_ASM; break;
            case 'b': file_type = FILETYPE_BIN; break;
            case 'n': file_type = FILETYPE_NONE; break;
            }
        } else if (!strncmp(arg, "-std=", 5)) {
            const char *std = arg + 5;
            if (!strcmp(std, "c11") || !strcmp(std, "gnu11")) {
                s->std_version = 201112;
            } else if (!strcmp(std, "c99") || !strcmp(std, "gnu99")) {
                s->std_version = 199901;
