            switch (xc) {
            case 'c': file_type = FILETYPE_C; break;
            case 'a': file_type = FILETYPE_ASM; break;
            case 'b': file_type = FILETYPE_BIN; break;
            case 'n': file_type = FILETYPE_NONE; break;
            }
        } else if (!strncmp(arg, "-std=", 5)) {
            const char *std = arg + 5;
            if (!strcmp(std, "c11") || !strcmp(std, "gnu11")) {
                s->std_version = 201112;
