        } else if (!strcmp(arg, "-M")) {
            s->gen_deps = 2; /* deps only, no compilation */
            s->include_sys_deps = 1;
        } else if (!strcmp(arg, "-MM")) {
            s->gen_deps = 2;
            s->include_sys_deps = 0;
        } else if (!strcmp(arg, "-MF")) {
            if (i+1 < expanded_argc) {
                s->deps_outfile = tcc_strdup(expanded_argv[++i]);
            }
        } else if (!strcmp(arg, "-P")) {
            s->pp_lineno_mode = 2; /* no line info */
        } else if (!strcmp(arg, "-P1")) {
            s->pp_lineno_mode = 1;
        } else if (!strcmp(arg, "-dD")) {
            s->pp_dD = 1;
        } else if (!strcmp(arg, "-dM")) {
            s->pp_dM = 1;
        } else if (!strcmp(arg, "-dt")) {
            s->pp_debug = 1;
        } else if (!strcmp(arg, "-pthread")) {
            parse_define(s, "_REENTRANT");
            add_library(s, "pthread");
        } else if (!strncmp(arg, "-O", 2)) {
            int n = (arg[2] >= '1' && arg[2] <= '3') ? arg[2]-'0' : 0;
            s->do_optimize = n;
            if (n > 0) {
                parse_define(s, "__OPTIMIZE__");
                char val[16];
                snprintf(val, sizeof(val), "__OPTIMIZE__%d__", n);
            }
        } else if (!strncmp(arg, "-Wl,", 4)) {
            handle_linker_option(s, arg + 4);
        } else if (!strncmp(arg, "-Wp,", 4)) {
            /* Pass to preprocessor */
        } else if (!strncmp(arg, "-f", 2)) {
            const char *fopt = arg + 2;
            int is_no = !strncmp(fopt, "no-", 3);
            if (is_no) fopt += 3;
            if (!strcmp(fopt, "unsigned-char")) s->char_is_unsigned = !is_no;
            else if (!strcmp(fopt, "signed-char")) s->char_is_unsigned = is_no;
            else if (!strcmp(fopt, "leading-underscore")) s->leading_underscore = !is_no;
            else if (!strcmp(fopt, "ms-extensions")) s->ms_extensions = !is_no;
            else if (!strcmp(fopt, "dollars-in-identifiers")) s->dollars_in_identifiers = !is_no;
            else if (!strcmp(fopt, "reverse-funcargs")) s->reverse_funcargs = !is_no;
            else if (!strcmp(fopt, "gnu89-inline")) s->gnu89_inline = !is_no;
            else if (!strcmp(fopt, "asynchronous-unwind-tables")) s->asynchronous_unwind_tables = !is_no;
            else if (!strcmp(fopt, "test-coverage")) s->test_coverage = !is_no;
            else if (!strcmp(fopt, "common")) { /* use common section */ }
        } else if (!strncmp(arg, "-m", 2)) {
            if (!strcmp(arg+2, "ms-bitfields")) s->ms_bitfields = 1;
            else if (!strcmp(arg+2, "no-sse")) s->no_sse = 1;
            else if (!strcmp(arg+2, "32")) {
                /* Would need to re-exec cross compiler */
                fprintf(stderr, "tcc: error: -m32 not supported in this build\n");
            } else if (!strcmp(arg+2, "64")) {
                /* Already 64-bit */
            }
        } else if (!strncmp(arg, "-include", 8)) {
            const char *f = arg[8] ? arg+8 : (i+1 < expanded_argc ? expanded_argv[++i] : NULL);
            if (f) add_include_file(s, f);
        } else if (!strcmp(arg, "-ar")) {
            s->do_ar = 1;
        } else if (!strcmp(arg, "-verbose") || !strcmp(arg, "-v")) {
            s->verbose++;
        } else {
            /* Unknown option - warn or ignore */
            /* Some common ignored options */
            if (!strcmp(arg, "-arch") || !strcmp(arg, "-C") ||
                !strcmp(arg, "--param") || !strcmp(arg, "-pedantic") ||
                !strcmp(arg, "-pipe") || !strcmp(arg, "-s") ||
                !strcmp(arg, "-traditional")) {
                /* silently ignored */
            } else if (arg[0] == '-') {
                /* Unknown - silently ignore most */
            }
        }
    }

    /* Free expanded argv */
    for (int i = 0; i < expanded_argc; i++) free(expanded_argv[i]);
    free(expanded_argv);

    if (show_hh) {
        print_help(1);
        return 0;
    }
    if (show_help) {
        print_help(0);
        return 0;
    }

    return 1; /* continue with compilation */
}

