/* ============================================================
 * DEPENDENCY GENERATION
 * ============================================================ */

static void write_dep_file(TCCState *s, const char *outfile, const char *src_file) {
    /* Determine dep file name */
    char dep_file[1024];
    if (s->deps_outfile) {
        strncpy(dep_file, s->deps_outfile, sizeof(dep_file)-1);
    } else {
        /* Replace .o with .d */
        strncpy(dep_file, outfile ? outfile : "output.o", sizeof(dep_file)-1);
        char *dot = strrchr(dep_file, '.');
        if (dot) strcpy(dot, ".d");
        else strcat(dep_file, ".d");
    }

    FILE *f = fopen(dep_file, "w");
    if (!f) return;

    /* Write dependency file */
    const char *target;
    if (outfile) {
        target = outfile;
    } else {
        /* Derive from source file name */
        char base[256];
        const char *slash = strrchr(src_file ? src_file : "input", '/');
        strncpy(base, slash ? slash+1 : (src_file ? src_file : "input"), sizeof(base)-1);
        char *dot = strrchr(base, '.');
        if (dot) strcpy(dot, ".o");
        else strcat(base, ".o");
        target = base;
    }

    /* Write: target: \n  src \n  dep1 \n  ... */
    fprintf(f, "%s: \\\n  %s", target, src_file ? src_file : "-");

    /* Write included files */
    for (int i = 0; i < dep_files.len; i++) {
        fprintf(f, " \\\n  %s", (char*)dep_files.buf[i]);
    }
    fprintf(f, "\n");

    fclose(f);
}

/* ============================================================
 * AR TOOL  
 * ============================================================ */

static int tcc_ar(TCCState *s, int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "usage: tcc -ar [crstvx] lib [files]\n");
        fprintf(stderr, "create library ([abdiopN] not supported).\n");
        return 1;
    }

    const char *flags = argv[0];
    const char *libname = argv[1];

    /* Determine operation */
    int create = strchr(flags, 'c') || strchr(flags, 'r') || strchr(flags, 'q');
    int verbose = strchr(flags, 'v') != NULL;
    int extract = strchr(flags, 'x') != NULL;
    int list = strchr(flags, 't') != NULL;
    int delete = strchr(flags, 'd') != NULL;
    int replace = strchr(flags, 'r') != NULL;
    int update = strchr(flags, 'u') != NULL;
    int print = strchr(flags, 'p') != NULL;
    int symbols = strchr(flags, 's') != NULL;

    /* Simple implementation: create/replace archive */
    if (extract) {
        /* Extract files from archive */
        FILE *f = fopen(libname, "rb");
        if (!f) {
            fprintf(stderr, "tcc: error: cannot open '%s'\n", libname);
            return 1;
        }

        char magic[SARMAG+1];
        fread(magic, 1, SARMAG, f);
        magic[SARMAG] = 0;
        if (strcmp(magic, ARMAG) != 0) {
            fprintf(stderr, "tcc: error: '%s' is not an archive\n", libname);
            fclose(f);
            return 1;
        }

        /* Read archive members */
        struct ar_hdr hdr;
        while (fread(&hdr, sizeof(hdr), 1, f) == 1) {
            char name[20];
            strncpy(name, hdr.ar_name, sizeof(name)-1);
            name[sizeof(name)-1] = 0;
            /* Trim trailing spaces */
            int nlen = strlen(name);
            while (nlen > 0 && name[nlen-1] == ' ') name[--nlen] = 0;
            if (nlen > 0 && name[nlen-1] == '/') name[--nlen] = 0;

            long size = atol(hdr.ar_size);

            if (verbose) printf("x - %s\n", name);

            /* Extract this member */
            char *buf = malloc(size);
            if (fread(buf, 1, size, f) != (size_t)size) {
                free(buf);
                break;
            }

            /* Write to file if it's in the list (or all) */
            int extract_this = 1;
            if (argc > 2) {
                extract_this = 0;
                for (int j = 2; j < argc; j++) {
                    if (!strcmp(argv[j], name)) { extract_this = 1; break; }
                }
            }

            if (extract_this && name[0] != '/' && name[0] != '_') {
                FILE *out = fopen(name, "wb");
                if (out) {
                    fwrite(buf, 1, size, out);
                    fclose(out);
                }
            }

            free(buf);
            /* Archive members are padded to even size */
            if (size & 1) fseek(f, 1, SEEK_CUR);
        }
        fclose(f);
        return 0;
    }

    if (list) {
        /* List archive contents */
        FILE *f = fopen(libname, "rb");
        if (!f) {
            fprintf(stderr, "tcc: error: cannot open '%s'\n", libname);
            return 1;
        }
        char magic[SARMAG+1];
        fread(magic, 1, SARMAG, f);
        magic[SARMAG] = 0;
        if (strcmp(magic, ARMAG) != 0) {
            fprintf(stderr, "tcc: error: '%s' is not an archive\n", libname);
            fclose(f);
            return 1;
        }
        struct ar_hdr hdr;
        while (fread(&hdr, sizeof(hdr), 1, f) == 1) {
            char name[20];
            strncpy(name, hdr.ar_name, sizeof(name)-1);
            name[sizeof(name)-1] = 0;
            int nlen = strlen(name);
            while (nlen > 0 && name[nlen-1] == ' ') name[--nlen] = 0;
            if (nlen > 0 && name[nlen-1] == '/') name[--nlen] = 0;

            long size = atol(hdr.ar_size);

            if (name[0] != '/' && name[0] != '_') {
                printf("%s\n", name);
            }
            fseek(f, size + (size & 1), SEEK_CUR);
        }
        fclose(f);
        return 0;
    }

    /* Create/replace operation */
    if (!create && !replace) {
        fprintf(stderr, "usage: tcc -ar [crstvx] lib [files]\n");
        fprintf(stderr, "create library ([abdiopN] not supported).\n");
        return 1;
    }

    /* Collect objects */
    FILE *f = fopen(libname, "wb");
    if (!f) {
        fprintf(stderr, "tcc: error: cannot create '%s'\n", libname);
        return 1;
    }

    /* Write archive magic */
    fwrite(ARMAG, 1, SARMAG, f);

    /* Write each object file */
    for (int i = 2; i < argc; i++) {
        const char *objfile = argv[i];
        FILE *obj = fopen(objfile, "rb");
        if (!obj) {
            fprintf(stderr, "tcc: warning: cannot open '%s'\n", objfile);
            continue;
        }

        fseek(obj, 0, SEEK_END);
        long size = ftell(obj);
        fseek(obj, 0, SEEK_SET);

        char *buf = malloc(size);
        fread(buf, 1, size, obj);
        fclose(obj);

        /* Get just the basename */
        const char *basename = strrchr(objfile, '/');
        basename = basename ? basename+1 : objfile;

        if (verbose) printf("a - %s\n", basename);

        /* Write archive header */
        struct ar_hdr hdr;
        memset(&hdr, ' ', sizeof(hdr));
        /* Name: pad to 16 chars with spaces, then '/' */
        int nlen = strlen(basename);
        if (nlen > 15) nlen = 15;
        memcpy(hdr.ar_name, basename, nlen);
        hdr.ar_name[nlen] = '/';
        /* Fill rest with spaces - already done by memset */
        /* Date: 0 */
        memcpy(hdr.ar_date, "0", 1);
        /* UID/GID: 0 */
        memcpy(hdr.ar_uid, "0", 1);
        memcpy(hdr.ar_gid, "0", 1);
        /* Mode: 100644 */
        memcpy(hdr.ar_mode, "100644", 6);
        /* Size */
        char sizestr[11];
        snprintf(sizestr, sizeof(sizestr), "%-10ld", size);
        memcpy(hdr.ar_size, sizestr, 10);
        /* End: `\n */
        hdr.ar_fmag[0] = '`';
        hdr.ar_fmag[1] = '\n';

        fwrite(&hdr, sizeof(hdr), 1, f);
        fwrite(buf, 1, size, f);
        if (size & 1) fputc('\n', f); /* pad to even */
        free(buf);
    }

    fclose(f);
    return 0;
}

