    FILE *f = fopen(libname, "wb");
    if (!f) {
        fprintf(stderr, "tcc: error: cannot create '%s'\n", libname);
        return 1;
    }

    /* Write archive magic */
    fwrite(ARMAG, 1, SARMAG, f);

    /* Write each object file */
    for (int i = 2; i < argc; i++) {
        const char *objfile = argv[i];
        FILE *obj = fopen(objfile, "rb");
        if (!obj) {
            fprintf(stderr, "tcc: warning: cannot open '%s'\n", objfile);
            continue;
        }

        fseek(obj, 0, SEEK_END);
        long size = ftell(obj);
        fseek(obj, 0, SEEK_SET);

        char *buf = malloc(size);
        fread(buf, 1, size, obj);
        fclose(obj);

        /* Get just the basename */
        const char *basename = strrchr(objfile, '/');
        basename = basename ? basename+1 : objfile;

        if (verbose) printf("a - %s\n", basename);

        /* Write archive header */
        struct ar_hdr hdr;
        memset(&hdr, ' ', sizeof(hdr));
        /* Name: pad to 16 chars with spaces, then '/' */
        int nlen = strlen(basename);
        if (nlen > 15) nlen = 15;
        memcpy(hdr.ar_name, basename, nlen);
        hdr.ar_name[nlen] = '/';
        /* Fill rest with spaces - already done by memset */
        /* Date: 0 */
        memcpy(hdr.ar_date, "0", 1);
        /* UID/GID: 0 */
        memcpy(hdr.ar_uid, "0", 1);
        memcpy(hdr.ar_gid, "0", 1);
        /* Mode: 100644 */
        memcpy(hdr.ar_mode, "100644", 6);
        /* Size */
        char sizestr[11];
        snprintf(sizestr, sizeof(sizestr), "%-10ld", size);
        memcpy(hdr.ar_size, sizestr, 10);
        /* End: `\n */
        hdr.ar_fmag[0] = '`';
        hdr.ar_fmag[1] = '\n';

        fwrite(&hdr, sizeof(hdr), 1, f);
        fwrite(buf, 1, size, f);
        if (size & 1) fputc('\n', f); /* pad to even */
        free(buf);
    }

    fclose(f);
    return 0;
}

