/* ============================================================
 * C PARSER AND CODE GENERATOR
 * Combined single-pass parser and code generator for C99
 * ============================================================ */

/* Type system helpers */

/* Get size of a basic type in bytes */
static int type_size(CType *type, int *align) {
    int btype = type->t & VT_BTYPE;
    int size, a;

    switch (btype) {
    case VT_BYTE:   size = 1; a = 1; break;
    case VT_SHORT:  size = 2; a = 2; break;
    case VT_INT:    size = 4; a = 4; break;
    case VT_LONG:   size = 8; a = 8; break; /* 64-bit system */
    case VT_LLONG:  size = 8; a = 8; break;
    case VT_FLOAT:  size = 4; a = 4; break;
    case VT_DOUBLE: size = 8; a = 8; break;
    case VT_LDOUBLE: size = 16; a = 16; break;
    case VT_BOOL:   size = 1; a = 1; break;
    case VT_PTR:
        if (type->t & VT_ARRAY) {
            if (type->ref && type->ref->nb_elts >= 0) {
                int elt_align;
                int elt_size = type_size(&type->ref->element_type, &elt_align);
                size = elt_size * type->ref->nb_elts;
                a = elt_align;
            } else {
                size = 0; a = 1; /* incomplete array */
            }
        } else {
            size = 8; a = 8; /* pointer */
        }
        break;
    case VT_STRUCT:
        if (type->ref) { size = type->ref->size; a = type->ref->align; }
        else { size = 0; a = 1; }
        break;
    case VT_FUNC:   size = 8; a = 8; /* function pointer */
        break;
    case VT_ENUM:   size = 4; a = 4; break;
    case VT_VOID:   size = 0; a = 1; break;
    default:        size = 4; a = 4; break;
    }

    if (align) *align = a;
    return size;
}

static int is_integer_type(CType *t) {
    int bt = t->t & VT_BTYPE;
    return bt == VT_INT || bt == VT_BYTE || bt == VT_SHORT ||
           bt == VT_LONG || bt == VT_LLONG || bt == VT_BOOL ||
           bt == VT_ENUM;
}

static int is_float_type(CType *t) {
    int bt = t->t & VT_BTYPE;
    return bt == VT_FLOAT || bt == VT_DOUBLE || bt == VT_LDOUBLE;
}

static int is_pointer_type(CType *t) {
    int bt = t->t & VT_BTYPE;
    return bt == VT_PTR || bt == VT_FUNC;
}

/* ============================================================
 * PARSE STATE
 * ============================================================ */

/* The parse state - everything needed for parsing one translation unit */
typedef struct PS {
    TCCState *s;          /* compiler state */
    CompUnit *cu;         /* current compilation unit */
    CodeGen *cg;          /* code generator (if compiling) */
    FILE *pp_out;         /* preprocessor output (if -E) */

    /* Current token */
    int tok;              /* token type */
    int line_num;         /* line number of current token */
    char *tok_ident;      /* identifier text */
    long long tok_int;    /* integer value */
    unsigned long long tok_uint;
    double tok_double;    /* float value */
    CString tok_str;      /* string value */
    int tok_is_wide;      /* wide string/char */
    int tok_float_type;   /* 0=double, 1=float, 2=ldouble */

    /* Token lookahead buffer */
    int tok_buf[4];
    int tok_buf_n;

    /* Symbol tables */
    /* Typedef and variable names - organized by scope */
    struct {
        Symbol **syms; /* hash table */
        int size;
    } sym_table;
    Symbol *local_syms; /* current function's local vars */
    Symbol *global_syms_list; /* global symbols list */

    /* Tag table (struct/union/enum tags) */
    Symbol *tags_hash[256];

    /* Label table */
    struct {
        char *name;
        int defined;
        int offset;   /* in .text */
        int refs;     /* forward references to patch */
        struct { int offset; } ref_list[64];
        int nb_refs;
    } labels[512];
    int nb_labels;

    /* Current function state */
    int in_func;
    CType func_ret_type;
    int func_ret_label;     /* label for "return" */
    int *break_labels;
    int nb_break_labels;
    int cap_break_labels;
    int *continue_labels;
    int nb_continue_labels;
    int cap_cont_labels;

    /* Switch state stack */
    struct SwitchInfo {
        int *case_values;    /* case values */
        int *case_labels;    /* corresponding labels */
        int nb_cases;
        int cap_cases;
        int default_label;   /* -1 if no default */
        int break_label;     /* label for break */
    } *sw_stack;
    int sw_depth;
    int sw_cap;

    /* Local variable offset */
    int local_offset; /* negative offset from rbp */
    int max_local;    /* max local offset used */

    /* Anonymous symbol counter */
    int anon_count;

    /* Static data counter for string literals */
    int str_count;

    /* Dependency tracking */
    char **dep_files;
    int nb_dep_files;
} PS;

#define SYM_TABLE_SIZE 2048
#define SYM_TABLE_MASK (SYM_TABLE_SIZE-1)

static PS *ps_new(TCCState *s, CompUnit *cu, CodeGen *cg, FILE *pp_out) {
    PS *ps = calloc(1, sizeof(PS));
    ps->s = s;
    ps->cu = cu;
    ps->cg = cg;
    ps->pp_out = pp_out;
    ps->sym_table.size = SYM_TABLE_SIZE;
    ps->sym_table.syms = calloc(SYM_TABLE_SIZE, sizeof(Symbol*));
    ps->func_ret_label = -1;
    return ps;
}

static void ps_free(PS *ps) {
    /* TODO: free symbols etc. */
    free(ps->sym_table.syms);
    free(ps->break_labels);
    free(ps->continue_labels);
    free(ps);
}

/* Symbol lookup */
static Symbol *sym_lookup_name(PS *ps, const char *name) {
    unsigned h = sym_hashfn(name) & SYM_TABLE_MASK;
    Symbol *s = ps->sym_table.syms[h];
    while (s) {
        if (!strcmp(s->name, name)) return s;
        s = s->scope_next;
    }
    return NULL;
}

static Symbol *sym_add_new(PS *ps, const char *name, int flags) {
    Symbol *s = calloc(1, sizeof(Symbol));
    s->name = name ? tcc_strdup(name) : NULL;
    s->array_size = -1;
    unsigned h = name ? (sym_hashfn(name) & SYM_TABLE_MASK) : 0;
    if (name) {
        s->scope_next = ps->sym_table.syms[h];
        ps->sym_table.syms[h] = s;
    }
    return s;
}

static Symbol *find_tag(PS *ps, const char *name) {
    unsigned h = sym_hashfn(name) & 255;
    Symbol *s = ps->tags_hash[h];
    while (s) {
        if (s->name && !strcmp(s->name, name)) return s;
        s = s->scope_next;
    }
    return NULL;
}

static Symbol *add_tag(PS *ps, const char *name) {
    Symbol *s = find_tag(ps, name);
    if (s) return s;
    s = calloc(1, sizeof(Symbol));
    s->name = name ? tcc_strdup(name) : NULL;
    unsigned h = name ? (sym_hashfn(name) & 255) : 0;
    s->scope_next = ps->tags_hash[h];
    ps->tags_hash[h] = s;
    return s;
}

/* ============================================================
 * TOKEN SCANNER
 * Scans tokens from preprocessed source
 * ============================================================ */

/* The scanner reads from the preprocessor buffer.
 * In -E mode, tokens are not consumed by the parser.
 * In compile mode, tokens drive the parser.
 */

/* Main tokenizer - reads next raw token */
static int scan_raw_tok(TCCState *s) {
    /* Skip whitespace */
    while (s->ch == ' ' || s->ch == '\t' || s->ch == '\r' || s->ch == '\f') bs_adv(s);

    /* Handle preprocessor directives and macros */
    /* First, handle any buffered tokens from macro expansion */
    while (s->bs && !s->bs->buf_len && s->bs->is_string) {
        pop_buffer(s);
    }

    if (!s->ch || (!s->bs)) return TOK_EOF;

    char c = s->ch;

    /* Newline */
    if (c == '\n') {
        bs_adv(s);
        return '\n';
    }

    /* Hash (preprocessor directive) */
    if (c == '#') {
        /* Could be # or ## */
        bs_adv(s);
        if (s->ch == '#') {
            bs_adv(s);
            return TOK_TWOSHARPS;
        }
        return '#';
    }

    /* Identifier or keyword */
    if (is_idstart[(unsigned char)c]) {
        CString cs;
        memset(&cs, 0, sizeof(cs));
        while (is_idstart[(unsigned char)s->ch] || (s->ch >= '0' && s->ch <= '9') ||
               (s->dollars_in_identifiers && s->ch == '$')) {
            cstr_ccat(&cs, s->ch);
            bs_adv(s);
        }
        /* Look up keyword */
        int tok = cs.buf ? kw_lookup(cs.buf) : TOK_IDENT;
        if (tok == TOK_IDENT) {
            /* Check for macro */
            if (cs.buf) {
                Macro *m = macro_find(s, cs.buf);
                if (m && !m->is_undef) {
                    /* Expand macro */
                    if (m->params == NULL) {
                        char *expanded = macro_expand(s, m->body, 0);
                        if (expanded && *expanded) {
                            push_buffer(s, expanded, strlen(expanded), NULL, 1);
                            free(cs.buf);
                            free(expanded);
                            return scan_raw_tok(s);
                        }
