/* Main tokenizer - reads next raw token */
static int scan_raw_tok(TCCState *s) {
    /* Skip whitespace */
    while (s->ch == ' ' || s->ch == '\t' || s->ch == '\r' || s->ch == '\f') bs_adv(s);

    /* Handle preprocessor directives and macros */
    /* First, handle any buffered tokens from macro expansion */
    while (s->bs && !s->bs->buf_len && s->bs->is_string) {
        pop_buffer(s);
    }

    if (!s->ch || (!s->bs)) return TOK_EOF;

    char c = s->ch;

    /* Newline */
    if (c == '\n') {
        bs_adv(s);
        return '\n';
    }

    /* Hash (preprocessor directive) */
    if (c == '#') {
        /* Could be # or ## */
        bs_adv(s);
        if (s->ch == '#') {
            bs_adv(s);
            return TOK_TWOSHARPS;
        }
        return '#';
    }

    /* Identifier or keyword */
    if (is_idstart[(unsigned char)c]) {
        CString cs;
        memset(&cs, 0, sizeof(cs));
        while (is_idstart[(unsigned char)s->ch] || (s->ch >= '0' && s->ch <= '9') ||
               (s->dollars_in_identifiers && s->ch == '$')) {
            cstr_ccat(&cs, s->ch);
            bs_adv(s);
        }
        /* Look up keyword */
        int tok = cs.buf ? kw_lookup(cs.buf) : TOK_IDENT;
        if (tok == TOK_IDENT) {
            /* Check for macro */
            if (cs.buf) {
                Macro *m = macro_find(s, cs.buf);
                if (m && !m->is_undef) {
                    /* Expand macro */
                    if (m->params == NULL) {
                        char *expanded = macro_expand(s, m->body, 0);
                        if (expanded && *expanded) {
                            push_buffer(s, expanded, strlen(expanded), NULL, 1);
                            free(cs.buf);
                            free(expanded);
                            return scan_raw_tok(s);
                        }
                        free(expanded);
                        free(cs.buf);
                        return scan_raw_tok(s);
                    }
                }
            }
        }
        /* Store identifier */
        if (s->tok.tok_str.buf) cstr_reset(&s->tok.tok_str);
        if (cs.buf) {
            s->tok.tok_str.buf = cs.buf;
            s->tok.tok_str.len = strlen(cs.buf);
            s->tok.tok_str.cap = s->tok.tok_str.len + 1;
        }
        return tok;
    }

    /* Number */
    if (isdigit(c) || (c == '.' && isdigit(bs_peek(s)))) {
        CString cs;
        memset(&cs, 0, sizeof(cs));
        int tok;
        scan_number(s, &cs, &tok);
        if (cs.buf) {
            if (s->tok.tok_str.buf) cstr_reset(&s->tok.tok_str);
            s->tok.tok_str = cs;
        }
        return TOK_PPNUM;
    }

    /* String literal */
    if (c == '"' || (c == 'L' && bs_peek(s) == '"') ||
        (c == 'u' && bs_peek(s) == '"') ||
        (c == 'U' && bs_peek(s) == '"')) {
        int is_wide = (c == 'L' || c == 'U');
        if (c != '"') bs_adv(s); /* skip prefix */
        CString cs;
        memset(&cs, 0, sizeof(cs));
        scan_string(s, &cs, '"');
        /* Concatenate adjacent string literals */
        while (s->ch == '"' || (s->ch == 'L' && bs_peek(s) == '"') ||
               (s->ch == 'u' && bs_peek(s) == '"') ||
               (s->ch == 'U' && bs_peek(s) == '"')) {
            /* Skip whitespace first */
            if (s->ch != '"') bs_adv(s);
            scan_string(s, &cs, '"');
        }
        if (s->tok.tok_str.buf) cstr_reset(&s->tok.tok_str);
        s->tok.tok_str = cs;
        return TOK_STR;
    }

    /* Char literal */
    if (c == '\'' || (c == 'L' && bs_peek(s) == '\'')) {
        int is_wide = (c == 'L');
        if (is_wide) bs_adv(s);
        bs_adv(s); /* skip ' */
        int val = 0;
        if (s->ch == '\\') {
            val = scan_escape(s);
        } else {
            val = (unsigned char)s->ch;
            bs_adv(s);
        }
        if (s->ch == '\'') bs_adv(s);
        s->tok.i = val;
        return is_wide ? TOK_LCHAR : TOK_CCHAR;
    }

    /* Operators */
    bs_adv(s);
    switch (c) {
    case '=':
        if (s->ch == '=') { bs_adv(s); return TOK_EQ; }
        return '=';
    case '!':
        if (s->ch == '=') { bs_adv(s); return TOK_NE; }
        return '!';
    case '<':
        if (s->ch == '=') { bs_adv(s); return TOK_LE; }
        if (s->ch == '<') {
            bs_adv(s);
            if (s->ch == '=') { bs_adv(s); return TOK_SHL_ASSIGN; }
            return TOK_SHL;
        }
        return '<';
    case '>':
        if (s->ch == '=') { bs_adv(s); return TOK_GE; }
        if (s->ch == '>') {
            bs_adv(s);
            if (s->ch == '=') { bs_adv(s); return TOK_SAR_ASSIGN; }
            return TOK_SAR;
        }
        return '>';
    case '&':
        if (s->ch == '&') { bs_adv(s); return TOK_LAND; }
        if (s->ch == '=') { bs_adv(s); return TOK_AND_ASSIGN; }
        return '&';
    case '|':
        if (s->ch == '|') { bs_adv(s); return TOK_LOR; }
        if (s->ch == '=') { bs_adv(s); return TOK_OR_ASSIGN; }
        return '|';
    case '+':
        if (s->ch == '+') { bs_adv(s); return TOK_INC; }
        if (s->ch == '=') { bs_adv(s); return TOK_ADD_ASSIGN; }
        return '+';
    case '-':
        if (s->ch == '-') { bs_adv(s); return TOK_DEC; }
        if (s->ch == '>') { bs_adv(s); return TOK_ARROW; }
        if (s->ch == '=') { bs_adv(s); return TOK_SUB_ASSIGN; }
        return '-';
    case '*':
        if (s->ch == '=') { bs_adv(s); return TOK_MUL_ASSIGN; }
        return '*';
    case '/':
        if (s->ch == '=') { bs_adv(s); return TOK_DIV_ASSIGN; }
        return '/';
    case '%':
        if (s->ch == '=') { bs_adv(s); return TOK_MOD_ASSIGN; }
        return '%';
    case '^':
        if (s->ch == '=') { bs_adv(s); return TOK_XOR_ASSIGN; }
        return '^';
    case '.':
        if (s->ch == '.' && bs_peek(s) == '.') {
            bs_adv(s); bs_adv(s);
            return TOK_DOTS;
        }
        return '.';
    case ':': return ':';
    case ';': return ';';
    case ',': return ',';
    case '(': return '(';
    case ')': return ')';
    case '[': return '[';
    case ']': return ']';
    case '{': return '{';
    case '}': return '}';
    case '?': return '?';
    case '~': return '~';
    }

    return c;
}

