 * ============================================================ */

static int preprocess_only(TCCState *s, const char *infile, FILE *out) {
    /* Output initial line directive */
    if (strcmp(infile, "-") != 0) {
        if (s->pp_lineno_mode != 2) {
            fprintf(out, "# 1 \"%s\"\n", infile);
        }
    }
    fprintf(out, "# 1 \"<command line>\" 1\n");

