    for (int i = 0; i < s->nb_include_files; i++) {
        char path[1024];
        if (find_include_file(s, s->include_files[i], 0, NULL, path, sizeof(path))) {
            process_include(s, path, 0, out);
        }
    }

    if (s->pp_lineno_mode != 2) {
        fprintf(out, "# 1 \"%s\" 2\n", infile);
    }

    /* Process the main file */
    if (!strcmp(infile, "-")) {
        /* Read from stdin */
        char *buf = NULL;
        size_t buf_size = 0;
        size_t buf_len = 0;
        char tmp[4096];
        size_t n;
        while ((n = fread(tmp, 1, sizeof(tmp), stdin)) > 0) {
            buf = tcc_realloc(buf, buf_len + n + 2);
            memcpy(buf + buf_len, tmp, n);
            buf_len += n;
        }
        if (buf) {
            buf[buf_len] = '\n';
            buf[buf_len+1] = 0;
            push_buffer(s, buf, buf_len+1, "-", 0);
            preprocess_buffer(s, out, 0);
            pop_buffer(s);
            free(buf);
        }
    } else {
        process_include(s, infile, 0, out);
    }

    /* Output -dM: dump all defined macros */
    if (s->pp_dM) {
        fprintf(out, "\n");
        for (int i = 0; i < MACRO_HASH_SIZE; i++) {
            Macro *m = s->macros[i];
            while (m) {
                if (!m->is_undef) {
                    fprintf(out, "#define %s", m->name);
                    if (m->params) {
                        fprintf(out, "(");
                        for (int j = 0; j < m->nb_params; j++) {
                            if (j > 0) fprintf(out, ",");
                            fprintf(out, "%s", m->params[j]);
                        }
                        if (m->is_variadic) {
                            if (m->nb_params > 0) fprintf(out, ",");
                            fprintf(out, "...");
                        }
                        fprintf(out, ")");
                    }
                    if (m->body && *m->body) {
                        fprintf(out, " %s", m->body);
                    }
                    fprintf(out, "\n");
                }
                m = m->hash_next;
            }
        }
    }

    return s->nb_errors ? 1 : 0;
