/* ============================================================
 * MAIN ENTRY POINT
 * ============================================================ */

int tcc_main(int argc, char **argv) {
    if (!kw_initialized) kw_init();

    /* Handle -ar mode specially */
    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-ar")) {
            if (i+1 < argc) {
                TCCState *s = tcc_state_new();
                int ret = tcc_ar(s, argc-i-1, argv+i+1);
                return ret;
            }
            fprintf(stderr, "usage: tcc -ar [crstvx] lib [files]\n");
            fprintf(stderr, "create library ([abdiopN] not supported).\n");
            return 1;
        }
    }

    TCCState *s = tcc_state_new();
    g_tcc = s;

    /* Add predefined macros early */
    tcc_add_predefined_macros(s);

    /* Parse arguments */
    int ret = tcc_parse_args(s, argc, argv, 1);
    if (ret <= 0) {
        /* 0 = handled (version/help shown), negative = error */
        return ret < 0 ? 1 : 0;
    }

    /* If no files given, show help */
    if (s->nb_files == 0 && !s->pp_dM) {
        print_help(0);
        return 0;
    }

    /* Setup default paths */
    tcc_setup_defaults(s);

    /* Update predefined macros based on flags */
    if (s->char_is_unsigned) {
        macro_define(s, "__CHAR_UNSIGNED__", "1", NULL, 0, 0);
    }

    /* Handle -MD/-MMD: reset dep_files */
    memset(&dep_files, 0, sizeof(dep_files));

    /* Show verbose info */
    if (s->verbose >= 1) {
        print_version();
    }

    /* Preprocessing only mode (-E or -M/-MM) */
    if (s->pp_only || s->gen_deps >= 2) {
        /* Process each input file */
        for (int i = 0; i < s->nb_files; i++) {
            const char *infile = s->files[i];

            /* Output line directive for -E mode */
            FILE *out = stdout;
            if (s->outfile) {
                out = fopen(s->outfile, "w");
                if (!out) {
                    fprintf(stderr, "tcc: error: cannot open '%s'\n", s->outfile);
                    return 1;
                }
            }

            if (s->gen_deps >= 2) {
                /* -M/-MM: output deps, no preprocessing */
                memset(&dep_files, 0, sizeof(dep_files));
                /* Process file to collect deps */
                s->gen_deps = 1;
                preprocess_only(s, infile, fopen("/dev/null", "w"));
                s->gen_deps = 2;

                /* Output dependencies */
                const char *target;
                char base[256];
                const char *slash = strrchr(infile, '/');
                strncpy(base, slash ? slash+1 : infile, sizeof(base)-1);
                char *dot = strrchr(base, '.');
                if (dot) strcpy(dot, ".o");
                target = base;

                fprintf(out, "%s: \\\n  %s", target, infile);
                for (int j = 0; j < dep_files.len; j++) {
                    fprintf(out, " \\\n  %s", (char*)dep_files.buf[j]);
                }
                fprintf(out, "\n");
            } else {
                /* -E: preprocess and output */
                preprocess_only(s, infile, out);
            }

            if (s->outfile && out != stdout) fclose(out);
        }
        return s->nb_errors ? 1 : 0;
    }

    /* Compilation mode */
    if (s->output_type == TCC_OUTPUT_PREPROCESS) {
        /* Same as pp_only */
        for (int i = 0; i < s->nb_files; i++) {
            preprocess_only(s, s->files[i], stdout);
        }
        return s->nb_errors ? 1 : 0;
    }

    /* Determine output file */
    const char *outfile = s->outfile;

    /* Object compilation mode (-c) */
    if (s->output_type == TCC_OUTPUT_OBJ && !s->relocatable) {
        /* Compile each file separately */
        if (s->nb_files > 1 && outfile) {
            fprintf(stderr, "tcc: error: cannot specify output file with -c many files\n");
            return 1;
        }

        for (int i = 0; i < s->nb_files; i++) {
            const char *infile = s->files[i];
            int filetype = s->file_types[i];

            /* Determine output filename */
            char auto_outfile[1024];
            const char *out = outfile;
            if (!out) {
                /* Create .o from source name */
                const char *slash = strrchr(infile, '/');
                const char *base = slash ? slash+1 : infile;
                strncpy(auto_outfile, base, sizeof(auto_outfile)-1);
                char *dot = strrchr(auto_outfile, '.');
                if (dot) strcpy(dot, ".o");
                else strcat(auto_outfile, ".o");
                out = auto_outfile;
            }

            if (s->verbose >= 2) {
                fprintf(stderr, "-> %s\n", infile);
            }

            /* Compile the file */
            int r = compile_file(s, infile, filetype, out);

            if (s->verbose >= 2) {
                fprintf(stderr, "<- %s\n", out);
            }

            if (r != 0) return r;

            /* Generate dependency file if requested */
            if (s->gen_deps) {
                write_dep_file(s, out, infile);
            }
        }
        return s->nb_errors ? 1 : 0;
    }

    /* Link mode: produce executable or shared library */
    if (!outfile) outfile = "a.out";

    /* First compile all source files to temporary objects */
    char **obj_files = calloc(s->nb_files, sizeof(char*));
    int *obj_types = calloc(s->nb_files, sizeof(int));
    int nb_obj = 0;
    char tmp_files[512][64];
    int nb_tmp = 0;

    for (int i = 0; i < s->nb_files; i++) {
        const char *infile = s->files[i];
        int filetype = s->file_types[i];

        if (filetype == FILETYPE_OBJ || filetype == FILETYPE_LIB) {
            obj_files[nb_obj] = tcc_strdup(infile);
            obj_types[nb_obj] = filetype;
            nb_obj++;
        } else if (filetype == FILETYPE_C || filetype == FILETYPE_ASM) {
            /* Compile to temp file */
            char tmpname[64];
            snprintf(tmpname, sizeof(tmpname), "/tmp/tcc_%d_%d.o", getpid(), nb_tmp);
            strncpy(tmp_files[nb_tmp], tmpname, 63);
            nb_tmp++;

            if (s->verbose >= 2) {
                fprintf(stderr, "-> %s\n", infile);
            }

            int r = compile_file(s, infile, filetype, tmpname);
            if (r != 0) {
                /* Cleanup */
                for (int j = 0; j < nb_tmp; j++) unlink(tmp_files[j]);
                return r;
            }

            obj_files[nb_obj] = tcc_strdup(tmpname);
            obj_types[nb_obj] = FILETYPE_OBJ;
            nb_obj++;
        }
    }

    /* Now link */
    if (s->verbose >= 2) {
        fprintf(stderr, "<- %s\n", outfile);
    }

    int link_ret = link_files(s, obj_files, nb_obj, obj_types, outfile);

    /* Cleanup temp files */
    for (int i = 0; i < nb_tmp; i++) {
        unlink(tmp_files[i]);
    }

    for (int i = 0; i < nb_obj; i++) free(obj_files[i]);
    free(obj_files);
    free(obj_types);

    return link_ret || s->nb_errors ? 1 : 0;
}

int main(int argc, char **argv) {
    return tcc_main(argc, argv);
}

