    for (int i = 0; i < nb_obj; i++) free(obj_files[i]);
    free(obj_files);
    free(obj_types);

    return link_ret || s->nb_errors ? 1 : 0;
}

int main(int argc, char **argv) {
    return tcc_main(argc, argv);
}

