static int compile_file(TCCState *s, const char *filename, int filetype, const char *outfile) {
    /* Reset dep tracking */
    /* Reset errors for this file */
    /* Don't reset nb_errors - accumulate */

    if (filetype == FILETYPE_NONE) {
