/* ============================================================
 * LINKER
 * ============================================================ */

/* Link object files into an executable.
 * This is the ELF linker that reads .o files and creates an executable.
 */

/* Read an ELF object file */
typedef struct ObjFile {
    const char *filename;
    uint8_t *data;
    size_t size;
    Elf64_Ehdr *ehdr;
    Elf64_Shdr *shdrs;
    int nb_secs;
    char *shstrtab;
    /* Sections we care about */
    int text_sec, data_sec, data_ro_sec, bss_sec;
    int symtab_sec, strtab_sec;
    int eh_frame_sec;
    /* Relocation sections */
    int rela_text_sec, rela_data_sec, rela_data_ro_sec, rela_eh_frame_sec;
} ObjFile;

static ObjFile *load_obj_file(const char *filename) {
    FILE *f = fopen(filename, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *data = malloc(sz);
    fread(data, 1, sz, f);
    fclose(f);

    if (sz < (long)sizeof(Elf64_Ehdr)) { free(data); return NULL; }
    Elf64_Ehdr *ehdr = (Elf64_Ehdr *)data;
    if (memcmp(ehdr->e_ident, ELFMAG, 4) != 0) { free(data); return NULL; }

    ObjFile *obj = calloc(1, sizeof(ObjFile));
    obj->filename = tcc_strdup(filename);
    obj->data = data;
    obj->size = sz;
    obj->ehdr = ehdr;
    obj->shdrs = (Elf64_Shdr *)(data + ehdr->e_shoff);
    obj->nb_secs = ehdr->e_shnum;
    obj->shstrtab = (char *)(data + obj->shdrs[ehdr->e_shstrndx].sh_offset);

    /* Find key sections */
    obj->text_sec = obj->data_sec = obj->data_ro_sec = obj->bss_sec = -1;
    obj->symtab_sec = obj->strtab_sec = -1;
    obj->eh_frame_sec = -1;
    obj->rela_text_sec = obj->rela_data_sec = -1;
    obj->rela_data_ro_sec = obj->rela_eh_frame_sec = -1;

    for (int i = 0; i < obj->nb_secs; i++) {
        const char *name = obj->shstrtab + obj->shdrs[i].sh_name;
        if (!strcmp(name, ".text")) obj->text_sec = i;
        else if (!strcmp(name, ".data")) obj->data_sec = i;
        else if (!strcmp(name, ".data.ro")) obj->data_ro_sec = i;
        else if (!strcmp(name, ".bss")) obj->bss_sec = i;
        else if (!strcmp(name, ".symtab")) obj->symtab_sec = i;
        else if (!strcmp(name, ".strtab")) obj->strtab_sec = i;
        else if (!strcmp(name, ".eh_frame")) obj->eh_frame_sec = i;
        else if (!strcmp(name, ".rela.text")) obj->rela_text_sec = i;
        else if (!strcmp(name, ".rela.data")) obj->rela_data_sec = i;
        else if (!strcmp(name, ".rela.data.ro")) obj->rela_data_ro_sec = i;
        else if (!strcmp(name, ".rela.eh_frame")) obj->rela_eh_frame_sec = i;
    }

    return obj;
}

static void free_obj_file(ObjFile *obj) {
    free((char*)obj->filename);
    free(obj->data);
    free(obj);
