typedef struct ObjFile {
    const char *filename;
    uint8_t *data;
    size_t size;
    Elf64_Ehdr *ehdr;
    Elf64_Shdr *shdrs;
    int nb_secs;
    char *shstrtab;
    /* Sections we care about */
