        const char *name = obj->shstrtab + obj->shdrs[i].sh_name;
        if (!strcmp(name, ".text")) obj->text_sec = i;
        else if (!strcmp(name, ".data")) obj->data_sec = i;
        else if (!strcmp(name, ".data.ro")) obj->data_ro_sec = i;
        else if (!strcmp(name, ".bss")) obj->bss_sec = i;
        else if (!strcmp(name, ".symtab")) obj->symtab_sec = i;
        else if (!strcmp(name, ".strtab")) obj->strtab_sec = i;
        else if (!strcmp(name, ".eh_frame")) obj->eh_frame_sec = i;
        else if (!strcmp(name, ".rela.text")) obj->rela_text_sec = i;
        else if (!strcmp(name, ".rela.data")) obj->rela_data_sec = i;
        else if (!strcmp(name, ".rela.data.ro")) obj->rela_data_ro_sec = i;
        else if (!strcmp(name, ".rela.eh_frame")) obj->rela_eh_frame_sec = i;
