/* ============================================================
 * EXPRESSION VALUES
 * An expression value can be:
 * - An integer constant
 * - A float constant
 * - A local variable (offset from rbp)
 * - A global symbol (with relocation)
 * - In a register (rax, rcx, xmm0, etc.)
 * - The result of a comparison
 * ============================================================ */

/* Value categories */
#define V_CONST_INT   1  /* integer constant */
#define V_CONST_FLT   2  /* float constant */
#define V_LOCAL       3  /* local variable at [rbp+off] */
#define V_GLOBAL      4  /* global symbol */
#define V_REG_INT     5  /* value in integer register */
#define V_REG_FLT     6  /* value in XMM register */
#define V_CMP         7  /* result of comparison (flags set) */
#define V_LVALUE      8  /* lvalue (address in rax) */
#define V_STACK       9  /* value on stack */

typedef struct Val {
    CType type;      /* type of value */
    int cat;         /* value category (V_*) */
    int reg;         /* register (if V_REG_INT/V_REG_FLT) */
    long long ival;  /* integer constant or local offset */
    double dval;     /* float constant */
    int sym_idx;     /* ELF symbol index (for V_GLOBAL) */
    int cmp_op;      /* comparison operator (for V_CMP) */
    int is_signed;   /* signed comparison? */
    int is_lvalue;   /* is this an lvalue (addressable)? */
    int local_off;   /* stack offset for local */
} Val;

