static void cmp_skip_ws(Compiler *c) {
    while (c->pos < c->src_len) {
        char ch = c->src_buf[c->pos];
        if (ch == ' ' || ch == '\t' || ch == '\r' || ch == '\f' || ch == '\v') {
            c->pos++;
        } else if (ch == '\n') {
            c->pos++;
            c->line_num++;
        } else if (ch == '/') {
            if (c->pos+1 < c->src_len && c->src_buf[c->pos+1] == '/') {
                /* Line comment */
                c->pos += 2;
                while (c->pos < c->src_len && c->src_buf[c->pos] != '\n') c->pos++;
            } else if (c->pos+1 < c->src_len && c->src_buf[c->pos+1] == '*') {
                /* Block comment */
                c->pos += 2;
                while (c->pos+1 < c->src_len) {
                    if (c->src_buf[c->pos] == '*' && c->src_buf[c->pos+1] == '/') {
                        c->pos += 2;
                        break;
                    }
                    if (c->src_buf[c->pos] == '\n') c->line_num++;
                    c->pos++;
                }
            } else break;
        } else if (ch == '#') {
            /* Line directive: # N "filename" */
            c->pos++;
            while (c->pos < c->src_len && (c->src_buf[c->pos] == ' ' || c->src_buf[c->pos] == '\t')) c->pos++;
            if (isdigit(c->src_buf[c->pos])) {
                int new_line = 0;
                while (isdigit(c->src_buf[c->pos])) new_line = new_line*10 + c->src_buf[c->pos++]-'0';
                c->line_num = new_line - 1;
                /* Skip to filename */
                while (c->pos < c->src_len && c->src_buf[c->pos] != '"' && c->src_buf[c->pos] != '\n') c->pos++;
                if (c->pos < c->src_len && c->src_buf[c->pos] == '"') {
                    c->pos++;
                    int fn_start = c->pos;
                    while (c->pos < c->src_len && c->src_buf[c->pos] != '"') c->pos++;
                    int fn_len = c->pos - fn_start;
                    char *fn = malloc(fn_len+1);
                    memcpy(fn, c->src_buf+fn_start, fn_len);
                    fn[fn_len] = 0;
                    c->tok_file = fn;
                    if (c->pos < c->src_len) c->pos++;
                }
            }
            /* Skip rest of line */
            while (c->pos < c->src_len && c->src_buf[c->pos] != '\n') c->pos++;
        } else {
            break;
        }
    }
}

static char cmp_peek(Compiler *c) {
    if (c->pos < c->src_len) return c->src_buf[c->pos];
    return 0;
}

static char cmp_peek2(Compiler *c) {
    if (c->pos+1 < c->src_len) return c->src_buf[c->pos+1];
    return 0;
}

/* Parse escape sequence in string/char literal */
static int cmp_escape(Compiler *c) {
    c->pos++; /* skip \ */
    if (c->pos >= c->src_len) return '\\';
    char ch = c->src_buf[c->pos++];
    switch (ch) {
    case 'n': return '\n';
    case 't': return '\t';
    case 'r': return '\r';
    case 'a': return '\a';
    case 'b': return '\b';
    case 'f': return '\f';
    case 'v': return '\v';
    case '\\': return '\\';
    case '\'': return '\'';
    case '"': return '"';
    case '?': return '?';
    case '0': case '1': case '2': case '3':
    case '4': case '5': case '6': case '7': {
        int v = ch - '0';
        for (int i = 1; i < 3 && c->pos < c->src_len && c->src_buf[c->pos] >= '0' && c->src_buf[c->pos] <= '7'; i++) {
