        while (c->pos < c->src_len && isxdigit(c->src_buf[c->pos])) {
            char d = c->src_buf[c->pos++];
            v = v*16 + (d >= 'a' ? d-'a'+10 : d >= 'A' ? d-'A'+10 : d-'0');
        }
        return v;
    }
    case 'u': {
        int v = 0;
        for (int i = 0; i < 4 && c->pos < c->src_len && isxdigit(c->src_buf[c->pos]); i++) {
            char d = c->src_buf[c->pos++];
            v = v*16 + (d >= 'a' ? d-'a'+10 : d >= 'A' ? d-'A'+10 : d-'0');
