                base = 8; c->pos++;
                while (c->pos < c->src_len && c->src_buf[c->pos] >= '0' && c->src_buf[c->pos] <= '7') {
                    ival = ival*8 + (c->src_buf[c->pos++]-'0');
                }
            } else {
                c->pos++; /* skip 0 */
            }
        } else if (ch == '.') {
            is_float = 1;
        } else {
            while (c->pos < c->src_len && isdigit(c->src_buf[c->pos])) {
                ival = ival*10 + (c->src_buf[c->pos++]-'0');
            }
        }

        /* Float suffix or decimal part */
        if (c->pos < c->src_len && c->src_buf[c->pos] == '.') {
            is_float = 1;
        }
        if (c->pos < c->src_len && (c->src_buf[c->pos] == 'e' || c->src_buf[c->pos] == 'E')) {
            is_float = 1;
        }
        if (c->pos < c->src_len && (c->src_buf[c->pos] == 'p' || c->src_buf[c->pos] == 'P')) {
