            if (c->pos < c->src_len) c->pos++; /* skip closing " */

            /* Check for adjacent string */
            cmp_skip_ws(c);
            if (c->pos < c->src_len && (c->src_buf[c->pos] == '"' ||
                ((c->src_buf[c->pos] == 'L' || c->src_buf[c->pos] == 'u' || c->src_buf[c->pos] == 'U') &&
                 c->pos+1 < c->src_len && c->src_buf[c->pos+1] == '"'))) {
                if (c->src_buf[c->pos] != '"') c->pos++;
                c->pos++; /* skip " */
                continue;
