    if (ch == '\'' || (ch == 'L' && cmp_peek2(c) == '\'')) {
        c->tok_is_wide = (ch == 'L');
        if (c->tok_is_wide) c->pos++;
        c->pos++; /* skip ' */
        int v = 0;
        if (c->pos < c->src_len && c->src_buf[c->pos] == '\\') {
            v = cmp_escape(c);
        } else if (c->pos < c->src_len) {
            v = (unsigned char)c->src_buf[c->pos++];
