        if (cmp_peek(c) == '>') {
            c->pos++;
            if (cmp_peek(c) == '=') { c->pos++; c->tok = TOK_SAR_ASSIGN; return; }
            c->tok = TOK_SAR; return;
        }
        c->tok = '>'; return;
    case '&':
        if (cmp_peek(c) == '&') { c->pos++; c->tok = TOK_LAND; return; }
        if (cmp_peek(c) == '=') { c->pos++; c->tok = TOK_AND_ASSIGN; return; }
        c->tok = '&'; return;
    case '|':
