        if (cmp_peek(c) == '=') { c->pos++; c->tok = TOK_ADD_ASSIGN; return; }
        c->tok = '+'; return;
    case '-':
        if (cmp_peek(c) == '-') { c->pos++; c->tok = TOK_DEC; return; }
        if (cmp_peek(c) == '>') { c->pos++; c->tok = TOK_ARROW; return; }
        if (cmp_peek(c) == '=') { c->pos++; c->tok = TOK_SUB_ASSIGN; return; }
        c->tok = '-'; return;
    case '*':
        if (cmp_peek(c) == '=') { c->pos++; c->tok = TOK_MUL_ASSIGN; return; }
        c->tok = '*'; return;
    case '/':
        if (cmp_peek(c) == '=') { c->pos++; c->tok = TOK_DIV_ASSIGN; return; }
        c->tok = '/'; return;
    case '%':
        if (cmp_peek(c) == '=') { c->pos++; c->tok = TOK_MOD_ASSIGN; return; }
        c->tok = '%'; return;
    case '^':
        if (cmp_peek(c) == '=') { c->pos++; c->tok = TOK_XOR_ASSIGN; return; }
        c->tok = '^'; return;
    case '.':
        if (cmp_peek(c) == '.' && c->pos+1 < c->src_len && c->src_buf[c->pos+1] == '.') {
            c->pos += 2; c->tok = TOK_DOTS; return;
        }
        c->tok = '.'; return;
    case ':': c->tok = ':'; return;
    case ';': c->tok = ';'; return;
    case ',': c->tok = ','; return;
    case '(': c->tok = '('; return;
    case ')': c->tok = ')'; return;
    case '[': c->tok = '['; return;
    case ']': c->tok = ']'; return;
    case '{': c->tok = '{'; return;
    case '}': c->tok = '}'; return;
    case '?': c->tok = '?'; return;
    case '~': c->tok = '~'; return;
    case '#':
        if (cmp_peek(c) == '#') { c->pos++; c->tok = TOK_TWOSHARPS; return; }
        c->tok = '#'; return;
    default:
        c->tok = ch; return;
    }
