            char next = c->src_buf[c->pos+1];
            if (next == 'x' || next == 'X') {
                base = 16; c->pos += 2;
                while (c->pos < c->src_len && isxdigit(c->src_buf[c->pos])) {
                    char d = c->src_buf[c->pos++];
                    ival = ival*16 + (d >= 'a' ? d-'a'+10 : d >= 'A' ? d-'A'+10 : d-'0');
                }
            } else if (next == 'b' || next == 'B') {
                base = 2; c->pos += 2;
                while (c->pos < c->src_len && (c->src_buf[c->pos] == '0' || c->src_buf[c->pos] == '1')) {
                    ival = ival*2 + (c->src_buf[c->pos++]-'0');
                }
            } else if (isdigit(next)) {
                base = 8; c->pos++;
                while (c->pos < c->src_len && c->src_buf[c->pos] >= '0' && c->src_buf[c->pos] <= '7') {
                    ival = ival*8 + (c->src_buf[c->pos++]-'0');
                }
            } else {
                c->pos++; /* skip 0 */
            }
        } else if (ch == '.') {
            is_float = 1;
        } else {
            while (c->pos < c->src_len && isdigit(c->src_buf[c->pos])) {
                ival = ival*10 + (c->src_buf[c->pos++]-'0');
            }
        }

        /* Float suffix or decimal part */
        if (c->pos < c->src_len && c->src_buf[c->pos] == '.') {
            is_float = 1;
        }
        if (c->pos < c->src_len && (c->src_buf[c->pos] == 'e' || c->src_buf[c->pos] == 'E')) {
            is_float = 1;
        }
        if (c->pos < c->src_len && (c->src_buf[c->pos] == 'p' || c->src_buf[c->pos] == 'P')) {
            is_float = 1;
        }

        if (is_float) {
            /* Re-parse as float */
            int len = c->pos - start + 64;
            char *tmp = malloc(len);
            /* Collect the rest */
            c->pos = start;
            int i = 0;
            while (c->pos < c->src_len && (isxdigit(c->src_buf[c->pos]) ||
                   c->src_buf[c->pos] == '.' || c->src_buf[c->pos] == 'e' || c->src_buf[c->pos] == 'E' ||
                   c->src_buf[c->pos] == 'p' || c->src_buf[c->pos] == 'P' ||
                   c->src_buf[c->pos] == '+' || c->src_buf[c->pos] == '-' ||
                   c->src_buf[c->pos] == 'x' || c->src_buf[c->pos] == 'X' ||
                   c->src_buf[c->pos] == '0')) {
                if (i < len-1) tmp[i++] = c->src_buf[c->pos];
                c->pos++;
            }
            tmp[i] = 0;
            dval = strtod(tmp, NULL);
            free(tmp);
            c->tok_float_type = 2; /* double by default */
            /* Check suffix */
            if (c->pos < c->src_len && (c->src_buf[c->pos] == 'f' || c->src_buf[c->pos] == 'F')) {
                c->tok_float_type = 1; c->pos++;
            } else if (c->pos < c->src_len && (c->src_buf[c->pos] == 'l' || c->src_buf[c->pos] == 'L')) {
                c->tok_float_type = 3; c->pos++;
            }
            c->tok_dval = dval;
            c->tok = TOK_PPNUM;
            c->tok_is_float = 1;
            return;
        }

        /* Integer suffixes */
        c->tok_is_unsigned = 0;
        c->tok_is_long = 0;
        c->tok_is_longlong = 0;
        while (c->pos < c->src_len) {
            char s2 = c->src_buf[c->pos];
            if (s2 == 'u' || s2 == 'U') { c->tok_is_unsigned = 1; c->pos++; }
            else if (s2 == 'l' || s2 == 'L') {
                if (c->tok_is_long) { c->tok_is_longlong = 1; c->tok_is_long = 0; }
                else c->tok_is_long = 1;
                c->pos++;
            } else break;
        }
        c->tok_ival = ival;
        c->tok_uval = (unsigned long long)ival;
        c->tok_is_float = 0;
        c->tok = TOK_PPNUM;
        return;
    }

    /* String literal */
    if (ch == '"' || (ch == 'L' && cmp_peek2(c) == '"') ||
        (ch == 'u' && cmp_peek2(c) == '"') || (ch == 'U' && cmp_peek2(c) == '"') ||
        (ch == 'u' && c->pos+1 < c->src_len && c->src_buf[c->pos+1] == '8' && 
         c->pos+2 < c->src_len && c->src_buf[c->pos+2] == '"')) {
        c->tok_is_wide = 0;
        if (ch != '"') {
            if (ch == 'L' || ch == 'U') c->tok_is_wide = 1;
            c->pos++; /* skip prefix */
            if (c->pos < c->src_len && c->src_buf[c->pos] == '8') c->pos++; /* u8 */
        }
        c->pos++; /* skip " */
        int slen = 0;
        /* Concatenate adjacent strings */
        while (1) {
            while (c->pos < c->src_len && c->src_buf[c->pos] != '"') {
                int v;
                if (c->src_buf[c->pos] == '\\') {
                    v = cmp_escape(c);
                } else {
                    v = (unsigned char)c->src_buf[c->pos++];
                }
                if (slen < (int)sizeof(c->tok_str)-4) {
                    c->tok_str[slen++] = v;
                }
            }
            if (c->pos < c->src_len) c->pos++; /* skip closing " */

            /* Check for adjacent string */
            cmp_skip_ws(c);
            if (c->pos < c->src_len && (c->src_buf[c->pos] == '"' ||
                ((c->src_buf[c->pos] == 'L' || c->src_buf[c->pos] == 'u' || c->src_buf[c->pos] == 'U') &&
                 c->pos+1 < c->src_len && c->src_buf[c->pos+1] == '"'))) {
                if (c->src_buf[c->pos] != '"') c->pos++;
                c->pos++; /* skip " */
                continue;
            }
            break;
        }
        c->tok_str[slen] = 0;
        c->tok_str_len = slen;
        c->tok = TOK_STR;
        return;
    }

    /* Char literal */
    if (ch == '\'' || (ch == 'L' && cmp_peek2(c) == '\'')) {
        c->tok_is_wide = (ch == 'L');
        if (c->tok_is_wide) c->pos++;
        c->pos++; /* skip ' */
        int v = 0;
        if (c->pos < c->src_len && c->src_buf[c->pos] == '\\') {
            v = cmp_escape(c);
        } else if (c->pos < c->src_len) {
            v = (unsigned char)c->src_buf[c->pos++];
        }
        if (c->pos < c->src_len && c->src_buf[c->pos] == '\'') c->pos++;
        c->tok_ival = v;
        c->tok = TOK_CCHAR;
        return;
    }

    /* Operators */
    c->pos++;
    switch (ch) {
    case '=':
        if (cmp_peek(c) == '=') { c->pos++; c->tok = TOK_EQ; return; }
        c->tok = '='; return;
    case '!':
        if (cmp_peek(c) == '=') { c->pos++; c->tok = TOK_NE; return; }
        c->tok = '!'; return;
    case '<':
        if (cmp_peek(c) == '=') { c->pos++; c->tok = TOK_LE; return; }
        if (cmp_peek(c) == '<') {
            c->pos++;
            if (cmp_peek(c) == '=') { c->pos++; c->tok = TOK_SHL_ASSIGN; return; }
            c->tok = TOK_SHL; return;
        }
        c->tok = '<'; return;
    case '>':
        if (cmp_peek(c) == '=') { c->pos++; c->tok = TOK_GE; return; }
        if (cmp_peek(c) == '>') {
            c->pos++;
            if (cmp_peek(c) == '=') { c->pos++; c->tok = TOK_SAR_ASSIGN; return; }
            c->tok = TOK_SAR; return;
        }
        c->tok = '>'; return;
    case '&':
        if (cmp_peek(c) == '&') { c->pos++; c->tok = TOK_LAND; return; }
        if (cmp_peek(c) == '=') { c->pos++; c->tok = TOK_AND_ASSIGN; return; }
        c->tok = '&'; return;
    case '|':
        if (cmp_peek(c) == '|') { c->pos++; c->tok = TOK_LOR; return; }
        if (cmp_peek(c) == '=') { c->pos++; c->tok = TOK_OR_ASSIGN; return; }
        c->tok = '|'; return;
    case '+':
        if (cmp_peek(c) == '+') { c->pos++; c->tok = TOK_INC; return; }
        if (cmp_peek(c) == '=') { c->pos++; c->tok = TOK_ADD_ASSIGN; return; }
        c->tok = '+'; return;
    case '-':
        if (cmp_peek(c) == '-') { c->pos++; c->tok = TOK_DEC; return; }
        if (cmp_peek(c) == '>') { c->pos++; c->tok = TOK_ARROW; return; }
        if (cmp_peek(c) == '=') { c->pos++; c->tok = TOK_SUB_ASSIGN; return; }
        c->tok = '-'; return;
    case '*':
        if (cmp_peek(c) == '=') { c->pos++; c->tok = TOK_MUL_ASSIGN; return; }
        c->tok = '*'; return;
    case '/':
        if (cmp_peek(c) == '=') { c->pos++; c->tok = TOK_DIV_ASSIGN; return; }
        c->tok = '/'; return;
    case '%':
        if (cmp_peek(c) == '=') { c->pos++; c->tok = TOK_MOD_ASSIGN; return; }
        c->tok = '%'; return;
    case '^':
        if (cmp_peek(c) == '=') { c->pos++; c->tok = TOK_XOR_ASSIGN; return; }
        c->tok = '^'; return;
    case '.':
        if (cmp_peek(c) == '.' && c->pos+1 < c->src_len && c->src_buf[c->pos+1] == '.') {
            c->pos += 2; c->tok = TOK_DOTS; return;
        }
        c->tok = '.'; return;
    case ':': c->tok = ':'; return;
    case ';': c->tok = ';'; return;
    case ',': c->tok = ','; return;
    case '(': c->tok = '('; return;
    case ')': c->tok = ')'; return;
    case '[': c->tok = '['; return;
    case ']': c->tok = ']'; return;
    case '{': c->tok = '{'; return;
    case '}': c->tok = '}'; return;
    case '?': c->tok = '?'; return;
    case '~': c->tok = '~'; return;
    case '#':
        if (cmp_peek(c) == '#') { c->pos++; c->tok = TOK_TWOSHARPS; return; }
        c->tok = '#'; return;
    default:
        c->tok = ch; return;
    }
}

