/* ============================================================
 * TYPE PARSER
 * Parses C type declarations
 * ============================================================ */

/* Forward declarations for the parser */
static void expr(Compiler *c, Val *v);
static void assign_expr(Compiler *c, Val *v);
static void cond_expr(Compiler *c, Val *v);
static void or_expr(Compiler *c, Val *v);
static void and_expr(Compiler *c, Val *v);
static void bor_expr(Compiler *c, Val *v);
static void bxor_expr(Compiler *c, Val *v);
static void band_expr(Compiler *c, Val *v);
static void eq_expr(Compiler *c, Val *v);
static void rel_expr(Compiler *c, Val *v);
static void shift_expr(Compiler *c, Val *v);
static void add_expr(Compiler *c, Val *v);
static void mul_expr(Compiler *c, Val *v);
static void unary_expr(Compiler *c, Val *v);
static void postfix_expr(Compiler *c, Val *v);
static void primary_expr(Compiler *c, Val *v);
static void compound_stmt(Compiler *c);
static void stmt(Compiler *c);
static void parse_decl(Compiler *c, int is_global);
static int parse_type_spec(Compiler *c, CType *type, int *storage, int *align_attr);
static void parse_declarator(Compiler *c, CType *base_type, char *name_out, int name_size, CType *full_type);

/* Error helper */
static void cmp_error(Compiler *c, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    fprintf(stderr, "%s:%d: error: ", c->tok_file ? c->tok_file : c->src_filename, c->tok_line);
    vfprintf(stderr, fmt, ap);
    fprintf(stderr, "\n");
    va_end(ap);
    c->s->nb_errors++;
    /* Try to recover - skip to next semicolon or end */
}

static void cmp_warning(Compiler *c, const char *fmt, ...) {
    if (c->s->warn_none) return;
    va_list ap;
    va_start(ap, fmt);
    fprintf(stderr, "%s:%d: warning: ", c->tok_file ? c->tok_file : c->src_filename, c->tok_line);
    vfprintf(stderr, fmt, ap);
    fprintf(stderr, "\n");
    va_end(ap);
    if (c->s->warn_error) c->s->nb_errors++;
}

static void expect(Compiler *c, int tok) {
    if (c->tok != tok) {
        char msg[64];
        if (tok < 128 && isprint(tok)) {
            snprintf(msg, sizeof(msg), "'%c'", tok);
        } else if (tok == TOK_IDENT) {
            snprintf(msg, sizeof(msg), "identifier");
        } else if (tok == ';') {
            snprintf(msg, sizeof(msg), "';'");
        } else {
            snprintf(msg, sizeof(msg), "token %d", tok);
        }
        char got[64];
        if (c->tok < 128 && isprint(c->tok)) {
            snprintf(got, sizeof(got), "'%c'", c->tok);
        } else if (c->tok == TOK_IDENT) {
            snprintf(got, sizeof(got), "'%s'", c->tok_str);
        } else if (c->tok == TOK_EOF) {
            snprintf(got, sizeof(got), "'<eof>'");
        } else {
            snprintf(got, sizeof(got), "token %d", c->tok);
        }
        cmp_error(c, "%s expected (got %s)", msg, got);
    }
    cmp_next(c);
}

/* Lookup typedef */
static struct TypedefEntry *find_typedef(Compiler *c, const char *name) {
    unsigned h = sym_hashfn(name) & 255;
    struct TypedefEntry *e = c->typedefs[h];
    while (e) {
        if (!strcmp(e->name, name)) return e;
        e = e->next;
    }
    return NULL;
}

static void add_typedef(Compiler *c, const char *name, CType *type) {
    struct TypedefEntry *e = malloc(sizeof(struct TypedefEntry));
    e->name = tcc_strdup(name);
    e->type = *type;
    unsigned h = sym_hashfn(name) & 255;
    e->next = c->typedefs[h];
    c->typedefs[h] = e;
}

/* Lookup variable */
static struct VarEntry *find_var(Compiler *c, const char *name) {
    struct VarScope *scope = c->scope;
    while (scope) {
        unsigned h = sym_hashfn(name) & 255;
        struct VarEntry *e = scope->vars[h];
        while (e) {
            if (!strcmp(e->name, name)) return e;
            e = e->next;
        }
        scope = scope->parent;
    }
    return NULL;
}

static struct VarEntry *add_var(Compiler *c, const char *name, CType *type, int is_local) {
    if (!c->scope) {
        c->scope = calloc(1, sizeof(struct VarScope));
    }
    struct VarEntry *e = calloc(1, sizeof(struct VarEntry));
    e->name = tcc_strdup(name);
    e->type = *type;
    e->is_local = is_local;
    unsigned h = sym_hashfn(name) & 255;
    e->next = c->scope->vars[h];
    c->scope->vars[h] = e;
    return e;
}

/* Push/pop scope */
static void push_scope(Compiler *c) {
    struct VarScope *ns = calloc(1, sizeof(struct VarScope));
    ns->parent = c->scope;
    c->scope = ns;
}

static void pop_scope(Compiler *c) {
    if (!c->scope) return;
    struct VarScope *old = c->scope;
    c->scope = old->parent;
    /* Free variables in old scope */
    for (int i = 0; i < 256; i++) {
        struct VarEntry *e = old->vars[i];
        while (e) {
            struct VarEntry *next = e->next;
            free(e->name);
            free(e);
            e = next;
        }
    }
    free(old);
}

/* Tag lookup */
static struct TagEntry *find_tag(Compiler *c, const char *name) {
    unsigned h = sym_hashfn(name) & 255;
    struct TagEntry *e = c->tags[h];
    while (e) {
        if (!strcmp(e->name, name)) return e;
        e = e->next;
    }
    return NULL;
}

static TypeDef *get_or_create_tag(Compiler *c, const char *name, int kind) {
    struct TagEntry *e = find_tag(c, name);
    if (e) return e->def;
    e = malloc(sizeof(struct TagEntry));
    e->name = tcc_strdup(name);
    e->def = calloc(1, sizeof(TypeDef));
    e->def->kind = kind;
    e->def->tag = tcc_strdup(name);
    unsigned h = sym_hashfn(name) & 255;
    e->next = c->tags[h];
    c->tags[h] = e;
    return e->def;
}

/* Parse struct/union definition */
static TypeDef *parse_struct_union(Compiler *c, int is_union) {
    char tag[256] = "";

    /* Optional tag */
    if (c->tok == TOK_IDENT) {
        strncpy(tag, c->tok_str, sizeof(tag)-1);
        cmp_next(c);
    }

    TypeDef *def;
    if (*tag) {
        def = get_or_create_tag(c, tag, is_union ? TK_UNION : TK_STRUCT);
    } else {
        def = calloc(1, sizeof(TypeDef));
        def->kind = is_union ? TK_UNION : TK_STRUCT;
        def->tag = NULL;
    }

    if (c->tok != '{') {
        /* Forward reference */
        return def;
    }

    cmp_next(c); /* skip { */

    /* Parse fields */
    int total_size = 0;
    int max_align = 1;
    Symbol *fields = NULL;
    Symbol **last = &fields;

    while (c->tok != '}' && c->tok != TOK_EOF) {
        /* Parse field type */
        CType base_type;
        int storage = 0, align_attr = 0;
        if (!parse_type_spec(c, &base_type, &storage, &align_attr)) {
            /* Error recovery */
            while (c->tok != ';' && c->tok != '}' && c->tok != TOK_EOF) cmp_next(c);
            if (c->tok == ';') cmp_next(c);
            continue;
        }

        /* Parse field declarators */
        while (c->tok != ';' && c->tok != TOK_EOF) {
            CType field_type;
            char fname[256] = "";

            /* Bitfield? */
            if (c->tok == ':') {
                /* Anonymous bitfield */
                cmp_next(c);
                /* Skip bitfield width expression */
                while (c->tok != ';' && c->tok != ',' && c->tok != TOK_EOF) cmp_next(c);
                break;
            }

            parse_declarator(c, &base_type, fname, sizeof(fname), &field_type);

            /* Bitfield? */
            int bit_size = -1;
            if (c->tok == ':') {
                cmp_next(c);
                /* Parse constant expression for bit width */
                if (c->tok == TOK_PPNUM) {
                    bit_size = (int)c->tok_ival;
                    cmp_next(c);
                }
            }

            /* Get field size and alignment */
            int fsize, falign;
            fsize = type_size(&field_type, &falign);
            if (align_attr > falign) falign = align_attr;

            /* Create field symbol */
            Symbol *field = calloc(1, sizeof(Symbol));
            field->name = *fname ? tcc_strdup(fname) : NULL;
            field->type = field_type;
            field->is_field = 1;

            if (bit_size >= 0) {
                field->bit_size = bit_size;
                /* Simplify: treat bitfields as their underlying type */
            }

            if (is_union) {
                /* All fields start at offset 0 */
                field->addr = 0;
                if (fsize > total_size) total_size = fsize;
            } else {
                /* Align field */
                total_size = (total_size + falign-1) & ~(falign-1);
                field->addr = total_size;
                total_size += fsize;
            }

            if (falign > max_align) max_align = falign;

            *last = field;
            last = &field->next;

            if (c->tok == ',') cmp_next(c);
            else break;
        }

        if (c->tok == ';') cmp_next(c);
    }

    expect(c, '}');

    /* Final alignment */
    total_size = (total_size + max_align-1) & ~(max_align-1);

    def->fields = fields;
    def->size = total_size;
    def->align = max_align;
    def->defined = 1;

    return def;
}

/* Parse enum definition */
static TypeDef *parse_enum(Compiler *c) {
    char tag[256] = "";

    if (c->tok == TOK_IDENT) {
        strncpy(tag, c->tok_str, sizeof(tag)-1);
        cmp_next(c);
    }

    TypeDef *def;
    if (*tag) {
        def = get_or_create_tag(c, tag, TK_ENUM);
    } else {
        def = calloc(1, sizeof(TypeDef));
        def->kind = TK_ENUM;
    }

    if (c->tok != '{') return def;
    cmp_next(c);

    int val = 0;
    while (c->tok != '}' && c->tok != TOK_EOF) {
        char name[256] = "";
        if (c->tok != TOK_IDENT) {
            cmp_error(c, "identifier expected in enum");
            while (c->tok != ',' && c->tok != '}' && c->tok != TOK_EOF) cmp_next(c);
        } else {
            strncpy(name, c->tok_str, sizeof(name)-1);
            cmp_next(c);
        }

        if (c->tok == '=') {
            cmp_next(c);
            /* Parse constant expression */
            /* Simple: just handle integer constants */
            int negate = 0;
            if (c->tok == '-') { negate = 1; cmp_next(c); }
            if (c->tok == TOK_PPNUM && !c->tok_is_float) {
                val = (int)(negate ? -c->tok_ival : c->tok_ival);
                cmp_next(c);
            }
        }

        /* Add enum constant as a global constant */
        if (*name) {
            /* Add to global scope as integer constant */
            CType t;
            t.t = VT_INT | VT_CONSTANT;
            t.ref = NULL;
            struct VarEntry *e = add_var(c, name, &t, 0);
            e->is_local = 0;
            e->sym_idx = -1; /* No ELF sym needed for enum constants */
            /* Store value - we need a way to access it */
            /* For now, add as a global symbol with special value */
            /* We'll use a "define" approach */
            /* Actually, let's just add it with a special section = -2 (constant) */
        }

        val++;
        if (c->tok == ',') cmp_next(c);
    }

    expect(c, '}');

    def->size = 4;
    def->align = 4;
    def->defined = 1;

    return def;
}

/* Check if token is a type specifier */
static int is_type_specifier(Compiler *c) {
    switch (c->tok) {
    case TOK_INT: case TOK_VOID: case TOK_CHAR: case TOK_SHORT: case TOK_LONG:
    case TOK_SIGNED: case TOK_UNSIGNED: case TOK_FLOAT: case TOK_DOUBLE:
    case TOK_CONST: case TOK_VOLATILE: case TOK_RESTRICT:
    case TOK__BOOL: case TOK__COMPLEX: case TOK___COMPLEX:
    case TOK_STRUCT: case TOK_UNION: case TOK_ENUM:
    case TOK_EXTERN: case TOK_STATIC: case TOK_TYPEDEF: case TOK_AUTO: case TOK_REGISTER:
    case TOK_INLINE: case TOK__INLINE: case TOK___INLINE__: case TOK___FORCEINLINE:
    case TOK__NORETURN: case TOK___THREAD:
    case TOK___ATTRIBUTE__: case TOK___ATTRIBUTE:
    case TOK___VOLATILE__: case TOK___VOLATILE: case TOK___CONST__: case TOK___CONST:
    case TOK___EXTENSION__:
    case TOK__ALIGNAS:
        return 1;
    case TOK_IDENT:
        /* Check if it's a typedef name */
        return find_typedef(c, c->tok_str) != NULL;
    case TOK_TYPEOF: case TOK___TYPEOF__: case TOK___TYPEOF:
        return 1;
    default:
        return 0;
    }
}

/* Parse type attributes (__attribute__, __declspec, etc.) */
static void parse_attributes(Compiler *c, int *packed, int *aligned, int *noreturn_attr, int *visibility) {
    while (c->tok == TOK___ATTRIBUTE__ || c->tok == TOK___ATTRIBUTE ||
           c->tok == TOK___DECLSPEC || c->tok == TOK___CDECL ||
           c->tok == TOK___STDCALL || c->tok == TOK___FASTCALL) {
        if (c->tok == TOK___ATTRIBUTE__ || c->tok == TOK___ATTRIBUTE) {
            cmp_next(c);
            expect(c, '(');
            expect(c, '(');
            while (c->tok != ')' && c->tok != TOK_EOF) {
                if (c->tok == TOK_IDENT || c->tok > 255) {
                    char attrname[64];
                    strncpy(attrname, c->tok_str, sizeof(attrname)-1);
                    cmp_next(c);
                    if (c->tok == '(') {
                        /* Skip attribute arguments */
                        cmp_next(c);
                        int depth = 1;
                        while (depth > 0 && c->tok != TOK_EOF) {
                            if (c->tok == '(') depth++;
                            else if (c->tok == ')') depth--;
                            if (depth > 0) cmp_next(c);
                        }
                        expect(c, ')');
                    }
                    if (!strcmp(attrname, "packed")) { if (packed) *packed = 1; }
                    else if (!strcmp(attrname, "noreturn")) { if (noreturn_attr) *noreturn_attr = 1; }
                }
                if (c->tok == ',') cmp_next(c);
                else break;
            }
            expect(c, ')');
            expect(c, ')');
        } else {
            cmp_next(c);
        }
    }
}

/* Parse type specifier - returns 1 if a type was found, 0 otherwise */
static int parse_type_spec(Compiler *c, CType *type, int *storage, int *align_attr) {
    int has_type = 0;
    int is_signed = -1; /* -1=unspecified, 0=unsigned, 1=signed */
    int is_long = 0;
    int is_long_long = 0;
    int is_short = 0;
    int is_complex = 0;
    int bt = -1; /* base type */
    int flags = 0;
    int packed = 0;

    if (storage) *storage = 0;
    if (align_attr) *align_attr = 0;
    type->t = VT_INT; /* default */
    type->ref = NULL;

    for (;;) {
        int t = c->tok;

        /* Skip extension markers */
        if (t == TOK___EXTENSION__) { cmp_next(c); continue; }

        /* Storage class */
        if (t == TOK_EXTERN) {
            if (storage) *storage |= VT_EXTERN;
            cmp_next(c); has_type = 1; continue;
        }
        if (t == TOK_STATIC) {
            if (storage) *storage |= VT_STATIC;
            cmp_next(c); has_type = 1; continue;
        }
        if (t == TOK_TYPEDEF) {
            if (storage) *storage |= VT_TYPEDEF;
            cmp_next(c); has_type = 1; continue;
        }
        if (t == TOK_AUTO || t == TOK_REGISTER) {
            cmp_next(c); has_type = 1; continue;
        }
        if (t == TOK_INLINE || t == TOK__INLINE || t == TOK___INLINE__ ||
            t == TOK___FORCEINLINE) {
            if (storage) *storage |= VT_INLINE;
            cmp_next(c); has_type = 1; continue;
        }
        if (t == TOK__NORETURN) {
            cmp_next(c); has_type = 1; continue;
        }
        if (t == TOK___THREAD) {
            cmp_next(c); has_type = 1; continue;
        }

        /* Type qualifiers */
        if (t == TOK_CONST || t == TOK___CONST || t == TOK___CONST__) {
            flags |= VT_CONSTANT; cmp_next(c); has_type = 1; continue;
        }
        if (t == TOK_VOLATILE || t == TOK___VOLATILE || t == TOK___VOLATILE__) {
            flags |= VT_VOLATILE; cmp_next(c); has_type = 1; continue;
        }
        if (t == TOK_RESTRICT) {
            cmp_next(c); has_type = 1; continue;
        }

        /* Attributes */
        if (t == TOK___ATTRIBUTE__ || t == TOK___ATTRIBUTE) {
            parse_attributes(c, &packed, align_attr, NULL, NULL);
            has_type = 1; continue;
        }
        if (t == TOK___CDECL || t == TOK___STDCALL || t == TOK___FASTCALL || t == TOK___REGPARM) {
            cmp_next(c);
            if (c->tok == '(') {
                cmp_next(c);
                while (c->tok != ')' && c->tok != TOK_EOF) cmp_next(c);
                expect(c, ')');
            }
            has_type = 1; continue;
        }
        if (t == TOK___DECLSPEC) {
            cmp_next(c);
            expect(c, '(');
            while (c->tok != ')' && c->tok != TOK_EOF) cmp_next(c);
            expect(c, ')');
            has_type = 1; continue;
        }
        if (t == TOK__ALIGNAS) {
            cmp_next(c);
            expect(c, '(');
            /* Parse alignment expression */
            if (c->tok == TOK_PPNUM) {
                if (align_attr) *align_attr = (int)c->tok_ival;
                cmp_next(c);
            } else {
                CType dummy;
                int dummy_storage = 0;
                parse_type_spec(c, &dummy, &dummy_storage, NULL);
            }
            expect(c, ')');
            has_type = 1; continue;
        }

        /* Base types */
        if (t == TOK_VOID) {
            bt = VT_VOID; cmp_next(c); has_type = 1; continue;
        }
        if (t == TOK_CHAR) {
            bt = VT_BYTE; cmp_next(c); has_type = 1; continue;
        }
        if (t == TOK_SHORT) {
            is_short = 1; cmp_next(c); has_type = 1; continue;
        }
        if (t == TOK_INT) {
            if (bt == -1) bt = VT_INT;
            cmp_next(c); has_type = 1; continue;
        }
        if (t == TOK_LONG) {
            if (is_long) is_long_long = 1;
            else is_long = 1;
            cmp_next(c); has_type = 1; continue;
        }
        if (t == TOK_SIGNED) {
            is_signed = 1; cmp_next(c); has_type = 1; continue;
        }
        if (t == TOK_UNSIGNED) {
            is_signed = 0; cmp_next(c); has_type = 1; continue;
        }
        if (t == TOK_FLOAT) {
            bt = VT_FLOAT; cmp_next(c); has_type = 1; continue;
        }
        if (t == TOK_DOUBLE) {
            if (is_long) bt = VT_LDOUBLE;
            else bt = VT_DOUBLE;
            cmp_next(c); has_type = 1; continue;
        }
        if (t == TOK__BOOL) {
            bt = VT_BOOL; cmp_next(c); has_type = 1; continue;
        }
        if (t == TOK__COMPLEX || t == TOK___COMPLEX) {
            is_complex = 1; cmp_next(c); has_type = 1; continue;
        }

        /* struct/union/enum */
        if (t == TOK_STRUCT) {
            cmp_next(c);
            TypeDef *def = parse_struct_union(c, 0);
            bt = VT_STRUCT;
            type->ref = def;
            has_type = 1; continue;
        }
        if (t == TOK_UNION) {
            cmp_next(c);
            TypeDef *def = parse_struct_union(c, 1);
            bt = VT_STRUCT;
            type->ref = def;
            has_type = 1; continue;
        }
        if (t == TOK_ENUM) {
            cmp_next(c);
            TypeDef *def = parse_enum(c);
            bt = VT_ENUM;
            type->ref = def;
            has_type = 1; continue;
        }

        /* typeof */
        if (t == TOK_TYPEOF || t == TOK___TYPEOF__ || t == TOK___TYPEOF) {
            cmp_next(c);
            expect(c, '(');
            if (is_type_specifier(c)) {
                parse_type_spec(c, type, NULL, NULL);
            } else {
                Val v;
                expr(c, &v);
                *type = v.type;
            }
            expect(c, ')');
            has_type = 1;
            return 1;
        }

        /* Typedef name */
        if (t == TOK_IDENT) {
            struct TypedefEntry *td = find_typedef(c, c->tok_str);
            if (td) {
                *type = td->type;
                cmp_next(c);
                has_type = 1;
                /* Continue to pick up qualifiers */
                /* But don't pick up another base type */
                flags |= type->t & (VT_CONSTANT|VT_VOLATILE);
                type->t &= ~(VT_CONSTANT|VT_VOLATILE);
                /* Don't repeat this identifier */
                /* Apply additional qualifiers */
                for (;;) {
                    int t2 = c->tok;
                    if (t2 == TOK_CONST || t2 == TOK___CONST || t2 == TOK___CONST__) {
                        flags |= VT_CONSTANT; cmp_next(c);
                    } else if (t2 == TOK_VOLATILE || t2 == TOK___VOLATILE || t2 == TOK___VOLATILE__) {
                        flags |= VT_VOLATILE; cmp_next(c);
                    } else if (t2 == TOK_RESTRICT) {
                        cmp_next(c);
                    } else if (t2 == TOK___ATTRIBUTE__ || t2 == TOK___ATTRIBUTE) {
                        parse_attributes(c, &packed, align_attr, NULL, NULL);
                    } else break;
                }
                type->t |= flags;
                return 1;
            }
        }

        break; /* No more type tokens */
    }

    if (!has_type) return 0;

    /* Combine type */
    if (bt == -1) {
        if (is_long_long) bt = VT_LLONG;
        else if (is_long) bt = VT_LONG;
        else if (is_short) bt = VT_SHORT;
        else bt = VT_INT;
    } else if (is_long && bt == VT_DOUBLE) {
        bt = VT_LDOUBLE;
    } else if (is_long_long && bt == VT_INT) {
        bt = VT_LLONG;
    } else if (is_long && bt == VT_INT) {
        bt = VT_LONG;
    } else if (is_short && bt == VT_INT) {
        bt = VT_SHORT;
    }

    type->t = bt;
    if (is_signed == 0) type->t |= VT_UNSIGNED;
    if (c->s->char_is_unsigned && bt == VT_BYTE && is_signed == -1) type->t |= VT_UNSIGNED;
    type->t |= flags;

    return 1;
}

/* Parse abstract or named declarator */
static void parse_declarator(Compiler *c, CType *base_type, char *name_out, int name_size, CType *full_type) {
    *full_type = *base_type;
    if (name_out && name_size > 0) name_out[0] = 0;

    /* Pointer declarators */
    while (c->tok == '*') {
        cmp_next(c);
        /* Skip qualifiers */
        while (c->tok == TOK_CONST || c->tok == TOK___CONST || c->tok == TOK___CONST__ ||
               c->tok == TOK_VOLATILE || c->tok == TOK___VOLATILE || c->tok == TOK___VOLATILE__ ||
               c->tok == TOK_RESTRICT) {
            cmp_next(c);
        }
        /* Create pointer type */
        TypeDef *def = calloc(1, sizeof(TypeDef));
        def->kind = TK_ARRAY; /* reuse for pointer */
        def->element_type = *full_type;
        CType ptr_type;
        ptr_type.t = VT_PTR;
        ptr_type.ref = def;
        *full_type = ptr_type;
    }

    /* Optional name or grouped declarator */
    if (c->tok == '(') {
        /* Could be function prototype or grouped declarator */
        /* Peek: if next is type specifier, it's a function
         * Otherwise it's a grouped declarator */
        cmp_next(c); /* skip ( */
        if (c->tok == ')' || is_type_specifier(c) || c->tok == TOK_DOTS) {
            /* This is actually a function - put back and handle below */
            /* Actually we need to re-handle... */
            /* For simplicity, treat as function parameters */
            c->pos -= 1; /* Back up */
            /* ... actually this gets complex. For now, just handle the simple cases */
            c->tok = '('; /* Simulate being back at ( */
        } else {
            /* Grouped declarator: (name) */
            parse_declarator(c, base_type, name_out, name_size, full_type);
            expect(c, ')');
        }
    } else if (c->tok == TOK_IDENT && name_out) {
        strncpy(name_out, c->tok_str, name_size-1);
        name_out[name_size-1] = 0;
        cmp_next(c);
    }

    /* Array and function suffixes */
    for (;;) {
        if (c->tok == '[') {
            cmp_next(c);
            int nb_elts = -1;
            if (c->tok != ']') {
                /* Constant expression for array size */
                if (c->tok == TOK_PPNUM && !c->tok_is_float) {
                    nb_elts = (int)c->tok_ival;
                    cmp_next(c);
                } else {
                    /* VLA - just skip for now */
                    Val dummy;
                    expr(c, &dummy);
                    nb_elts = -2; /* VLA */
                }
            }
            expect(c, ']');

            TypeDef *def = calloc(1, sizeof(TypeDef));
            def->kind = TK_ARRAY;
            def->element_type = *full_type;
            def->nb_elts = nb_elts;
            CType arr_type;
            arr_type.t = VT_PTR | VT_ARRAY;
            arr_type.ref = def;
            *full_type = arr_type;
        } else if (c->tok == '(') {
            /* Function parameters */
            cmp_next(c);

            TypeDef *def = calloc(1, sizeof(TypeDef));
            def->kind = TK_FUNC;
            def->ret_type = *full_type;
            def->params = NULL;
            def->variadic = 0;
            def->calling_conv = FUNC_CDECL;

            Symbol **last = &def->params;

            while (c->tok != ')' && c->tok != TOK_EOF) {
                if (c->tok == TOK_DOTS) {
                    def->variadic = 1;
                    cmp_next(c);
                    break;
                }

                CType pbase;
                int pstorage = 0, palign = 0;
                if (!parse_type_spec(c, &pbase, &pstorage, &palign)) {
                    /* Just void */
                    if (c->tok == ')') break;
                    cmp_next(c);
                    continue;
                }

                /* Check for (void) */
                if ((pbase.t & VT_BTYPE) == VT_VOID && c->tok == ')') break;

                CType ptype;
                char pname[256] = "";
                parse_declarator(c, &pbase, pname, sizeof(pname), &ptype);

                /* Convert array to pointer for parameters */
                if ((ptype.t & VT_BTYPE) == VT_PTR && (ptype.t & VT_ARRAY)) {
                    ptype.t &= ~VT_ARRAY;
                }

                Symbol *param = calloc(1, sizeof(Symbol));
                param->name = *pname ? tcc_strdup(pname) : NULL;
                param->type = ptype;
                *last = param;
                last = &param->next;

                if (c->tok == ',') cmp_next(c);
                else break;
            }
            expect(c, ')');

            /* Parse attributes */
            parse_attributes(c, NULL, NULL, NULL, NULL);

            CType func_type;
            func_type.t = VT_FUNC;
            func_type.ref = def;
            *full_type = func_type;
        } else {
            break;
        }
    }
}

