/* ============================================================
 * CODE GENERATION HELPERS
 * Low-level code emission for the compiler
 * ============================================================ */

/* Allocate a local variable on the stack */
static int alloc_local(Compiler *c, int size, int align) {
    /* Round up size to alignment */
    size = (size + align-1) & ~(align-1);
    c->local_off -= size;
    /* Align the offset */
    c->local_off = -((-c->local_off + align-1) & ~(align-1));
    if (-c->local_off > c->max_local_size) c->max_local_size = -c->local_off;
    return c->local_off;
}

/* Emit code to load an integer register value */
/* reg: TREG_RAX, TREG_RCX, TREG_RDX, TREG_RSI, TREG_RDI, TREG_R8, TREG_R9 */
static void load_val_to_reg(Compiler *c, Val *v, int reg) {
    int btype = v->type.t & VT_BTYPE;
    int is_ptr = (btype == VT_PTR);
    int is_64 = (btype == VT_LLONG || btype == VT_LONG || btype == VT_PTR || is_ptr);
    int is_32 = !is_64;

    switch (v->cat) {
    case V_CONST_INT: {
        /* Load immediate to reg */
        CodeGen *cg = c->cg;
        if (reg == TREG_RAX) {
            emit1(cg, 0xb8 | (reg & 7)); /* MOV eax, imm32 */
            emit4(cg, (uint32_t)v->ival);
        } else if (reg < 8) {
            emit1(cg, 0xb8 | reg);
            emit4(cg, (uint32_t)v->ival);
        } else {
            emit2(cg, rex_byte(0,0,0,1), 0xb8 | (reg & 7));
            emit4(cg, (uint32_t)v->ival);
        }
        break;
    }
    case V_LOCAL: {
        CodeGen *cg = c->cg;
        int off = v->local_off;
        if (is_64 || is_ptr) {
            emit_mov_r64_rbp_off(cg, reg, off);
        } else if (btype == VT_BYTE) {
            /* MOVSX byte */
            if (reg < 8) {
                emit2(cg, 0x0f, 0xbe);
                if (off >= -128 && off <= 127) {
                    emit2(cg, modrm(1, reg, 5), (uint8_t)(int8_t)off);
                } else {
                    emit2(cg, modrm(2, reg, 5), 0);
                    emit4(cg, off);
                }
            }
        } else if (btype == VT_SHORT) {
            /* MOVSX short */
            emit2(cg, 0x0f, 0xbf);
            if (off >= -128 && off <= 127) {
                emit2(cg, modrm(1, reg, 5), (uint8_t)(int8_t)off);
            } else {
                emit2(cg, modrm(2, reg, 5), 0);
                emit4(cg, off);
            }
        } else {
            emit_mov_r32_rbp_off(cg, reg, off);
        }
        break;
    }
    case V_GLOBAL: {
        /* Load global variable */
        CodeGen *cg = c->cg;
        /* For global pointers, load the address */
        /* For global integers, load the value */
        if (is_64 || is_ptr) {
            emit_mov_r64_riprel(cg, reg, v->sym_idx);
        } else {
            /* Load as 32-bit via RIP-relative */
            if (reg >= 8) emit1(cg, rex_byte(0, 1, 0, 0));
            emit1(cg, 0x8b);
            emit1(cg, modrm(0, reg & 7, 5));
            int pos = cg_cur(cg);
            emit4(cg, 0);
            cu_add_rela(&c->rela_text, NULL, c->cu->text, pos, v->sym_idx, R_X86_64_PC32, -4);
        }
        break;
    }
    case V_REG_INT:
        if (v->reg != reg) {
            CodeGen *cg = c->cg;
            if (is_64) emit_mov_r64_r64(cg, reg, v->reg);
            else emit_mov_r32_r32(cg, reg, v->reg);
        }
        break;
    default:
        /* Other cases */
        break;
    }
    v->cat = V_REG_INT;
    v->reg = reg;
}

/* Store a value to a local variable */
static void store_to_local(Compiler *c, Val *v, int off, CType *type) {
    CodeGen *cg = c->cg;
    int btype = type->t & VT_BTYPE;
    int is_64 = (btype == VT_LLONG || btype == VT_LONG || btype == VT_PTR);

    if (v->cat == V_CONST_INT) {
        /* Store immediate */
        if (is_64) {
