            load_val_to_reg(c, v, TREG_RAX);
            emit_mov_rbp_off_r64(cg, off, TREG_RAX);
        } else {
            emit1(cg, 0xc7);
            if (off >= -128 && off <= 127) {
                emit2(cg, modrm(1, 0, 5), (uint8_t)(int8_t)off);
            } else {
                emit2(cg, modrm(2, 0, 5), 0);
                emit4(cg, (uint32_t)off);
            }
            emit4(cg, (uint32_t)v->ival);
        }
    } else if (v->cat == V_REG_INT) {
        if (is_64) {
            emit_mov_rbp_off_r64(cg, off, v->reg);
        } else if (btype == VT_BYTE) {
            /* Store byte */
            int reg = v->reg;
            if (reg >= 8) emit1(cg, rex_byte(0, 1, 0, 0));
            emit1(cg, 0x88);
            if (off >= -128 && off <= 127) {
                emit2(cg, modrm(1, reg & 7, 5), (uint8_t)(int8_t)off);
            } else {
                emit2(cg, modrm(2, reg & 7, 5), 0);
                emit4(cg, (uint32_t)off);
            }
        } else if (btype == VT_SHORT) {
            /* Store short: 66 89 /r */
            emit1(cg, 0x66);
            emit1(cg, 0x89);
            if (off >= -128 && off <= 127) {
                emit2(cg, modrm(1, v->reg & 7, 5), (uint8_t)(int8_t)off);
            } else {
                emit2(cg, modrm(2, v->reg & 7, 5), 0);
                emit4(cg, (uint32_t)off);
            }
        } else {
            emit_mov_rbp_off_r32(cg, off, v->reg);
        }
    } else {
        load_val_to_reg(c, v, TREG_RAX);
        store_to_local(c, v, off, type);
    }
