/* Store a value to global symbol */
static void store_to_global(Compiler *c, Val *v, int sym_idx, CType *type) {
    CodeGen *cg = c->cg;
    load_val_to_reg(c, v, TREG_RAX);
    emit_mov_riprel_r32(cg, sym_idx, TREG_RAX);
}

/* Load address of local variable */
static void load_local_addr(Compiler *c, int off, int reg) {
    CodeGen *cg = c->cg;
    /* LEA reg, [rbp+off] */
    if (reg >= 8) {
        emit1(cg, rex_byte(1, 1, 0, 0));
        emit1(cg, 0x8d);
        if (off >= -128 && off <= 127) {
            emit2(cg, modrm(1, reg & 7, 5), (uint8_t)(int8_t)off);
        } else {
            emit2(cg, modrm(2, reg & 7, 5), 0);
            emit4(cg, (uint32_t)off);
        }
    } else {
        emit1(cg, rex_byte(1, 0, 0, 0));
        emit1(cg, 0x8d);
        if (off >= -128 && off <= 127) {
            emit2(cg, modrm(1, reg, 5), (uint8_t)(int8_t)off);
        } else {
            emit2(cg, modrm(2, reg, 5), 0);
            emit4(cg, (uint32_t)off);
        }
    }
}

/* Dereference pointer in register, load value to rax */
static void deref_ptr_to_rax(Compiler *c, int ptr_reg, CType *elem_type) {
    CodeGen *cg = c->cg;
    int btype = elem_type->t & VT_BTYPE;
    int is_64 = (btype == VT_LLONG || btype == VT_LONG || btype == VT_PTR);

    if (ptr_reg != TREG_RAX) {
        emit_mov_r64_r64(cg, TREG_RAX, ptr_reg);
        ptr_reg = TREG_RAX;
    }

    if (is_64) {
        /* MOV rax, [rax] */
        emit2(cg, rex_byte(1, 0, 0, 0), 0x8b);
        emit1(cg, modrm(0, 0, 0));
    } else if (btype == VT_BYTE) {
        /* MOVSX al, [rax] */
        if (elem_type->t & VT_UNSIGNED) {
            /* MOVZX eax, byte [rax] */
            emit3(cg, 0x0f, 0xb6, modrm(0, 0, 0));
        } else {
            emit3(cg, 0x0f, 0xbe, modrm(0, 0, 0));
        }
    } else if (btype == VT_SHORT) {
        if (elem_type->t & VT_UNSIGNED) {
            emit3(cg, 0x0f, 0xb7, modrm(0, 0, 0));
        } else {
            emit3(cg, 0x0f, 0xbf, modrm(0, 0, 0));
        }
    } else {
        /* MOV eax, [rax] */
        emit2(cg, 0x8b, modrm(0, 0, 0));
    }
}

/* Store rax to address in rcx */
static void store_rax_to_rcx(Compiler *c, CType *type) {
    CodeGen *cg = c->cg;
    int btype = type->t & VT_BTYPE;
    int is_64 = (btype == VT_LLONG || btype == VT_LONG || btype == VT_PTR);

    if (is_64) {
        emit2(cg, rex_byte(1, 0, 0, 0), 0x89);
        emit1(cg, modrm(0, 0, 1)); /* MOV [rcx], rax */
    } else if (btype == VT_BYTE) {
        emit2(cg, 0x88, modrm(0, 0, 1)); /* MOV [rcx], al */
    } else if (btype == VT_SHORT) {
        emit3(cg, 0x66, 0x89, modrm(0, 0, 1));
    } else {
        emit2(cg, 0x89, modrm(0, 0, 1)); /* MOV [rcx], eax */
    }
}

/* ============================================================
 * FLOAT CODE GENERATION
 * ============================================================ */

/* XMM register operations */
/* Store XMM0 to local [rbp+off] */
static void store_xmm0_to_local(Compiler *c, int off, int is_double) {
    CodeGen *cg = c->cg;
    /* MOVQ/MOVD xmm0, [rbp+off] */
    if (is_double) {
        /* 66 0f d6 45 off (MOVQ [rbp+off], xmm0) */
        emit3(cg, 0x66, 0x0f, 0xd6);
    } else {
        /* 66 0f 7e 45 off (MOVD [rbp+off], xmm0) -> actually this goes wrong way */
        /* We want to store xmm0 to memory: F3 0F 11 45 off (MOVSS) */
        emit3(cg, 0xf3, 0x0f, 0x11);
    }
    if (off >= -128 && off <= 127) {
        emit2(cg, modrm(1, 0, 5), (uint8_t)(int8_t)off);
    } else {
        emit2(cg, modrm(2, 0, 5), 0);
        emit4(cg, (uint32_t)off);
    }
}

/* Load XMM0 from local [rbp+off] */
static void load_xmm0_from_local(Compiler *c, int off, int is_double) {
    CodeGen *cg = c->cg;
    if (is_double) {
        /* F3 0F 7E 45 off */
        emit3(cg, 0xf3, 0x0f, 0x7e);
    } else {
        /* 66 0F 6E 45 off (MOVD xmm0, m32) */
        emit3(cg, 0x66, 0x0f, 0x6e);
    }
    if (off >= -128 && off <= 127) {
        emit2(cg, modrm(1, 0, 5), (uint8_t)(int8_t)off);
    } else {
        emit2(cg, modrm(2, 0, 5), 0);
        emit4(cg, (uint32_t)off);
    }
}

/* Add float constant to .data.ro and return its offset */
static int add_float_const_f32(Compiler *c, float fv) {
    int off = section_align_to(c->cu->data_ro, 4);
    section_append(c->cu->data_ro, &fv, sizeof(float));
    return off;
}

static int add_float_const_f64(Compiler *c, double dv) {
    int off = section_align_to(c->cu->data_ro, 8);
    section_append(c->cu->data_ro, &dv, sizeof(double));
    return off;
}

/* Add string to .data.ro */
static int add_string_literal(Compiler *c, const char *str, int len) {
    int off = c->cu->data_ro->data_offset;
    section_append(c->cu->data_ro, str, len);
    section_put1(c->cu->data_ro, 0); /* null terminator */
    return off;
}

