    } else if (btype == VT_BYTE) {
        emit2(cg, 0x88, modrm(0, 0, 1)); /* MOV [rcx], al */
    } else if (btype == VT_SHORT) {
        emit3(cg, 0x66, 0x89, modrm(0, 0, 1));
    } else {
        emit2(cg, 0x89, modrm(0, 0, 1)); /* MOV [rcx], eax */
    }
}

/* ============================================================
 * FLOAT CODE GENERATION
 * ============================================================ */

/* XMM register operations */
/* Store XMM0 to local [rbp+off] */
static void store_xmm0_to_local(Compiler *c, int off, int is_double) {
    CodeGen *cg = c->cg;
    /* MOVQ/MOVD xmm0, [rbp+off] */
    if (is_double) {
        /* 66 0f d6 45 off (MOVQ [rbp+off], xmm0) */
        emit3(cg, 0x66, 0x0f, 0xd6);
    } else {
        /* 66 0f 7e 45 off (MOVD [rbp+off], xmm0) -> actually this goes wrong way */
        /* We want to store xmm0 to memory: F3 0F 11 45 off (MOVSS) */
        emit3(cg, 0xf3, 0x0f, 0x11);
    }
    if (off >= -128 && off <= 127) {
        emit2(cg, modrm(1, 0, 5), (uint8_t)(int8_t)off);
    } else {
        emit2(cg, modrm(2, 0, 5), 0);
        emit4(cg, (uint32_t)off);
    }
}

/* Load XMM0 from local [rbp+off] */
static void load_xmm0_from_local(Compiler *c, int off, int is_double) {
    CodeGen *cg = c->cg;
    if (is_double) {
        /* F3 0F 7E 45 off */
        emit3(cg, 0xf3, 0x0f, 0x7e);
    } else {
        /* 66 0F 6E 45 off (MOVD xmm0, m32) */
        emit3(cg, 0x66, 0x0f, 0x6e);
    }
    if (off >= -128 && off <= 127) {
        emit2(cg, modrm(1, 0, 5), (uint8_t)(int8_t)off);
    } else {
        emit2(cg, modrm(2, 0, 5), 0);
        emit4(cg, (uint32_t)off);
    }
}

/* Add float constant to .data.ro and return its offset */
static int add_float_const_f32(Compiler *c, float fv) {
    int off = section_align_to(c->cu->data_ro, 4);
    section_append(c->cu->data_ro, &fv, sizeof(float));
    return off;
}

static int add_float_const_f64(Compiler *c, double dv) {
    int off = section_align_to(c->cu->data_ro, 8);
    section_append(c->cu->data_ro, &dv, sizeof(double));
    return off;
}

/* Add string to .data.ro */
static int add_string_literal(Compiler *c, const char *str, int len) {
    int off = c->cu->data_ro->data_offset;
    section_append(c->cu->data_ro, str, len);
    section_put1(c->cu->data_ro, 0); /* null terminator */
    return off;
}

