/* ============================================================
 * EXPRESSION PARSER
 * Recursive descent expression parser with direct code gen
 * ============================================================ */

/* The expression evaluator works on a Val structure.
 * The Val represents the "current value" being computed.
 * After evaluation:
 * - Simple constants: cat=V_CONST_INT, ival=value
 * - Local variables: cat=V_LOCAL, local_off=offset
 * - Global variables: cat=V_GLOBAL, sym_idx=elf_sym
 * - Register values: cat=V_REG_INT, reg=register
 * - Float values: different handling
 */

/* Primary expressions */
static void primary_expr(Compiler *c, Val *v) {
    memset(v, 0, sizeof(Val));
    v->type.t = VT_INT;

    switch (c->tok) {
    case TOK_PPNUM:
        if (c->tok_is_float) {
            v->cat = V_CONST_FLT;
            v->dval = c->tok_dval;
            if (c->tok_float_type == 1) {
                v->type.t = VT_FLOAT;
            } else if (c->tok_float_type == 3) {
                v->type.t = VT_LDOUBLE;
            } else {
                v->type.t = VT_DOUBLE;
            }
        } else {
            v->cat = V_CONST_INT;
            v->ival = c->tok_ival;
            if (c->tok_is_longlong) {
                v->type.t = c->tok_is_unsigned ? (VT_LLONG|VT_UNSIGNED) : VT_LLONG;
            } else if (c->tok_is_long) {
                v->type.t = c->tok_is_unsigned ? (VT_LONG|VT_UNSIGNED) : VT_LONG;
            } else if (c->tok_is_unsigned) {
                v->type.t = VT_INT|VT_UNSIGNED;
            } else {
                v->type.t = VT_INT;
            }
        }
        cmp_next(c);
        return;

    case TOK_CCHAR:
    case TOK_LCHAR:
        v->cat = V_CONST_INT;
        v->ival = c->tok_ival;
        v->type.t = VT_INT;
        cmp_next(c);
        return;

    case TOK_STR: {
        /* String literal: put in .data.ro, create pointer */
        int off = add_string_literal(c, c->tok_str, c->tok_str_len);
        cmp_next(c);

        /* Create a local symbol for the string */
        char sym_name[64];
        snprintf(sym_name, sizeof(sym_name), "L.%d", c->str_count++);

        /* Add symbol to ELF symtab */
        int sym_idx = cu_add_elf_sym(c->cu, sym_name, 3 /* .data.ro section */,
                                       off, c->tok_str_len+1,
                                       STT_OBJECT, STB_LOCAL, STV_DEFAULT);

        v->cat = V_GLOBAL;
        v->sym_idx = sym_idx;
        v->type.t = VT_PTR;
        TypeDef *def = calloc(1, sizeof(TypeDef));
        def->element_type.t = VT_BYTE; /* char */
        def->kind = TK_ARRAY;
        v->type.ref = def;
        return;
    }

    case TOK_IDENT: {
        /* Look up variable or function */
        char name[256];
        strncpy(name, c->tok_str, sizeof(name)-1);
        cmp_next(c);

        struct VarEntry *e = find_var(c, name);
        if (!e) {
            /* Check if it's a typedef used as a value (enum constant etc) */
            struct TypedefEntry *td = find_typedef(c, name);
            if (td) {
                /* This shouldn't happen in expression context normally */
                cmp_error(c, "'%s' undeclared", name);
                v->cat = V_CONST_INT;
                return;
            }

            /* Undeclared - may be a function, warn */
            if (c->s->warn_implicit_function_declaration) {
                cmp_warning(c, "implicit declaration of function '%s'", name);
            }

            /* Create an implicit function declaration */
            CType ft;
            ft.t = VT_FUNC;
            ft.ref = calloc(1, sizeof(TypeDef));
            ft.ref->kind = TK_FUNC;
            ft.ref->ret_type.t = VT_INT;
            ft.ref->variadic = 1;

            /* Add to undefined symbols */
            /* Look up in ELF symtab */
            /* Add as undefined external */
            int sym_idx = cu_add_elf_sym(c->cu, name, SHN_UNDEF, 0, 0,
                                          STT_FUNC, STB_GLOBAL, STV_DEFAULT);

            e = add_var(c, name, &ft, 0);
            e->sym_idx = sym_idx;
        }

        if (e->is_typedef) {
            cmp_error(c, "'%s' is a type, not a value", name);
            v->cat = V_CONST_INT;
            return;
        }

        /* Handle enum constants */
        /* (stored as V_CONST_INT with special sym_idx = -1) */

        v->type = e->type;
        if (e->is_local) {
            v->cat = V_LOCAL;
            v->local_off = e->local_off;
            v->is_lvalue = 1;
        } else {
            v->cat = V_GLOBAL;
            v->sym_idx = e->sym_idx;
            v->is_lvalue = (e->type.t & VT_BTYPE) != VT_FUNC;
        }
        return;
    }

    case TOK_SIZEOF: {
        cmp_next(c);
        int size;
        if (c->tok == '(') {
            cmp_next(c);
            if (is_type_specifier(c)) {
                CType t;
                int st = 0;
                parse_type_spec(c, &t, &st, NULL);
                CType full;
                parse_declarator(c, &t, NULL, 0, &full);
                int align;
                size = type_size(&full, &align);
            } else {
                Val inner;
                expr(c, &inner);
                int align;
                size = type_size(&inner.type, &align);
            }
            expect(c, ')');
        } else {
            Val inner;
            unary_expr(c, &inner);
            int align;
            size = type_size(&inner.type, &align);
        }
        v->cat = V_CONST_INT;
        v->ival = size;
        v->type.t = VT_LONG | VT_UNSIGNED; /* size_t */
        return;
    }

    case TOK__ALIGNOF:
    case TOK___ALIGNOF: {
        cmp_next(c);
        int align = 1;
        if (c->tok == '(') {
            cmp_next(c);
            if (is_type_specifier(c)) {
                CType t;
                int st = 0;
                parse_type_spec(c, &t, &st, NULL);
                CType full;
                parse_declarator(c, &t, NULL, 0, &full);
                type_size(&full, &align);
            } else {
                Val inner;
                expr(c, &inner);
                type_size(&inner.type, &align);
            }
            expect(c, ')');
        }
        v->cat = V_CONST_INT;
        v->ival = align;
        v->type.t = VT_INT;
        return;
    }

    case TOK___FUNC__:
    case TOK___FUNCTION__:
    case TOK___PRETTY_FUNCTION__: {
        /* Return the function name as a string */
        const char *fname = ""; /* TODO: track current function name */
        int off = add_string_literal(c, fname, strlen(fname));
        char sym_name[64];
        snprintf(sym_name, sizeof(sym_name), "L.%d", c->str_count++);
        int sym_idx = cu_add_elf_sym(c->cu, sym_name, 3, off, strlen(fname)+1,
                                      STT_OBJECT, STB_LOCAL, STV_DEFAULT);
        v->cat = V_GLOBAL;
        v->sym_idx = sym_idx;
        v->type.t = VT_PTR;
        v->type.ref = calloc(1, sizeof(TypeDef));
        v->type.ref->element_type.t = VT_BYTE | VT_CONSTANT;
        v->type.ref->kind = TK_ARRAY;
        cmp_next(c);
        return;
    }

    case '(': {
        cmp_next(c);
        /* Check for compound literal: (type){...} */
        if (is_type_specifier(c)) {
            CType cast_type;
            int st = 0;
            parse_type_spec(c, &cast_type, &st, NULL);
            CType full_type;
            parse_declarator(c, &cast_type, NULL, 0, &full_type);
            expect(c, ')');

            if (c->tok == '{') {
                /* Compound literal */
                /* Allocate on stack */
                int size, align;
                size = type_size(&full_type, &align);
                if (size < 0) size = 0;
                int off = alloc_local(c, size, align);

                /* Zero-initialize */
                load_local_addr(c, off, TREG_RDI);
                emit_mov_r64_r64(c->cg, TREG_RSI, TREG_RDI); /* Nop - RDI already set */

                /* Parse initializer */
                cmp_next(c); /* skip { */
                /* TODO: full initializer support */
                while (c->tok != '}' && c->tok != TOK_EOF) {
                    Val init_v;
                    assign_expr(c, &init_v);
                    if (c->tok == ',') cmp_next(c);
                }
                expect(c, '}');

                v->cat = V_LOCAL;
                v->local_off = off;
                v->type = full_type;
                v->is_lvalue = 1;
                return;
            } else {
                /* Cast expression */
                unary_expr(c, v);
                /* Cast to full_type */
                v->type = full_type;
                return;
            }
        }
        expr(c, v);
        expect(c, ')');
        return;
    }

    case TOK___BUILTIN_VA_ARG: {
        /* __builtin_va_arg(ap, type) */
        cmp_next(c);
        expect(c, '(');
        Val ap_val;
        assign_expr(c, &ap_val);
        expect(c, ',');
        CType va_type;
        int st = 0;
        parse_type_spec(c, &va_type, &st, NULL);
        CType full_va;
        parse_declarator(c, &va_type, NULL, 0, &full_va);
        expect(c, ')');

        /* Simple implementation: read from stack */
        /* Load ap into rax, dereference */
        load_val_to_reg(c, &ap_val, TREG_RAX);
        /* Load value at [rax] */
        deref_ptr_to_rax(c, TREG_RAX, &full_va);

        v->cat = V_REG_INT;
        v->reg = TREG_RAX;
        v->type = full_va;
        return;
    }

    case TOK___BUILTIN_CONSTANT_P: {
        cmp_next(c);
        expect(c, '(');
        Val inner;
        expr(c, &inner);
        expect(c, ')');
        v->cat = V_CONST_INT;
        v->ival = (inner.cat == V_CONST_INT || inner.cat == V_CONST_FLT) ? 1 : 0;
        v->type.t = VT_INT;
        return;
    }

    case TOK___BUILTIN_EXPECT: {
        cmp_next(c);
        expect(c, '(');
        expr(c, v);
        expect(c, ',');
        Val dummy;
        expr(c, &dummy);
        expect(c, ')');
        return;
    }

    case TOK___BUILTIN_OFFSETOF: {
        cmp_next(c);
        expect(c, '(');
        CType base;
        int st = 0;
        parse_type_spec(c, &base, &st, NULL);
        expect(c, ',');
        /* Field name */
        char fname[256] = "";
        if (c->tok == TOK_IDENT) {
            strncpy(fname, c->tok_str, sizeof(fname)-1);
            cmp_next(c);
        }
        expect(c, ')');

        /* Find field offset */
        int offset = 0;
        if ((base.t & VT_BTYPE) == VT_STRUCT && base.ref) {
            for (Symbol *f = base.ref->fields; f; f = f->next) {
                if (f->name && !strcmp(f->name, fname)) {
                    offset = (int)f->addr;
                    break;
                }
            }
        }
        v->cat = V_CONST_INT;
        v->ival = offset;
        v->type.t = VT_LONG | VT_UNSIGNED;
        return;
    }

    case TOK___BUILTIN_TYPES_COMPATIBLE_P: {
        cmp_next(c);
        expect(c, '(');
        CType t1, t2;
        int st1 = 0, st2 = 0;
        parse_type_spec(c, &t1, &st1, NULL);
        expect(c, ',');
        parse_type_spec(c, &t2, &st2, NULL);
        expect(c, ')');
        /* Simple: compare base types */
        int compat = ((t1.t & VT_BTYPE) == (t2.t & VT_BTYPE));
        v->cat = V_CONST_INT;
        v->ival = compat;
        v->type.t = VT_INT;
        return;
    }

    case TOK___BUILTIN_RETURN_ADDRESS:
    case TOK___BUILTIN_FRAME_ADDRESS: {
        cmp_next(c);
        expect(c, '(');
        Val dummy;
        expr(c, &dummy);
        expect(c, ')');
        /* Return NULL for now */
        v->cat = V_CONST_INT;
        v->ival = 0;
        v->type.t = VT_PTR;
        return;
    }

    case TOK___BUILTIN_CLZ:
    case TOK___BUILTIN_CTZ:
    case TOK___BUILTIN_POPCOUNT: {
        int blt = c->tok;
        cmp_next(c);
        expect(c, '(');
        expr(c, v);
        expect(c, ')');
        load_val_to_reg(c, v, TREG_RAX);
        CodeGen *cg = c->cg;
        if (blt == TOK___BUILTIN_CLZ) {
            /* BSR eax, eax; xor eax, 31 */
            emit3(cg, 0x0f, 0xbd, modrm(3, 0, 0));
            emit3(cg, 0x83, 0xf0, 0x1f); /* xor eax, 31 */
        } else if (blt == TOK___BUILTIN_CTZ) {
            /* BSF eax, eax */
            emit3(cg, 0x0f, 0xbc, modrm(3, 0, 0));
        } else {
            /* POPCNT eax, eax */
            emit4(cg, 0xb8400f00 | 0); /* placeholder */
        }
        v->cat = V_REG_INT;
        v->reg = TREG_RAX;
        v->type.t = VT_INT;
        return;
    }

    default:
        cmp_error(c, "unexpected token in expression: '%c' (%d)", 
                  c->tok >= 32 && c->tok < 128 ? c->tok : '?', c->tok);
        v->cat = V_CONST_INT;
        v->ival = 0;
        /* Try to recover */
        cmp_next(c);
        return;
    }
}

