/* ============================================================
 * POSTFIX EXPRESSIONS
 * () [] -> . ++ --
 * ============================================================ */

static void postfix_expr(Compiler *c, Val *v) {
    primary_expr(c, v);

    for (;;) {
        switch (c->tok) {
        case '(': {
            /* Function call */
            cmp_next(c);

            /* Get function type */
            CType func_type = v->type;
            TypeDef *fdef = NULL;
            if ((func_type.t & VT_BTYPE) == VT_FUNC) {
                fdef = func_type.ref;
            } else if ((func_type.t & VT_BTYPE) == VT_PTR && func_type.ref) {
                /* Pointer to function */
                func_type = func_type.ref->element_type;
                if ((func_type.t & VT_BTYPE) == VT_FUNC) fdef = func_type.ref;
            }

            /* Determine return type */
            CType ret_type;
            ret_type.t = VT_INT;
            ret_type.ref = NULL;
            if (fdef) ret_type = fdef->ret_type;

            /* Parse arguments */
            #define MAX_CALL_ARGS 16
            Val args[MAX_CALL_ARGS];
            int nb_args = 0;

            while (c->tok != ')' && c->tok != TOK_EOF) {
                if (nb_args < MAX_CALL_ARGS) {
                    assign_expr(c, &args[nb_args]);
                    nb_args++;
                } else {
                    Val dummy;
                    assign_expr(c, &dummy);
                }
                if (c->tok == ',') cmp_next(c);
                else break;
            }
            expect(c, ')');

            /* SysV AMD64 ABI:
             * Integer args: RDI, RSI, RDX, RCX, R8, R9
             * Float args: XMM0-XMM7
             */
            static const int int_arg_regs[] = { TREG_RDI, TREG_RSI, TREG_RDX, TREG_RCX, TREG_R8, TREG_R9 };
            int int_arg = 0, flt_arg = 0;

            /* Push arguments in reverse order for stack args */
            /* For now, just handle register args */
            CodeGen *cg = c->cg;

            for (int i = 0; i < nb_args; i++) {
                int btype = args[i].type.t & VT_BTYPE;
                if (btype == VT_FLOAT || btype == VT_DOUBLE || btype == VT_LDOUBLE) {
                    /* Float argument in XMM register */
                    if (flt_arg < 8) {
                        /* Load to XMMn */
                        if (args[i].cat == V_CONST_FLT) {
                            /* Load float constant via .data.ro */
                            int data_off;
                            if (btype == VT_FLOAT) {
                                float fv = (float)args[i].dval;
                                data_off = add_float_const_f32(c, fv);
                            } else {
                                data_off = add_float_const_f64(c, args[i].dval);
                            }
                            /* Get symbol for .data.ro section */
                            /* Load from RIP+rel */
                            /* For float: MOVD xmmN, [rip+rel] */
                            /* For double: MOVQ xmmN, [rip+rel] */
                            int xmm = flt_arg;
                            /* Find or create .data.ro symbol */
                            /* We need a relocation to data_ro+data_off */
                            /* Hmm, this requires more work... */
                            /* For now, just push 0 */
                            if (btype == VT_FLOAT) {
                                emit4(cg, 0x6e0f66); /* MOVD xmm0, [RIP+rel] - but need proper encoding */
                            }
                        } else if (args[i].cat == V_LOCAL) {
                            /* Load from local - MOVQ/MOVD xmmN, [rbp+off] */
                            load_xmm0_from_local(c, args[i].local_off, btype == VT_DOUBLE || btype == VT_LDOUBLE);
                        }
                        flt_arg++;
                    }
                } else {
                    /* Integer/pointer argument */
                    if (int_arg < 6) {
                        int reg = int_arg_regs[int_arg];
                        load_val_to_reg(c, &args[i], reg);
                        int_arg++;
                    } else {
                        /* Push to stack */
                        load_val_to_reg(c, &args[i], TREG_RAX);
                        emit_push_r64(cg, TREG_RAX);
                    }
                }
            }

            /* For variadic functions, must set AL = number of float args */
            int is_variadic = fdef ? fdef->variadic : 1;
            if (is_variadic) {
                emit1(cg, 0xb0); /* MOV al, imm8 */
                emit1(cg, (uint8_t)flt_arg); /* number of float args */
            }

            /* Emit call */
            if (v->cat == V_GLOBAL) {
                emit1(cg, 0xe8); /* CALL rel32 */
                int pos = cg_cur(cg);
                emit4(cg, 0);
                cu_add_rela(&c->rela_text, NULL, c->cu->text,
                            pos, v->sym_idx, R_X86_64_PLT32, -4);
            } else {
                /* Call through register */
                load_val_to_reg(c, v, TREG_RAX);
                /* CALL rax: FF D0 */
                emit2(cg, 0xff, 0xd0);
            }

            /* Clean up stack args if any were pushed */
            int stack_args = nb_args - MIN2(int_arg, 6) - MIN2(flt_arg, 8);
            if (stack_args > 0) {
                emit_add_r32_imm8(cg, TREG_RSP, stack_args * 8);
            }

            /* Result is in RAX (integer) or XMM0 (float) */
            v->type = ret_type;
            int rbtype = ret_type.t & VT_BTYPE;
            if (rbtype == VT_FLOAT || rbtype == VT_DOUBLE) {
                v->cat = V_REG_FLT;
                v->reg = TREG_XMM0;
            } else {
                v->cat = V_REG_INT;
                v->reg = TREG_RAX;
            }
            break;
        }

        case '[': {
            /* Array subscript */
            cmp_next(c);
            Val idx;
            expr(c, &idx);
            expect(c, ']');

            /* Compute element type */
            CType elem_type;
            elem_type.t = VT_INT;
            elem_type.ref = NULL;
            if ((v->type.t & VT_BTYPE) == VT_PTR && v->type.ref) {
                if (v->type.t & VT_ARRAY) {
                    elem_type = v->type.ref->element_type;
                } else {
                    elem_type = v->type.ref->element_type;
                }
            }

            int elem_size, elem_align;
            elem_size = type_size(&elem_type, &elem_align);
            if (elem_size <= 0) elem_size = 1;

            /* Compute address: base + idx * elem_size */
            load_val_to_reg(c, v, TREG_RAX);
            load_val_to_reg(c, &idx, TREG_RCX);

            CodeGen *cg = c->cg;
            if (elem_size == 1) {
                emit2(cg, rex_byte(1,0,0,0), 0x01); /* ADD rax, rcx */
                emit1(cg, modrm(3, 1, 0));
            } else {
                /* IMUL rcx, elem_size */
                if (elem_size <= 127) {
                    emit3(cg, rex_byte(1,0,0,0), 0x6b, modrm(3, 1, 1));
                    emit1(cg, (uint8_t)elem_size);
                } else {
                    emit2(cg, rex_byte(1,0,0,0), 0x69);
                    emit1(cg, modrm(3, 1, 1));
                    emit4(cg, (uint32_t)elem_size);
                }
                emit2(cg, rex_byte(1,0,0,0), 0x01);
                emit1(cg, modrm(3, 1, 0)); /* ADD rax, rcx */
            }

            /* Now RAX has the address, dereference it */
            deref_ptr_to_rax(c, TREG_RAX, &elem_type);

            v->type = elem_type;
            v->cat = V_REG_INT;
            v->reg = TREG_RAX;
            v->is_lvalue = 1;
            break;
        }

        case '.': {
            /* Struct field access */
            cmp_next(c);
            char fname[256] = "";
            if (c->tok == TOK_IDENT) {
                strncpy(fname, c->tok_str, sizeof(fname)-1);
                cmp_next(c);
            } else {
                cmp_error(c, "field name expected");
            }

            /* Find field in struct */
            if ((v->type.t & VT_BTYPE) != VT_STRUCT || !v->type.ref) {
                cmp_error(c, "not a struct/union");
                break;
            }

            Symbol *field = NULL;
            for (Symbol *f = v->type.ref->fields; f; f = f->next) {
                if (f->name && !strcmp(f->name, fname)) { field = f; break; }
            }

            if (!field) {
                cmp_error(c, "field '%s' not found", fname);
                break;
            }

            /* Adjust offset */
            if (v->cat == V_LOCAL) {
                v->local_off += (int)field->addr;
                v->type = field->type;
            } else {
                /* Load address */
                if (v->cat == V_CONST_INT || v->cat == V_GLOBAL) {
                    load_val_to_reg(c, v, TREG_RAX);
                }
                if (v->cat == V_REG_INT) {
                    /* Add field offset */
                    if (field->addr != 0) {
                        CodeGen *cg = c->cg;
                        if (field->addr <= 127) {
                            emit3(cg, rex_byte(1,0,0,0), 0x83, modrm(3, 0, v->reg & 7));
                            emit1(cg, (uint8_t)field->addr);
                        } else {
                            emit2(cg, rex_byte(1,0,0,0), 0x81);
                            emit1(cg, modrm(3, 0, v->reg & 7));
                            emit4(cg, (uint32_t)field->addr);
                        }
                    }
                    /* Dereference to get value */
                    deref_ptr_to_rax(c, v->reg, &field->type);
                    v->cat = V_REG_INT;
                    v->reg = TREG_RAX;
                }
                v->type = field->type;
            }
            v->is_lvalue = 1;
            break;
        }

        case TOK_ARROW: {
            /* Pointer-to-struct field access */
            cmp_next(c);
            char fname[256] = "";
            if (c->tok == TOK_IDENT) {
                strncpy(fname, c->tok_str, sizeof(fname)-1);
                cmp_next(c);
            } else {
                cmp_error(c, "field name expected after ->");
            }

            /* Dereference pointer */
            CType ptr_type = v->type;
            CType struct_type;
            if ((ptr_type.t & VT_BTYPE) == VT_PTR && ptr_type.ref) {
                struct_type = ptr_type.ref->element_type;
            } else {
                cmp_error(c, "not a pointer to struct");
                break;
            }

            /* Find field */
            if ((struct_type.t & VT_BTYPE) != VT_STRUCT || !struct_type.ref) {
                cmp_error(c, "not a struct pointer");
                break;
            }

            Symbol *field = NULL;
            for (Symbol *f = struct_type.ref->fields; f; f = f->next) {
                if (f->name && !strcmp(f->name, fname)) { field = f; break; }
            }

            if (!field) {
                cmp_error(c, "field '%s' not found", fname);
                break;
            }

            /* Load pointer to RAX */
            load_val_to_reg(c, v, TREG_RAX);

            CodeGen *cg = c->cg;
            if (field->addr != 0) {
                /* Add offset to pointer */
                if ((int)field->addr <= 127) {
                    emit2(cg, rex_byte(1,0,0,0), 0x83);
                    emit2(cg, modrm(3, 0, 0), (uint8_t)field->addr);
                } else {
                    emit2(cg, rex_byte(1,0,0,0), 0x81);
                    emit1(cg, modrm(3, 0, 0));
                    emit4(cg, (uint32_t)field->addr);
                }
            }

            /* Load from [rax+offset] - we already computed the address */
            deref_ptr_to_rax(c, TREG_RAX, &field->type);

            v->type = field->type;
            v->cat = V_REG_INT;
            v->reg = TREG_RAX;
            v->is_lvalue = 1;
            break;
        }

        case TOK_INC:
        case TOK_DEC: {
            /* Post-increment/decrement */
            int is_inc = (c->tok == TOK_INC);
            cmp_next(c);

            /* Load current value to RAX */
            load_val_to_reg(c, v, TREG_RAX);

            /* Save original value to RCX */
            CodeGen *cg = c->cg;
            emit_mov_r64_r64(cg, TREG_RCX, TREG_RAX);

            /* Increment/decrement RAX */
            if (is_inc) {
                emit3(cg, 0x83, modrm(3, 0, TREG_RAX), 0x01); /* add eax, 1 */
            } else {
                emit3(cg, 0x83, modrm(3, 5, TREG_RAX), 0x01); /* sub eax, 1 */
            }

            /* Store back */
            if (v->cat == V_LOCAL) {
                emit_mov_rbp_off_r32(cg, v->local_off, TREG_RAX);
            } else if (v->cat == V_GLOBAL) {
                emit_mov_riprel_r32(cg, v->sym_idx, TREG_RAX);
            }

            /* Result is original value (in RCX) */
            emit_mov_r32_r32(cg, TREG_RAX, TREG_RCX);

            v->cat = V_REG_INT;
            v->reg = TREG_RAX;
            break;
        }

        default:
            return;
        }
    }
}

/* ============================================================
 * UNARY EXPRESSIONS
 * ============================================================ */

static void unary_expr(Compiler *c, Val *v) {
    int tok = c->tok;

    switch (tok) {
    case '!': {
        cmp_next(c);
        unary_expr(c, v);
        load_val_to_reg(c, v, TREG_RAX);
        CodeGen *cg = c->cg;
        /* TEST eax, eax */
        emit2(cg, 0x85, modrm(3, 0, 0));
        /* SETE al */
        emit3(cg, 0x0f, 0x94, modrm(3, 0, 0));
        /* MOVZX eax, al */
        emit3(cg, 0x0f, 0xb6, modrm(3, 0, 0));
        v->cat = V_REG_INT;
        v->reg = TREG_RAX;
        v->type.t = VT_INT;
        return;
    }
    case '-': {
        cmp_next(c);
        unary_expr(c, v);
        if (v->cat == V_CONST_INT) {
            v->ival = -v->ival;
            return;
        }
        int btype = v->type.t & VT_BTYPE;
        if (btype == VT_FLOAT || btype == VT_DOUBLE) {
            /* Float negate: XOR with sign bit */
            /* For simplicity, store to local, negate, reload */
            int sz = type_size(&v->type, NULL);
            int off = alloc_local(c, sz, sz);
            /* TODO: proper float negation */
        } else {
            load_val_to_reg(c, v, TREG_RAX);
            CodeGen *cg = c->cg;
            emit2(cg, 0xf7, modrm(3, 3, TREG_RAX)); /* NEG eax */
            v->cat = V_REG_INT;
            v->reg = TREG_RAX;
        }
        return;
    }
    case '~': {
        cmp_next(c);
        unary_expr(c, v);
        if (v->cat == V_CONST_INT) {
            v->ival = ~v->ival;
            return;
        }
        load_val_to_reg(c, v, TREG_RAX);
        CodeGen *cg = c->cg;
        emit2(cg, 0xf7, modrm(3, 2, TREG_RAX)); /* NOT eax */
        v->cat = V_REG_INT;
        v->reg = TREG_RAX;
        return;
    }
    case '+': {
        cmp_next(c);
        unary_expr(c, v);
        return;
    }
    case '*': {
        /* Dereference */
        cmp_next(c);
        unary_expr(c, v);

        CType ptr_type = v->type;
        CType elem_type;
        elem_type.t = VT_INT;
        if ((ptr_type.t & VT_BTYPE) == VT_PTR && ptr_type.ref) {
            elem_type = ptr_type.ref->element_type;
        }

        load_val_to_reg(c, v, TREG_RAX);
        deref_ptr_to_rax(c, TREG_RAX, &elem_type);
        v->type = elem_type;
        v->cat = V_REG_INT;
        v->reg = TREG_RAX;
        v->is_lvalue = 1;
        return;
    }
    case '&': {
        /* Address-of */
        cmp_next(c);
        unary_expr(c, v);

        CType elem_type = v->type;

        if (v->cat == V_LOCAL) {
            load_local_addr(c, v->local_off, TREG_RAX);
            v->cat = V_REG_INT;
            v->reg = TREG_RAX;
        } else if (v->cat == V_GLOBAL) {
            /* LEA rax, [rip+sym] */
            CodeGen *cg = c->cg;
            emit2(cg, rex_byte(1, 0, 0, 0), 0x8d);
            emit1(cg, modrm(0, 0, 5));
            int pos = cg_cur(cg);
            emit4(cg, 0);
            cu_add_rela(&c->rela_text, NULL, c->cu->text, pos, v->sym_idx, R_X86_64_PC32, -4);
            v->cat = V_REG_INT;
            v->reg = TREG_RAX;
        }

        /* Type is pointer to elem_type */
        TypeDef *def = calloc(1, sizeof(TypeDef));
        def->element_type = elem_type;
        def->kind = TK_ARRAY;
        v->type.t = VT_PTR;
        v->type.ref = def;
        return;
    }
    case TOK_INC:
    case TOK_DEC: {
        /* Pre-increment/decrement */
        int is_inc = (tok == TOK_INC);
        cmp_next(c);
        unary_expr(c, v);

        load_val_to_reg(c, v, TREG_RAX);
        CodeGen *cg = c->cg;

        if (is_inc) {
            emit3(cg, 0x83, modrm(3, 0, TREG_RAX), 0x01); /* add eax, 1 */
        } else {
            emit3(cg, 0x83, modrm(3, 5, TREG_RAX), 0x01); /* sub eax, 1 */
        }

        /* Store back */
        if (v->cat == V_LOCAL || v->cat == V_REG_INT) {
            if (v->cat == V_LOCAL) {
                emit_mov_rbp_off_r32(cg, v->local_off, TREG_RAX);
            }
        }

        v->cat = V_REG_INT;
        v->reg = TREG_RAX;
        return;
    }
    case TOK_SIZEOF: {
        /* sizeof without parens - goes to unary */
        /* But we handle this in primary_expr too... Let's handle here */
        /* Actually TOK_SIZEOF should go to primary_expr always */
        postfix_expr(c, v);
        return;
    }
    case '(': {
        /* Could be cast or grouped expression */
        /* Peek to see if it's a type */
        int saved_pos = c->pos;
        int saved_tok = c->tok;
        long long saved_ival = c->tok_ival;
        cmp_next(c);

        if (is_type_specifier(c)) {
            /* Cast expression */
            CType cast_type;
            int st = 0;
            parse_type_spec(c, &cast_type, &st, NULL);
            CType full_type;
            parse_declarator(c, &cast_type, NULL, 0, &full_type);
            expect(c, ')');

            unary_expr(c, v);

            /* Apply cast */
            int from_bt = v->type.t & VT_BTYPE;
            int to_bt = full_type.t & VT_BTYPE;

            if (from_bt != to_bt) {
                /* Need to convert */
                if (to_bt == VT_VOID) {
                    /* Cast to void - discard */
                } else if ((to_bt == VT_FLOAT || to_bt == VT_DOUBLE) &&
                           (from_bt == VT_INT || from_bt == VT_LONG || from_bt == VT_LLONG)) {
                    /* Int to float */
                    load_val_to_reg(c, v, TREG_RAX);
                    CodeGen *cg = c->cg;
                    /* CVTSI2SS xmm0, eax */
                    if (to_bt == VT_FLOAT) {
                        emit4(cg, 0xc02a0f2a); /* cvtsi2ss xmm0, eax */
                    } else {
                        emit4(cg, 0xc02a0ff2); /* cvtsi2sd xmm0, eax */
                    }
                    v->cat = V_REG_FLT;
                    v->reg = TREG_XMM0;
                } else if ((from_bt == VT_FLOAT || from_bt == VT_DOUBLE) &&
                           (to_bt == VT_INT || to_bt == VT_LONG)) {
                    /* Float to int */
                    /* TODO: proper conversion */
                    CodeGen *cg = c->cg;
                    emit4(cg, 0xc02c0ff2); /* CVTTSD2SI eax, xmm0 */
                    v->cat = V_REG_INT;
                    v->reg = TREG_RAX;
                } else {
                    /* Integer cast */
                    if (v->cat == V_CONST_INT) {
                        /* Truncate/extend constant */
                        switch (to_bt) {
                        case VT_BYTE:
                            if (full_type.t & VT_UNSIGNED) v->ival = (uint8_t)v->ival;
                            else v->ival = (int8_t)v->ival;
                            break;
                        case VT_SHORT:
                            if (full_type.t & VT_UNSIGNED) v->ival = (uint16_t)v->ival;
                            else v->ival = (int16_t)v->ival;
                            break;
                        case VT_INT:
                            v->ival = (int32_t)v->ival;
                            break;
                        }
                    }
                }
            }
            v->type = full_type;
            return;
        } else {
            /* Not a cast - reset and treat as grouped expression */
            c->pos = saved_pos;
            c->tok = saved_tok;
            c->tok_ival = saved_ival;
        }
        /* Fall through to postfix_expr */
        postfix_expr(c, v);
        return;
    }
    default:
        postfix_expr(c, v);
        return;
    }
}

