/* ============================================================
 * BINARY EXPRESSIONS
 * ============================================================ */

/* Binary operation helper */
static void bin_op(Compiler *c, Val *a, Val *b, int op) {
    int btype = a->type.t & VT_BTYPE;

    if (a->cat == V_CONST_INT && b->cat == V_CONST_INT) {
        /* Constant folding */
        long long av = a->ival, bv = b->ival;
        switch (op) {
        case '+': a->ival = av + bv; return;
        case '-': a->ival = av - bv; return;
        case '*': a->ival = av * bv; return;
        case '/': if (bv) a->ival = av / bv; return;
        case '%': if (bv) a->ival = av % bv; return;
        case '&': a->ival = av & bv; return;
        case '|': a->ival = av | bv; return;
        case '^': a->ival = av ^ bv; return;
        case TOK_SHL: a->ival = av << bv; return;
        case TOK_SAR: a->ival = av >> bv; return;
        }
    }

    /* Emit code */
    CodeGen *cg = c->cg;

    /* Load a to RAX, b to RCX */
    load_val_to_reg(c, a, TREG_RAX);
    load_val_to_reg(c, b, TREG_RCX);

    switch (op) {
    case '+':
        emit2(cg, 0x01, modrm(3, TREG_RCX, TREG_RAX)); /* ADD eax, ecx */
        break;
    case '-':
        emit2(cg, 0x29, modrm(3, TREG_RCX, TREG_RAX)); /* SUB eax, ecx */
        break;
    case '*':
        emit3(cg, 0x0f, 0xaf, modrm(3, TREG_RAX, TREG_RCX)); /* IMUL eax, ecx */
        break;
    case '/':
        /* CDQ + IDIV */
        emit1(cg, 0x99); /* CDQ (sign-extend eax to edx:eax) */
        emit2(cg, 0xf7, modrm(3, 7, TREG_RCX)); /* IDIV ecx */
        break;
    case '%':
        emit1(cg, 0x99); /* CDQ */
