/* Binary operation helper */
static void bin_op(Compiler *c, Val *a, Val *b, int op) {
    int btype = a->type.t & VT_BTYPE;

    if (a->cat == V_CONST_INT && b->cat == V_CONST_INT) {
        /* Constant folding */
        long long av = a->ival, bv = b->ival;
        switch (op) {
        case '+': a->ival = av + bv; return;
        case '-': a->ival = av - bv; return;
        case '*': a->ival = av * bv; return;
        case '/': if (bv) a->ival = av / bv; return;
        case '%': if (bv) a->ival = av % bv; return;
        case '&': a->ival = av & bv; return;
        case '|': a->ival = av | bv; return;
        case '^': a->ival = av ^ bv; return;
        case TOK_SHL: a->ival = av << bv; return;
        case TOK_SAR: a->ival = av >> bv; return;
        }
    }

    /* Emit code */
    CodeGen *cg = c->cg;

    /* Load a to RAX, b to RCX */
    load_val_to_reg(c, a, TREG_RAX);
    load_val_to_reg(c, b, TREG_RCX);

    switch (op) {
    case '+':
        emit2(cg, 0x01, modrm(3, TREG_RCX, TREG_RAX)); /* ADD eax, ecx */
        break;
    case '-':
        emit2(cg, 0x29, modrm(3, TREG_RCX, TREG_RAX)); /* SUB eax, ecx */
        break;
    case '*':
        emit3(cg, 0x0f, 0xaf, modrm(3, TREG_RAX, TREG_RCX)); /* IMUL eax, ecx */
        break;
    case '/':
        /* CDQ + IDIV */
        emit1(cg, 0x99); /* CDQ (sign-extend eax to edx:eax) */
        emit2(cg, 0xf7, modrm(3, 7, TREG_RCX)); /* IDIV ecx */
        break;
    case '%':
        emit1(cg, 0x99); /* CDQ */
        emit2(cg, 0xf7, modrm(3, 7, TREG_RCX)); /* IDIV ecx */
        emit_mov_r32_r32(cg, TREG_RAX, TREG_RDX); /* MOV eax, edx (remainder) */
        break;
    case '&':
        emit2(cg, 0x21, modrm(3, TREG_RCX, TREG_RAX)); /* AND eax, ecx */
        break;
    case '|':
        emit2(cg, 0x09, modrm(3, TREG_RCX, TREG_RAX)); /* OR eax, ecx */
        break;
    case '^':
        emit2(cg, 0x31, modrm(3, TREG_RCX, TREG_RAX)); /* XOR eax, ecx */
        break;
    case TOK_SHL:
        /* SHL eax, cl */
        emit2(cg, 0xd3, modrm(3, 4, TREG_RAX));
        break;
    case TOK_SAR:
        /* SAR eax, cl */
        emit2(cg, 0xd3, modrm(3, 7, TREG_RAX));
        break;
    }

    a->cat = V_REG_INT;
    a->reg = TREG_RAX;
}

/* Comparison operation - sets flags */
static void cmp_op(Compiler *c, Val *a, Val *b, int op) {
    load_val_to_reg(c, a, TREG_RAX);
    load_val_to_reg(c, b, TREG_RCX);

    CodeGen *cg = c->cg;
    /* CMP eax, ecx */
    emit2(cg, 0x39, modrm(3, TREG_RCX, TREG_RAX));

    /* SETcc al */
    uint8_t setcc;
    switch (op) {
    case TOK_EQ: setcc = 0x94; break; /* SETE */
    case TOK_NE: setcc = 0x95; break; /* SETNE */
    case '<':   setcc = (a->type.t & VT_UNSIGNED) ? 0x92 : 0x9c; break; /* SETB/SETL */
    case '>':   setcc = (a->type.t & VT_UNSIGNED) ? 0x97 : 0x9f; break; /* SETA/SETG */
    case TOK_LE: setcc = (a->type.t & VT_UNSIGNED) ? 0x96 : 0x9e; break; /* SETBE/SETLE */
    case TOK_GE: setcc = (a->type.t & VT_UNSIGNED) ? 0x93 : 0x9d; break; /* SETAE/SETGE */
    default: setcc = 0x94; break;
    }
    emit3(cg, 0x0f, setcc, modrm(3, 0, 0)); /* SETcc al */
    emit3(cg, 0x0f, 0xb6, modrm(3, 0, 0)); /* MOVZX eax, al */

    a->cat = V_REG_INT;
    a->reg = TREG_RAX;
    a->type.t = VT_INT;
}

static void mul_expr(Compiler *c, Val *v) {
    unary_expr(c, v);
    while (c->tok == '*' || c->tok == '/' || c->tok == '%') {
        int op = c->tok;
        cmp_next(c);
        Val v2;
        unary_expr(c, &v2);
        bin_op(c, v, &v2, op);
    }
}

static void add_expr(Compiler *c, Val *v) {
    mul_expr(c, v);
    while (c->tok == '+' || c->tok == '-') {
        int op = c->tok;
        cmp_next(c);
        Val v2;
        mul_expr(c, &v2);
        bin_op(c, v, &v2, op);
    }
}

