    while (c->tok == TOK_SHL || c->tok == TOK_SAR) {
        int op = c->tok;
        cmp_next(c);
        Val v2;
        add_expr(c, &v2);
        bin_op(c, v, &v2, op);
    }
}

static void rel_expr(Compiler *c, Val *v) {
    shift_expr(c, v);
    while (c->tok == '<' || c->tok == '>' || c->tok == TOK_LE || c->tok == TOK_GE) {
        int op = c->tok;
        cmp_next(c);
        Val v2;
        shift_expr(c, &v2);
        cmp_op(c, v, &v2, op);
    }
}

