}

static void band_expr(Compiler *c, Val *v) {
    eq_expr(c, v);
    while (c->tok == '&') {
        cmp_next(c);
        Val v2;
        eq_expr(c, &v2);
        bin_op(c, v, &v2, '&');
    }
}

static void bxor_expr(Compiler *c, Val *v) {
    band_expr(c, v);
    while (c->tok == '^') {
        cmp_next(c);
        Val v2;
        band_expr(c, &v2);
        bin_op(c, v, &v2, '^');
    }
}

static void bor_expr(Compiler *c, Val *v) {
    bxor_expr(c, v);
    while (c->tok == '|') {
        cmp_next(c);
        Val v2;
        bxor_expr(c, &v2);
        bin_op(c, v, &v2, '|');
    }
}

static void and_expr(Compiler *c, Val *v) {
    bor_expr(c, v);
    while (c->tok == TOK_LAND) {
        cmp_next(c);

        /* Short-circuit evaluation */
        /* If v == 0, skip to end */
        load_val_to_reg(c, v, TREG_RAX);
        CodeGen *cg = c->cg;
        emit2(cg, 0x85, modrm(3, 0, 0)); /* TEST eax, eax */

        int end_label = cg_new_label(c->cg);
        emit2(cg, 0x0f, 0x84); /* JE */
        cg_emit_ref(c->cg, end_label);

        Val v2;
        bor_expr(c, &v2);
        load_val_to_reg(c, &v2, TREG_RAX);

        /* Normalize to 0/1 */
        emit2(cg, 0x85, modrm(3, 0, 0));
        emit3(cg, 0x0f, 0x95, modrm(3, 0, 0)); /* SETNE al */
        emit3(cg, 0x0f, 0xb6, modrm(3, 0, 0)); /* MOVZX */

        cg_define_label(c->cg, end_label);

        v->cat = V_REG_INT;
        v->reg = TREG_RAX;
        v->type.t = VT_INT;
    }
}

static void or_expr(Compiler *c, Val *v) {
    and_expr(c, v);
    while (c->tok == TOK_LOR) {
        cmp_next(c);

        load_val_to_reg(c, v, TREG_RAX);
        CodeGen *cg = c->cg;
        emit2(cg, 0x85, modrm(3, 0, 0)); /* TEST eax, eax */

        int true_label = cg_new_label(c->cg);
        emit2(cg, 0x0f, 0x85); /* JNE */
        cg_emit_ref(c->cg, true_label);

        Val v2;
        and_expr(c, &v2);
        load_val_to_reg(c, &v2, TREG_RAX);

        cg_define_label(c->cg, true_label);

        /* Normalize to 0/1 */
        emit2(cg, 0x85, modrm(3, 0, 0));
        emit3(cg, 0x0f, 0x95, modrm(3, 0, 0)); /* SETNE al */
        emit3(cg, 0x0f, 0xb6, modrm(3, 0, 0)); /* MOVZX */

        v->cat = V_REG_INT;
        v->reg = TREG_RAX;
        v->type.t = VT_INT;
    }
}

static void cond_expr(Compiler *c, Val *v) {
    or_expr(c, v);
    if (c->tok == '?') {
        cmp_next(c);

        load_val_to_reg(c, v, TREG_RAX);
        CodeGen *cg = c->cg;
        emit2(cg, 0x85, modrm(3, 0, 0)); /* TEST eax, eax */

        int false_label = cg_new_label(cg);
        int end_label = cg_new_label(cg);

        emit2(cg, 0x0f, 0x84); /* JE false */
        cg_emit_ref(cg, false_label);

        /* True branch */
        Val true_v;
        if (c->tok == ':') {
            /* GNU extension: a ?: b means a if true, b if false */
            true_v = *v;
        } else {
            expr(c, &true_v);
        }
        load_val_to_reg(c, &true_v, TREG_RAX);

        emit1(cg, 0xe9); /* JMP end */
        cg_emit_ref(cg, end_label);

        cg_define_label(cg, false_label);

        expect(c, ':');
        Val false_v;
        cond_expr(c, &false_v);
        load_val_to_reg(c, &false_v, TREG_RAX);

        cg_define_label(cg, end_label);

        v->cat = V_REG_INT;
        v->reg = TREG_RAX;
    }
}

/* Assignment expression */
static void assign_expr(Compiler *c, Val *v) {
    cond_expr(c, v);

    int assign_op = 0;
    switch (c->tok) {
    case '=': assign_op = '='; break;
    case TOK_ADD_ASSIGN: assign_op = '+'; break;
    case TOK_SUB_ASSIGN: assign_op = '-'; break;
    case TOK_MUL_ASSIGN: assign_op = '*'; break;
    case TOK_DIV_ASSIGN: assign_op = '/'; break;
    case TOK_MOD_ASSIGN: assign_op = '%'; break;
    case TOK_AND_ASSIGN: assign_op = '&'; break;
    case TOK_OR_ASSIGN:  assign_op = '|'; break;
    case TOK_XOR_ASSIGN: assign_op = '^'; break;
    case TOK_SHL_ASSIGN: assign_op = TOK_SHL; break;
    case TOK_SAR_ASSIGN: assign_op = TOK_SAR; break;
    default: return;
    }
    cmp_next(c);

    Val rhs;
    assign_expr(c, &rhs);

    if (assign_op != '=') {
        /* compound assignment: lhs op= rhs */
        Val lhs_val = *v;
        bin_op(c, &lhs_val, &rhs, assign_op);
        rhs = lhs_val;
    }

    /* Store rhs to lhs */
    if (v->cat == V_LOCAL) {
        load_val_to_reg(c, &rhs, TREG_RAX);
        store_to_local(c, &rhs, v->local_off, &v->type);
    } else if (v->cat == V_GLOBAL) {
        load_val_to_reg(c, &rhs, TREG_RAX);
        emit_mov_riprel_r32(c->cg, v->sym_idx, TREG_RAX);
    } else if (v->cat == V_REG_INT && v->is_lvalue) {
        /* Store to address in register */
        int addr_reg = v->reg;
        load_val_to_reg(c, &rhs, TREG_RAX);
        /* MOV [addr_reg], rax */
        store_rax_to_rcx(c, &v->type); /* Hmm, this uses RCX */
    }

    *v = rhs;
    v->is_lvalue = 0;
}

static void expr(Compiler *c, Val *v) {
    assign_expr(c, v);
    while (c->tok == ',') {
        cmp_next(c);
        assign_expr(c, v);
    }
}

