    case TOK_OR_ASSIGN:  assign_op = '|'; break;
    case TOK_XOR_ASSIGN: assign_op = '^'; break;
    case TOK_SHL_ASSIGN: assign_op = TOK_SHL; break;
    case TOK_SAR_ASSIGN: assign_op = TOK_SAR; break;
    default: return;
    }
    cmp_next(c);

    Val rhs;
    assign_expr(c, &rhs);

    if (assign_op != '=') {
        /* compound assignment: lhs op= rhs */
        Val lhs_val = *v;
        bin_op(c, &lhs_val, &rhs, assign_op);
        rhs = lhs_val;
    }

    /* Store rhs to lhs */
    if (v->cat == V_LOCAL) {
        load_val_to_reg(c, &rhs, TREG_RAX);
        store_to_local(c, &rhs, v->local_off, &v->type);
    } else if (v->cat == V_GLOBAL) {
        load_val_to_reg(c, &rhs, TREG_RAX);
        emit_mov_riprel_r32(c->cg, v->sym_idx, TREG_RAX);
    } else if (v->cat == V_REG_INT && v->is_lvalue) {
        /* Store to address in register */
        int addr_reg = v->reg;
        load_val_to_reg(c, &rhs, TREG_RAX);
        /* MOV [addr_reg], rax */
        store_rax_to_rcx(c, &v->type); /* Hmm, this uses RCX */
    }

    *v = rhs;
    v->is_lvalue = 0;
}

static void expr(Compiler *c, Val *v) {
    assign_expr(c, v);
    while (c->tok == ',') {
        cmp_next(c);
        assign_expr(c, v);
    }
}

