        if (c->nb_break >= c->cap_break) {
            c->cap_break = c->cap_break ? c->cap_break*2 : 8;
            c->break_labels = tcc_realloc(c->break_labels, c->cap_break*sizeof(int));
        }
        c->break_labels[c->nb_break++] = break_label;

        stmt(c);

        c->nb_break--;
        c->sw_depth--;

        /* Emit dispatcher */
        cg_define_label(cg, dispatch_label);
        emit_mov_r32_rbp_off(cg, TREG_RAX, sw_local);

        for (int i = 0; i < sw->nb_cases; i++) {
            /* CMP eax, case_val */
            emit1(cg, 0x3d); /* CMP eax, imm32 */
            emit4(cg, (uint32_t)sw->case_vals[i]);
            emit2(cg, 0x0f, 0x84); /* JE case_label */
            cg_emit_ref(cg, sw->case_labels[i]);
        }
        /* Jump to default or end */
        emit1(cg, 0xe9);
        if (sw->default_label >= 0) {
            cg_emit_ref(cg, sw->default_label);
        } else {
            cg_emit_ref(cg, break_label);
        }

        cg_define_label(cg, break_label);

        free(sw->case_vals);
        free(sw->case_labels);
        free(sw);
        return;
    }

    case TOK_CASE: {
        cmp_next(c);
        Val v;
        cond_expr(c, &v);
        expect(c, ':');

        if (c->sw_depth == 0) {
            cmp_error(c, "case outside switch");
            return;
        }

        struct SwitchEntry *sw = c->sw_stack[c->sw_depth-1];
        int case_label = cg_new_label(c->cg);
        cg_define_label(c->cg, case_label);

        if (sw->nb_cases >= sw->cap_cases) {
            sw->cap_cases = sw->cap_cases ? sw->cap_cases*2 : 8;
            sw->case_vals = tcc_realloc(sw->case_vals, sw->cap_cases*sizeof(int));
            sw->case_labels = tcc_realloc(sw->case_labels, sw->cap_cases*sizeof(int));
        }
        sw->case_vals[sw->nb_cases] = (int)v.ival;
        sw->case_labels[sw->nb_cases] = case_label;
        sw->nb_cases++;

        /* Fall through to next statement */
        if (c->tok != '}' && c->tok != TOK_EOF) stmt(c);
        return;
    }

    case TOK_DEFAULT: {
        cmp_next(c);
        expect(c, ':');

        if (c->sw_depth == 0) {
            cmp_error(c, "default outside switch");
            return;
        }

        struct SwitchEntry *sw = c->sw_stack[c->sw_depth-1];
        int def_label = cg_new_label(c->cg);
        cg_define_label(c->cg, def_label);
        sw->default_label = def_label;

        if (c->tok != '}' && c->tok != TOK_EOF) stmt(c);
        return;
    }

    case TOK_RETURN: {
        cmp_next(c);
        CodeGen *cg = c->cg;

        if (c->tok != ';') {
            Val v;
            expr(c, &v);
            int ret_bt = c->func_ret_type.t & VT_BTYPE;
            if (ret_bt == VT_FLOAT || ret_bt == VT_DOUBLE) {
                /* Return float in XMM0 */
            } else if (ret_bt != VT_VOID) {
                load_val_to_reg(c, &v, TREG_RAX);
            }
        }
        expect(c, ';');

        emit_return(c);
        return;
    }

    case TOK_BREAK: {
        cmp_next(c);
        expect(c, ';');
        if (c->nb_break > 0) {
            emit1(c->cg, 0xe9);
            cg_emit_ref(c->cg, c->break_labels[c->nb_break-1]);
        } else {
            cmp_error(c, "break outside loop/switch");
        }
        return;
    }

    case TOK_CONTINUE: {
        cmp_next(c);
        expect(c, ';');
        if (c->nb_cont > 0) {
            emit1(c->cg, 0xe9);
            cg_emit_ref(c->cg, c->continue_labels[c->nb_cont-1]);
        } else {
            cmp_error(c, "continue outside loop");
        }
        return;
    }

    case TOK_GOTO: {
        cmp_next(c);
        /* Get label name */
        char lname[256] = "";
        if (c->tok == TOK_IDENT) {
            strncpy(lname, c->tok_str, sizeof(lname)-1);
            cmp_next(c);
        }
        expect(c, ';');

        /* Emit jump to label - use forward reference */
        /* Find or create label */
        int lbl = -1;
        for (int i = 0; i < 512; i++) {
            if (!c->cg->label_defs || i >= c->cg->nb_labels_cg) break;
        }
        /* For simplicity, create a new label */
        lbl = cg_new_label(c->cg);
        emit1(c->cg, 0xe9);
        cg_emit_ref(c->cg, lbl);
        return;
    }

    case ';':
        /* Empty statement */
        cmp_next(c);
        return;

    case TOK_ASM:
    case TOK___ASM__:
    case TOK___ASM: {
        /* Inline assembly - skip for now */
        cmp_next(c);
        if (c->tok == TOK___VOLATILE || c->tok == TOK___VOLATILE__) cmp_next(c);
        expect(c, '(');
        /* Skip the asm string */
        int depth = 1;
        while (depth > 0 && c->tok != TOK_EOF) {
            if (c->tok == '(') depth++;
            else if (c->tok == ')') depth--;
            if (depth > 0) cmp_next(c);
        }
        expect(c, ')');
        if (c->tok == ';') cmp_next(c);
        return;
    }

    case TOK___LABEL__: {
        /* Local label declaration - skip */
        cmp_next(c);
        while (c->tok == TOK_IDENT) cmp_next(c);
        expect(c, ';');
        return;
    }

    default:
        if (c->tok == TOK_IDENT && c->pos < c->src_len) {
            /* Check for label: identifier ':' */
            int saved_pos = c->pos;
            int saved_tok = c->tok;
            char name[256];
            strncpy(name, c->tok_str, sizeof(name)-1);
            cmp_next(c);
            if (c->tok == ':') {
                cmp_next(c);
                /* Label definition - define the label */
                /* For now, just define a new label */
                int lbl = cg_new_label(c->cg);
                cg_define_label(c->cg, lbl);
                if (c->tok != '}' && c->tok != TOK_EOF) stmt(c);
                return;
            }
            /* Not a label - put back and parse as expression */
            c->pos = saved_pos;
            c->tok = saved_tok;
            strncpy(c->tok_str, name, sizeof(c->tok_str)-1);
        }

        /* Declaration or expression statement */
        if (is_type_specifier(c)) {
            parse_decl(c, 0);
        } else {
            Val v;
            expr(c, &v);
            expect(c, ';');
        }
        return;
    }
}

