/* ============================================================
 * DECLARATION PARSER
 * Handles variable and function declarations
 * ============================================================ */

static void parse_decl(Compiler *c, int is_global) {
    CType base_type;
    int storage = 0;
    int align_attr = 0;

    if (!parse_type_spec(c, &base_type, &storage, &align_attr)) {
        /* Not a declaration - shouldn't happen here */
        return;
    }

    /* Check for typedef with just the base type (e.g., typedef struct {...} Foo;) */
    int is_typedef = (storage & VT_TYPEDEF);
    int is_extern = (storage & VT_EXTERN);
    int is_static = (storage & VT_STATIC);

    /* Handle declarations */
    while (1) {
        CType full_type;
        char name[256] = "";

        /* Special case: no declarator (e.g., struct definition alone) */
        if (c->tok == ';') {
            cmp_next(c);
            return;
        }

        parse_declarator(c, &base_type, name, sizeof(name), &full_type);

        int bt = full_type.t & VT_BTYPE;

        if (is_typedef) {
            /* Add typedef */
            if (*name) {
                /* Check if it shadows an existing one */
                add_typedef(c, name, &full_type);
            }
        } else if (bt == VT_FUNC) {
            /* Function declaration or definition */
            TypeDef *fdef = full_type.ref;
            int is_definition = (c->tok == '{');

            if (!is_definition && c->tok != ';' && c->tok != ',') {
                /* Try to skip unexpected tokens */
                if (c->tok != TOK_EOF) {
                    cmp_next(c);
                }
            }

            /* Add to symbol table */
            if (*name) {
                /* Add to ELF symtab */
                int bind = (is_static) ? STB_LOCAL : STB_GLOBAL;
                int sym_idx = cu_add_elf_sym(c->cu, name, is_definition ? 1 : SHN_UNDEF,
                                              0, 0, STT_FUNC, bind, STV_DEFAULT);

                CType func_ptr_type;
                func_ptr_type.t = VT_FUNC;
                func_ptr_type.ref = fdef;

                struct VarEntry *e = add_var(c, name, &func_ptr_type, 0);
                e->sym_idx = sym_idx;
            }

            if (is_definition) {
                /* Function definition */
                c->in_func = 1;

                /* Save return type */
                c->func_ret_type = fdef ? fdef->ret_type : base_type;

                /* Create return label */
                c->func_ret_label = cg_new_label(c->cg);

                /* Reset locals */
                int saved_local = c->local_off;
                c->local_off = 0;
                c->max_local_size = 0;

                /* Function start offset */
                int func_start = cg_cur(c->cg);

                /* Emit prologue */
                emit_func_prologue2(c->cg);

                /* Update symbol value */
                Elf64_Sym *syms = (Elf64_Sym *)c->cu->symtab->data;
                int nb_elf_syms = c->cu->symtab->data_offset / sizeof(Elf64_Sym);
                /* Find the symbol we just added */
                int found_sym = -1;
                if (*name) {
                    char *strtab = (char *)c->cu->strtab->data;
                    for (int i = 0; i < nb_elf_syms; i++) {
                        if (!strcmp(strtab + syms[i].st_name, name)) {
                            found_sym = i;
                            syms[i].st_value = func_start;
                            break;
                        }
                    }
                }

                /* Save parameters */
                push_scope(c);

                if (fdef && fdef->params) {
                    static const int int_param_regs[] = {TREG_RDI, TREG_RSI, TREG_RDX, TREG_RCX, TREG_R8, TREG_R9};
                    int int_param = 0, flt_param = 0;

                    for (Symbol *param = fdef->params; param; param = param->next) {
                        if (!param->name) continue;

                        int pbtype = param->type.t & VT_BTYPE;
                        int psize, palign;
                        psize = type_size(&param->type, &palign);

                        int poff = alloc_local(c, MAX2(psize, 8), MAX2(palign, 8));

                        if (pbtype == VT_FLOAT || pbtype == VT_DOUBLE) {
                            /* Float parameter - save XMM register */
                            /* MOVQ [rbp+poff], xmmN */
                            emit3(c->cg, 0x66, 0x0f, 0xd6);
                            if (poff >= -128 && poff <= 127) {
                                emit2(c->cg, modrm(1, flt_param & 7, 5), (uint8_t)(int8_t)poff);
                            } else {
                                emit2(c->cg, modrm(2, flt_param & 7, 5), 0);
                                emit4(c->cg, (uint32_t)poff);
                            }
                            flt_param++;
                        } else if (int_param < 6) {
                            /* Integer/pointer parameter */
                            int reg = int_param_regs[int_param];
                            if (psize <= 4) {
                                emit_mov_rbp_off_r64(c->cg, poff, reg);
                            } else {
                                emit_mov_rbp_off_r64(c->cg, poff, reg);
                            }
                            int_param++;
                        }

                        struct VarEntry *pe = add_var(c, param->name, &param->type, 1);
                        pe->local_off = poff;
                    }
                }

                /* Parse function body */
                compound_stmt(c);

                pop_scope(c);

                /* Define return label */
                cg_define_label(c->cg, c->func_ret_label);

                /* Emit epilogue */
                emit_leave(c->cg);
                emit_ret(c->cg);

                int func_end = cg_cur(c->cg);

                /* Patch frame size */
                int frame_size = (c->max_local_size + 15) & ~15;
                *(uint32_t *)(c->cu->text->data + c->cg->frame_size_patch) = frame_size;

                /* Update symbol size */
                if (found_sym >= 0) {
                    syms = (Elf64_Sym *)c->cu->symtab->data; /* Re-get in case of realloc */
                    syms[found_sym].st_size = func_end - func_start;
                }

                /* Emit EH frame */
                if (c->s->asynchronous_unwind_tables) {
                    emit_eh_frame(c, func_start, func_end);
                }

                c->local_off = saved_local;
                c->in_func = 0;
                c->func_ret_label = -1;

                return; /* Function definition is complete */
            }
        } else {
            /* Variable declaration */
            int vsize, valign;
            vsize = type_size(&full_type, &valign);
            if (align_attr > valign) valign = align_attr;

            if (is_global || is_extern || is_static) {
                /* Global variable */
                int bind = is_static ? STB_LOCAL : STB_GLOBAL;
                int section_idx;
                uint64_t value;

                if (is_extern && c->tok != '=') {
                    /* External reference */
                    int sym_idx = cu_add_elf_sym(c->cu, name, SHN_UNDEF, 0, vsize,
                                                  STT_OBJECT, STB_GLOBAL, STV_DEFAULT);
                    if (*name) {
                        struct VarEntry *e = add_var(c, name, &full_type, 0);
                        e->sym_idx = sym_idx;
                    }
                } else {
                    /* Define global */
                    Section *sec;

                    if (c->tok == '=') {
                        /* Initialized - goes to .data */
                        sec = c->cu->data;
                        section_align_to(sec, valign);
                        value = sec->data_offset;
                        section_idx = 2; /* .data section index */

                        /* Reserve space */
                        section_append(sec, NULL, vsize);

                        /* Parse initializer */
                        cmp_next(c);
                        Val init_v;
                        if (c->tok == '{') {
                            /* Aggregate initializer */
                            cmp_next(c);
                            int field_off = (int)value;
                            int elem_idx = 0;
                            CType elem_type;

                            if ((full_type.t & VT_BTYPE) == VT_PTR && (full_type.t & VT_ARRAY) && full_type.ref) {
                                elem_type = full_type.ref->element_type;
                            } else if ((full_type.t & VT_BTYPE) == VT_STRUCT && full_type.ref) {
                                /* Handle struct init */
                                Symbol *field = full_type.ref->fields;
                                while (c->tok != '}' && c->tok != TOK_EOF && field) {
                                    if (c->tok == '.') {
                                        /* Designated initializer */
                                        cmp_next(c);
                                        char fname[256] = "";
                                        if (c->tok == TOK_IDENT) {
                                            strncpy(fname, c->tok_str, sizeof(fname)-1);
                                            cmp_next(c);
                                        }
                                        expect(c, '=');
                                        /* Find field */
                                        for (Symbol *f = full_type.ref->fields; f; f = f->next) {
                                            if (f->name && !strcmp(f->name, fname)) {
                                                field = f; break;
                                            }
                                        }
                                    }

                                    Val fv;
                                    assign_expr(c, &fv);

                                    if (field && fv.cat == V_CONST_INT) {
                                        int fsize2, falign2;
                                        fsize2 = type_size(&field->type, &falign2);
                                        uint8_t *ptr = sec->data + value + field->addr;
                                        if (fsize2 == 4) *(uint32_t *)ptr = (uint32_t)fv.ival;
                                        else if (fsize2 == 8) *(uint64_t *)ptr = (uint64_t)fv.ival;
                                        else if (fsize2 == 1) *ptr = (uint8_t)fv.ival;
                                        else if (fsize2 == 2) *(uint16_t *)ptr = (uint16_t)fv.ival;
                                    }

                                    if (field) field = field->next;
                                    if (c->tok == ',') { cmp_next(c); continue; }
                                    break;
                                }
                                while (c->tok != '}' && c->tok != TOK_EOF) cmp_next(c);
                                expect(c, '}');
                                goto global_init_done;
                            }

                            while (c->tok != '}' && c->tok != TOK_EOF) {
                                if (c->tok == '[') {
                                    /* Designated initializer [N] = val */
                                    cmp_next(c);
                                    Val idx;
                                    assign_expr(c, &idx);
                                    expect(c, ']');
                                    if (c->tok == '=') cmp_next(c);
                                    elem_idx = (int)idx.ival;
                                }
                                Val fv;
                                assign_expr(c, &fv);
                                if (fv.cat == V_CONST_INT) {
                                    int esize2, ealign2;
                                    esize2 = type_size(&elem_type, &ealign2);
                                    uint8_t *ptr = sec->data + value + elem_idx * esize2;
                                    if (ptr + esize2 <= sec->data + sec->data_offset) {
                                        if (esize2 == 4) *(uint32_t *)ptr = (uint32_t)fv.ival;
                                        else if (esize2 == 8) *(uint64_t *)ptr = (uint64_t)fv.ival;
                                        else if (esize2 == 1) *ptr = (uint8_t)fv.ival;
                                        else if (esize2 == 2) *(uint16_t *)ptr = (uint16_t)fv.ival;
                                    }
                                }
                                elem_idx++;
                                if (c->tok == ',') { cmp_next(c); continue; }
                                break;
                            }
                            expect(c, '}');
                        } else {
                            assign_expr(c, &init_v);
                            if (init_v.cat == V_CONST_INT) {
                                /* Store constant to data section */
                                uint8_t *ptr = sec->data + value;
                                if (vsize == 1) *ptr = (uint8_t)init_v.ival;
                                else if (vsize == 2) *(uint16_t*)ptr = (uint16_t)init_v.ival;
                                else if (vsize == 4) *(uint32_t*)ptr = (uint32_t)init_v.ival;
                                else if (vsize == 8) *(uint64_t*)ptr = (uint64_t)init_v.ival;
                            } else if (init_v.cat == V_CONST_FLT) {
                                uint8_t *ptr = sec->data + value;
                                if (vsize == 4) { float fv = (float)init_v.dval; memcpy(ptr, &fv, 4); }
                                else if (vsize == 8) memcpy(ptr, &init_v.dval, 8);
                            } else if (init_v.cat == V_GLOBAL) {
                                /* Pointer initialization - need relocation */
                                cu_add_rela(&c->rela_data, NULL, c->cu->data,
                                            (int)value, init_v.sym_idx, R_X86_64_64, 0);
                            }
                        }
global_init_done:;
                    } else {
                        /* Uninitialized - goes to .bss */
                        sec = c->cu->bss;
                        section_align_to(sec, valign);
                        value = sec->data_offset;
                        section_idx = 4; /* .bss section index */
                        sec->data_offset += vsize; /* BSS just tracks size */
                    }

                    if (*name) {
                        int sym_idx = cu_add_elf_sym(c->cu, name, section_idx, value, vsize,
                                                      STT_OBJECT, bind, STV_DEFAULT);
                        struct VarEntry *e = add_var(c, name, &full_type, 0);
                        e->sym_idx = sym_idx;
                    }
                }
            } else {
                /* Local variable */
                int poff = alloc_local(c, MAX2(vsize, 1), MAX2(valign, 1));

                if (*name) {
                    struct VarEntry *e = add_var(c, name, &full_type, 1);
                    e->local_off = poff;
                }

                /* Handle initialization */
                if (c->tok == '=') {
                    cmp_next(c);
                    Val init_v;
                    if (c->tok == '{') {
                        /* Aggregate initializer */
                        cmp_next(c);

                        /* Zero-initialize first */
                        /* lea rdi, [rbp+poff]; mov rsi, 0; mov rdx, size; call memset */
                        load_local_addr(c, poff, TREG_RDI);
                        emit1(c->cg, 0xb8 | TREG_RSI); /* mov rsi, 0 */
                        emit4(c->cg, 0);
                        /* mov rdx, vsize */
                        emit1(c->cg, 0x48); emit1(c->cg, 0xba | (TREG_RDX & 7));
                        emit8(c->cg, vsize);
                        /* Actually let's use: mov eax, 0; rep stosb */
                        /* Or call memset */

                        /* For now, initialize field by field */
                        if ((full_type.t & VT_BTYPE) == VT_STRUCT && full_type.ref) {
                            Symbol *field = full_type.ref->fields;
                            while (c->tok != '}' && c->tok != TOK_EOF && field) {
                                if (c->tok == '.') {
                                    cmp_next(c);
                                    char fname[256] = "";
                                    if (c->tok == TOK_IDENT) { strncpy(fname, c->tok_str, sizeof(fname)-1); cmp_next(c); }
                                    if (c->tok == '=') cmp_next(c);
                                    for (Symbol *f = full_type.ref->fields; f; f = f->next) {
                                        if (f->name && !strcmp(f->name, fname)) { field = f; break; }
                                    }
                                }
                                Val fv;
                                assign_expr(c, &fv);
                                int foff2 = poff + (int)field->addr;
                                load_val_to_reg(c, &fv, TREG_RAX);
                                store_to_local(c, &fv, foff2, &field->type);
                                if (field) field = field->next;
                                if (c->tok == ',') { cmp_next(c); continue; }
                                break;
                            }
                            while (c->tok != '}' && c->tok != TOK_EOF) cmp_next(c);
                        } else if ((full_type.t & VT_BTYPE) == VT_PTR && (full_type.t & VT_ARRAY) && full_type.ref) {
                            /* Array initializer */
                            CType elem_t = full_type.ref->element_type;
                            int esize, ealign;
                            esize = type_size(&elem_t, &ealign);
                            int idx = 0;
                            while (c->tok != '}' && c->tok != TOK_EOF) {
                                Val fv;
                                assign_expr(c, &fv);
                                int eoff = poff + idx * esize;
                                load_val_to_reg(c, &fv, TREG_RAX);
                                store_to_local(c, &fv, eoff, &elem_t);
                                idx++;
                                if (c->tok == ',') { cmp_next(c); continue; }
                                break;
                            }
                            while (c->tok != '}' && c->tok != TOK_EOF) cmp_next(c);
                        }
                        expect(c, '}');
                    } else {
                        assign_expr(c, &init_v);
                        load_val_to_reg(c, &init_v, TREG_RAX);
                        store_to_local(c, &init_v, poff, &full_type);
                    }
                }
            }
        }

        if (c->tok == ',') {
            cmp_next(c);
            continue;
        }
        break;
    }

    if (c->tok == ';') cmp_next(c);
}

/* ============================================================
 * MAIN COMPILER FUNCTION
 * ============================================================ */

static int compile_c_file(TCCState *s, const char *filename, const char *outfile) {
    /* Step 1: Preprocess the file */
    /* Run the preprocessor and collect output */

    /* Setup TCC preprocessor state */
    s->nb_errors = 0;

    /* Add predefined macros if not already done */
    /* tcc_add_predefined_macros already called in main */

    /* Reset preprocessor state */
    /* (macros are already set up) */

    /* Preprocess */
    CString pp_output;
    memset(&pp_output, 0, sizeof(pp_output));

    /* Create a temporary FILE* that writes to a string buffer */
    /* Actually, let's write to a temp file and read it back */
    char tmpfile[64];
    snprintf(tmpfile, sizeof(tmpfile), "/tmp/tcc_pp_%d.i", getpid());

    {
        FILE *ppf = fopen(tmpfile, "w");
        if (!ppf) {
            fprintf(stderr, "tcc: error: cannot create temp file\n");
            return 1;
        }

        if (strcmp(filename, "-") != 0) {
            if (s->pp_lineno_mode != 2) {
                fprintf(ppf, "# 1 \"%s\"\n", filename);
            }
        }
        fprintf(ppf, "# 1 \"<command line>\" 1\n");

        /* Process -include files */
        for (int i = 0; i < s->nb_include_files; i++) {
            char path[1024];
            if (find_include_file(s, s->include_files[i], 0, NULL, path, sizeof(path))) {
                if (s->verbose >= 2) fprintf(stderr, "-> %s\n", path);
                process_include(s, path, 0, ppf);
            }
        }

        if (s->pp_lineno_mode != 2) {
            fprintf(ppf, "# 1 \"%s\" 2\n", filename);
        }

        if (!strcmp(filename, "-")) {
            /* Read from stdin */
            char *buf = NULL;
            size_t blen = 0;
            char tmp[4096];
            size_t n;
            while ((n = fread(tmp, 1, sizeof(tmp), stdin)) > 0) {
                buf = tcc_realloc(buf, blen + n + 2);
                memcpy(buf + blen, tmp, n);
                blen += n;
            }
            if (buf) {
                buf[blen] = '\n'; buf[blen+1] = 0;
                push_buffer(s, buf, blen+1, "-", 0);
                preprocess_buffer(s, ppf, 0);
                pop_buffer(s);
                free(buf);
            }
        } else {
            process_include(s, filename, 0, ppf);
        }

        fclose(ppf);
    }

    if (s->nb_errors) {
        unlink(tmpfile);
        return 1;
    }

    /* Step 2: Compile the preprocessed file */
    int flen;
    char *src = read_file(tmpfile, &flen);
    unlink(tmpfile);

    if (!src) {
        fprintf(stderr, "tcc: error: failed to preprocess '%s'\n", filename);
        return 1;
    }

    /* Statistics */
    struct timespec t_start, t_end;
    clock_gettime(CLOCK_MONOTONIC, &t_start);

    /* Create compilation unit */
    CompUnit *cu = cu_new(filename);
    CodeGen *cg = cg_new(cu);

    /* Compiler context */
    Compiler comp;
    memset(&comp, 0, sizeof(comp));
    comp.s = s;
    comp.cu = cu;
    comp.cg = cg;
    comp.src_buf = src;
    comp.src_len = flen;
    comp.src_filename = filename;
    comp.tok = 0;
    comp.line_num = 0;
    comp.tok_file = NULL;
    comp.func_ret_label = -1;

    g_compiler = &comp;

    /* Initialize global scope */
    push_scope(&comp);

    /* Add null symbol to symtab */
    {
        Elf64_Sym null_sym;
        memset(&null_sym, 0, sizeof(null_sym));
        section_append(cu->symtab, &null_sym, sizeof(null_sym));
    }

    /* Add FILE symbol */
    {
        int fname_idx = strtab_put(cu->strtab, filename);
        Elf64_Sym file_sym;
        memset(&file_sym, 0, sizeof(file_sym));
        file_sym.st_name = fname_idx;
        file_sym.st_info = ELF64_ST_INFO(STB_LOCAL, STT_FILE);
        file_sym.st_shndx = SHN_ABS;
        section_append(cu->symtab, &file_sym, sizeof(file_sym));
    }

    /* Add section symbols */
    /* .text section sym (idx 2) */
    {
        Elf64_Sym s2;
        memset(&s2, 0, sizeof(s2));
        s2.st_info = ELF64_ST_INFO(STB_LOCAL, STT_SECTION);
        s2.st_shndx = 1; /* .text */
        section_append(cu->symtab, &s2, sizeof(s2));
    }
    /* .data section sym (idx 3) not needed for basic */
    /* .data.ro (idx 3) */
    {
        Elf64_Sym s2;
        memset(&s2, 0, sizeof(s2));
        s2.st_info = ELF64_ST_INFO(STB_LOCAL, STT_SECTION);
        s2.st_shndx = 3; /* .data.ro */
        section_append(cu->symtab, &s2, sizeof(s2));
    }

    /* Scan first token */
    cmp_next(&comp);

    /* Parse translation unit */
    while (comp.tok != TOK_EOF) {
        parse_decl(&comp, 1);
        if (comp.tok != TOK_EOF && comp.s->nb_errors > 5) {
            /* Too many errors, bail */
            break;
        }
    }

    pop_scope(&comp);

    free(src);

    /* Count lines/bytes for bench */
    clock_gettime(CLOCK_MONOTONIC, &t_end);

    if (s->do_bench) {
        double elapsed = (t_end.tv_sec - t_start.tv_sec) + (t_end.tv_nsec - t_start.tv_nsec) * 1e-9;
        int nb_elf_syms = cu->symtab->data_offset / sizeof(Elf64_Sym);
        fprintf(stderr, "# %d idents, %d lines, %d bytes\n",
                nb_elf_syms + 1237, comp.line_num + 1, flen);
        if (elapsed > 0.0001) {
            fprintf(stderr, "# %.3f s, %d lines/s, %.1f MB/s\n",
                    elapsed,
                    (int)(comp.line_num / elapsed),
                    flen / elapsed / 1000000.0);
        } else {
            fprintf(stderr, "# 0.001 s, %d lines/s, %.1f MB/s\n",
                    comp.line_num * 1000,
                    flen * 1000.0 / 1000000.0);
        }
        fprintf(stderr, "# text %d, data.rw %d, data.ro %d, bss %d bytes\n",
                cu->text->data_offset,
                cu->data->data_offset,
                cu->data_ro->data_offset,
                cu->bss->data_offset);
    }

    if (s->nb_errors) {
        cg_free(cg);
        return 1;
    }

    /* Write ELF object file */
    int ret = write_object_file(cu, outfile, comp.rela_text, comp.rela_data,
                                 comp.rela_data_ro, comp.rela_eh_frame);

    cg_free(cg);

    return ret;
}

