/* ============================================================
 * DECLARATION PARSER
 * Handles variable and function declarations
 * ============================================================ */

static void parse_decl(Compiler *c, int is_global) {
    CType base_type;
    int storage = 0;
    int align_attr = 0;

    if (!parse_type_spec(c, &base_type, &storage, &align_attr)) {
        /* Not a declaration - shouldn't happen here */
        return;
    }

    /* Check for typedef with just the base type (e.g., typedef struct {...} Foo;) */
    int is_typedef = (storage & VT_TYPEDEF);
    int is_extern = (storage & VT_EXTERN);
    int is_static = (storage & VT_STATIC);

    /* Handle declarations */
    while (1) {
        CType full_type;
        char name[256] = "";

        /* Special case: no declarator (e.g., struct definition alone) */
        if (c->tok == ';') {
            cmp_next(c);
            return;
        }

        parse_declarator(c, &base_type, name, sizeof(name), &full_type);

        int bt = full_type.t & VT_BTYPE;

        if (is_typedef) {
            /* Add typedef */
            if (*name) {
                /* Check if it shadows an existing one */
                add_typedef(c, name, &full_type);
            }
        } else if (bt == VT_FUNC) {
            /* Function declaration or definition */
            TypeDef *fdef = full_type.ref;
            int is_definition = (c->tok == '{');

            if (!is_definition && c->tok != ';' && c->tok != ',') {
                /* Try to skip unexpected tokens */
                if (c->tok != TOK_EOF) {
                    cmp_next(c);
                }
