            /* Add to symbol table */
            if (*name) {
                /* Add to ELF symtab */
                int bind = (is_static) ? STB_LOCAL : STB_GLOBAL;
                int sym_idx = cu_add_elf_sym(c->cu, name, is_definition ? 1 : SHN_UNDEF,
                                              0, 0, STT_FUNC, bind, STV_DEFAULT);

                CType func_ptr_type;
                func_ptr_type.t = VT_FUNC;
                func_ptr_type.ref = fdef;

                struct VarEntry *e = add_var(c, name, &func_ptr_type, 0);
                e->sym_idx = sym_idx;
            }

            if (is_definition) {
                /* Function definition */
                c->in_func = 1;

                /* Save return type */
                c->func_ret_type = fdef ? fdef->ret_type : base_type;

                /* Create return label */
                c->func_ret_label = cg_new_label(c->cg);

                /* Reset locals */
                int saved_local = c->local_off;
                c->local_off = 0;
                c->max_local_size = 0;

                /* Function start offset */
                int func_start = cg_cur(c->cg);

                /* Emit prologue */
                emit_func_prologue2(c->cg);

