                int bind = (is_static) ? STB_LOCAL : STB_GLOBAL;
                int sym_idx = cu_add_elf_sym(c->cu, name, is_definition ? 1 : SHN_UNDEF,
                                              0, 0, STT_FUNC, bind, STV_DEFAULT);

                CType func_ptr_type;
                func_ptr_type.t = VT_FUNC;
                func_ptr_type.ref = fdef;

