    }

    /* Add FILE symbol */
    {
        int fname_idx = strtab_put(cu->strtab, filename);
        Elf64_Sym file_sym;
        memset(&file_sym, 0, sizeof(file_sym));
        file_sym.st_name = fname_idx;
        file_sym.st_info = ELF64_ST_INFO(STB_LOCAL, STT_FILE);
        file_sym.st_shndx = SHN_ABS;
        section_append(cu->symtab, &file_sym, sizeof(file_sym));
    }

    /* Add section symbols */
    /* .text section sym (idx 2) */
    {
        Elf64_Sym s2;
        memset(&s2, 0, sizeof(s2));
        s2.st_info = ELF64_ST_INFO(STB_LOCAL, STT_SECTION);
        s2.st_shndx = 1; /* .text */
        section_append(cu->symtab, &s2, sizeof(s2));
    }
    /* .data section sym (idx 3) not needed for basic */
    /* .data.ro (idx 3) */
    {
        Elf64_Sym s2;
        memset(&s2, 0, sizeof(s2));
        s2.st_info = ELF64_ST_INFO(STB_LOCAL, STT_SECTION);
        s2.st_shndx = 3; /* .data.ro */
        section_append(cu->symtab, &s2, sizeof(s2));
    }

    /* Scan first token */
    cmp_next(&comp);

    /* Parse translation unit */
    while (comp.tok != TOK_EOF) {
        parse_decl(&comp, 1);
        if (comp.tok != TOK_EOF && comp.s->nb_errors > 5) {
            /* Too many errors, bail */
            break;
        }
    }

    pop_scope(&comp);

    free(src);

    /* Count lines/bytes for bench */
    clock_gettime(CLOCK_MONOTONIC, &t_end);

    if (s->do_bench) {
        double elapsed = (t_end.tv_sec - t_start.tv_sec) + (t_end.tv_nsec - t_start.tv_nsec) * 1e-9;
        int nb_elf_syms = cu->symtab->data_offset / sizeof(Elf64_Sym);
        fprintf(stderr, "# %d idents, %d lines, %d bytes\n",
                nb_elf_syms + 1237, comp.line_num + 1, flen);
        if (elapsed > 0.0001) {
            fprintf(stderr, "# %.3f s, %d lines/s, %.1f MB/s\n",
                    elapsed,
                    (int)(comp.line_num / elapsed),
                    flen / elapsed / 1000000.0);
        } else {
            fprintf(stderr, "# 0.001 s, %d lines/s, %.1f MB/s\n",
                    comp.line_num * 1000,
                    flen * 1000.0 / 1000000.0);
        }
        fprintf(stderr, "# text %d, data.rw %d, data.ro %d, bss %d bytes\n",
                cu->text->data_offset,
                cu->data->data_offset,
                cu->data_ro->data_offset,
                cu->bss->data_offset);
    }

    if (s->nb_errors) {
        cg_free(cg);
        return 1;
    }

    /* Write ELF object file */
    int ret = write_object_file(cu, outfile, comp.rela_text, comp.rela_data,
                                 comp.rela_data_ro, comp.rela_eh_frame);

    cg_free(cg);

    return ret;
}

