# Still same issue! Let me trace again:
# 0x46: mov -5, edi
# 0x4b: call abs_val(-5) -> rax = 5
# -- First call result in rax (5) is NOT saved --
# 0x50: mov 3, edi
# 0x55: call abs_val(3) -> rax = 3
# 0x5a: mov rax, -8(%rbp) -> save rax (3) to temp
# 0x5e: mov eax, ecx -> ecx = 3
# 0x60: mov -8(%rbp), eax -> eax = 3 (from temp) 
# 0x63: add ecx, eax -> 3 + 3 = 6
# WRONG - should be 5 + 3 = 8
#
# The issue: my fix saved the SECOND result (after the second call) instead of the FIRST.
# The expression is: abs_val(-5) + abs_val(3)
# Parse order:
# 1. Evaluate abs_val(-5) -> v = {cat=V_REG_INT, reg=RAX}
# 2. In add_expr: see '+', save v1 = {V_REG_INT, RAX}
# 3. Evaluate mul_expr(abs_val(3)) -> need to call abs_val(3), which clobbers RAX
# 4. But my fix: in bin_op, I first load v (which is V_REG_INT in RAX), save to temp
# 5. Then load v2 (which is the second call result, also V_REG_INT in RAX)
# 
# Wait - the problem is different. After the second call, v2 is {V_REG_INT, RAX=3}.
# My bin_op fix saves a (which is V_REG_INT) to temp, BUT:
# At the time bin_op is called, 'a' is {V_REG_INT, RAX=5}
# However, by the time I try to load 'b', the call to abs_val(3) has clobbered RAX
# 
# The issue is that bin_op is called AFTER both operands are evaluated!
# In add_expr:
#   a = abs_val(-5) -> a = {V_REG_INT, RAX=5}
#   b = mul_expr(abs_val(3)) -> this CALL changes RAX to 3 -> a is now stale!
#
# Actually wait - add_expr evaluates a FIRST, then b. 
# a is computed by mul_expr -> calls abs_val(-5) -> a = {V_REG_INT, RAX=5}
# Then add_expr sees '+', calls mul_expr again for b
# mul_expr calls abs_val(3) -> b = {V_REG_INT, RAX=3}
# 
# Now bin_op is called with a={V_REG_INT,RAX=5} and b={V_REG_INT,RAX=3}
# But RAX is currently 3 (from b's evaluation), so a's value is GONE!
# 
# The fix needs to happen BEFORE evaluating b, not in bin_op.
# In add_expr, after getting a, save a to a temp before evaluating b.

# Let me fix add_expr, mul_expr, etc. to save a before evaluating b
python3 << 'PYEOF'
with open('tcc.c', 'r') as f:
    content = f.read()

# Fix add_expr
old = '''static void add_expr(Compiler *c, Val *v) {
    mul_expr(c, v);
    while (c->tok == '+' || c->tok == '-') {
        int op = c->tok;
        cmp_next(c);
        Val v2;
        mul_expr(c, &v2);
        bin_op(c, v, &v2, op);
    }
}'''

new = '''static void add_expr(Compiler *c, Val *v) {
    mul_expr(c, v);
    while (c->tok == '+' || c->tok == '-') {
        int op = c->tok;
        cmp_next(c);
        /* Save v to a local temp BEFORE evaluating v2 (which might clobber RAX) */
        int saved_off = 0;
        if (v->cat == V_REG_INT || v->cat == V_REG_FLT) {
            int sz = 8;
            saved_off = alloc_local(c, sz, sz);
            if (v->cat == V_REG_INT) {
                emit_mov_rbp_off_r64(c->cg, saved_off, v->reg);
            }
            int old_cat = v->cat;
            v->cat = V_LOCAL;
            v->local_off = saved_off;
        }
        Val v2;
        mul_expr(c, &v2);
        bin_op(c, v, &v2, op);
    }
}'''

if old in content:
    content = content.replace(old, new, 1)
    print("Fixed add_expr")
else:
    print("add_expr pattern not found")

with open('tcc.c', 'w') as f:
    f.write(content)
