    content = f.read()

# Find and replace emit_eh_frame
old_start = '/* Emit EH frame for a function */'
old_end = '/* Return statement handling */'

idx_start = content.find(old_start)
idx_end = content.find(old_end)

if idx_start >= 0 and idx_end >= 0:
    # Replace the whole function
    new_eh = '''/* Emit EH frame for a function */
static void emit_eh_frame(Compiler *c, int func_start, int func_end) {
    Section *eh = c->cu->eh_frame;
    int func_size = func_end - func_start;

    /* First call: emit CIE */
    static int cie_done = 0;  /* per compilation unit - reset in cu_new */

    if (eh->data_offset == 0) {
        /* Emit CIE */
        /* Length: 20 bytes (after length field) */
        section_put4(eh, 0x14);         /* CIE length = 20 */
        section_put4(eh, 0x00000000);   /* CIE ID = 0 */
        section_put1(eh, 0x01);         /* version = 1 */
        section_put1(eh, 'z');          /* augmentation */
        section_put1(eh, 'R');
        section_put1(eh, 0x00);         /* terminator */
        section_put1(eh, 0x01);         /* code align = 1 */
        section_put1(eh, 0x78);         /* data align = -8 */
        section_put1(eh, 0x10);         /* return addr reg = 16 */
        section_put1(eh, 0x01);         /* aug data len = 1 */
        section_put1(eh, 0x1b);         /* FDE encoding: pcrel+sdata4 */
        /* Initial instructions */
        section_put1(eh, 0x0c);         /* DW_CFA_def_cfa */
        section_put1(eh, 0x07);         /* register = RSP (7) */
        section_put1(eh, 0x08);         /* offset = 8 */
        section_put1(eh, 0x90);         /* DW_CFA_offset r16 */
        section_put1(eh, 0x01);         /* factor*-8 = 1 => offset=-8 */
        section_put1(eh, 0x00);         /* pad */
        section_put1(eh, 0x00);
        section_put1(eh, 0x00);
        /* Total CIE: 4 + 20 = 24 bytes */
    }

    /* Emit FDE */
    int fde_start_off = eh->data_offset; /* should be 24 = 0x18 */

    section_put4(eh, 0x20);  /* FDE length = 32 bytes */

    /* CIE pointer: offset from this field (at fde_start_off + 4) back to CIE start (0) */
    /* = fde_start_off + 4 */
    section_put4(eh, fde_start_off + 4);  /* e.g., 0x1c for first FDE */

    /* PC begin: relocated to .text[func_start] */
    int pc_begin_off = eh->data_offset;
    section_put4(eh, 0);  /* placeholder */
    /* Add relocation: R_X86_64_PC32 to .text + func_start */
    /* sym_idx 2 = .text section symbol */
    cu_add_rela(&c->rela_eh_frame, NULL, c->cu->eh_frame,
                pc_begin_off, 2, R_X86_64_PC32, func_start - 4);

    /* PC range: function size */
    section_put4(eh, func_size);

    /* Augmentation data length = 0 */
    section_put1(eh, 0x00);

    /* Call frame instructions */
    /* DW_CFA_advance_loc 1: push rbp (1 byte) */
    section_put1(eh, 0x41);
    /* DW_CFA_def_cfa_offset 16 */
    section_put1(eh, 0x0e);
    section_put1(eh, 0x10);
    /* DW_CFA_offset r6 at cfa-16 (factor=-8, so column=2) */
    section_put1(eh, 0x86);
    section_put1(eh, 0x02);
    /* DW_CFA_advance_loc 3: mov rbp,rsp (3 bytes) */
    section_put1(eh, 0x43);
    /* DW_CFA_def_cfa_register r6 */
    section_put1(eh, 0x0d);
    section_put1(eh, 0x06);

    /* DW_CFA_advance_loc4 for rest of function */
    int remaining = func_size - 11; /* 11 = 1+3+7 for prologue */
    if (remaining < 0) remaining = 0;
    section_put1(eh, 0x04);  /* DW_CFA_advance_loc4 */
    section_put4(eh, (uint32_t)remaining);
    /* Reset CFA to RSP+8 for epilogue */
    section_put1(eh, 0x0c);
    section_put1(eh, 0x07);
    section_put1(eh, 0x08);

    /* Pad to 8-byte boundary */
    int fde_content_size = eh->data_offset - fde_start_off - 4; /* -4 for length field */
    while (fde_content_size % 8 != 4) {
        section_put1(eh, 0x00);
        fde_content_size++;
    }
    /* Actually patch the length */
    *(uint32_t *)(eh->data + fde_start_off) = (uint32_t)(eh->data_offset - fde_start_off - 4);
}

'''
    content = content[:idx_start] + new_eh + content[idx_end:]
    print("Replaced emit_eh_frame")
else:
    print(f"Could not find function: start={idx_start}, end={idx_end}")

with open('tcc.c', 'w') as f:
    f.write(content)
