    content = f.read()

old = '''    case V_GLOBAL: {
        /* Load global variable */
        CodeGen *cg = c->cg;
        /* For global pointers, load the address */
        /* For global integers, load the value */
        if (is_64 || is_ptr) {
            emit_mov_r64_riprel(cg, reg, v->sym_idx);
        } else {
            /* Load as 32-bit via RIP-relative */
            if (reg >= 8) emit1(cg, rex_byte(0, 1, 0, 0));
            emit1(cg, 0x8b);
            emit1(cg, modrm(0, reg & 7, 5));
            int pos = cg_cur(cg);
            emit4(cg, 0);
            cu_add_rela(&c->rela_text, NULL, c->cu->text, pos, v->sym_idx, R_X86_64_PC32, -4);
        }
        break;
    }'''

new = '''    case V_GLOBAL: {
        /* Load global variable */
        CodeGen *cg = c->cg;
        int bt = v->type.t & VT_BTYPE;

        /* For pointer/array types, we want the ADDRESS (LEA), not the value */
        int use_lea = (bt == VT_PTR || bt == VT_FUNC);

        if (use_lea) {
            /* LEA reg, [rip+sym] */
            if (reg >= 8) {
                emit2(cg, rex_byte(1, 1, 0, 0), 0x8d);
                emit1(cg, modrm(0, reg & 7, 5));
            } else {
                emit2(cg, rex_byte(1, 0, 0, 0), 0x8d);
                emit1(cg, modrm(0, reg & 7, 5));
            }
            int pos = cg_cur(cg);
            emit4(cg, 0);
            cu_add_rela(&c->rela_text, NULL, c->cu->text, pos, v->sym_idx, R_X86_64_PC32, -4);
        } else if (is_64) {
            emit_mov_r64_riprel(cg, reg, v->sym_idx);
