    if (!s->bs) return;
    BufferState *old = s->bs;
    s->bs = old->prev;
    /* If this was a string buffer (e.g. macro expansion), free the data */
    if (old->is_string && old->buf) {
        free((char*)old->buf);
    }
    free(old->filename);
    free(old);
    if (s->bs) {
        /* Restore s->ch from parent buffer */
        /* After the included/pushed buffer exhausted, we need to re-read
