# The else handling:
# } else {
#   skip_line(s);
#   int lvl = s->iflevel - 1; // lvl = 0
#   if (lvl >= 0) { s->ifstack[lvl].skip = s->ifstack[lvl].had_true; }
#   // skip = had_true = 0
# }
# } else { <- this closes the outer "if/elif/else" check
#   skip_line(s); <- this is for UNKNOWN directives
# }
# cstr_reset(&dn);
# at_line_start = 1;
# if (s->ch == '\n') { bs_adv(s); }
# continue;
# 
# OK so after #else, skip=0. Then at_line_start=1. Then bs_adv reads 'i'.
# Then continue -> top of while loop.
# 
# WAIT! After continue, we go back to "while (s->ch)". Then:
# if (s->iflevel > 0 && s->ifstack[s->iflevel-1].skip) {
# s->iflevel=1, skip=0 -> FALSE -> skip block NOT entered ✓
# 
# Then we process 'i'. But s->ch = 'i' (from bs_adv after '\n').
# At the top: char c = s->ch = 'i'.
# 
# But wait - there's another issue!
# After the skip block ends (after #else), I set at_line_start=1 and do bs_adv.
# BUT what if at_line_start was set BEFORE I entered the "if (at_line_start && s->ch == '#')" block?
# 
# Let me trace the EXACT sequence:
# 1. We're in skip mode (skip=1). s->ch = '\n'.
# 2. "Skip this character" block: s->ch == '\n' -> bs_adv -> s->ch = ' ' (space before #else)
#    at_line_start = 1
#    continue
# 3. Top of while: check skip -> still skip=1
# 4. at_line_start=1, s->ch=' ':
#    "if (at_line_start && s->ch == '#')" -> FALSE (s->ch != '#')
#    So we go to "else { bs_adv(s); }" section
#    bs_adv -> s->ch = '#'  
#    at_line_start=0 (set in the else branch)
#    continue
# 5. Top of while: check skip -> still 1
#    at_line_start=0, s->ch='#'
#    "if (at_line_start && s->ch == '#')" -> FALSE! (at_line_start = 0!)
#    So we DON'T process '#' as a directive!
#    "else { bs_adv(s); }" -> advance past '#' and 'e','l','s','e' etc.
#    Eventually the skip loop just skips the #else!
# 
# AH HA! The bug is:
# When skipping, if we see '\n', we set at_line_start=1 and bs_adv.
# bs_adv reads the first char of the next line (e.g., space ' ').
# Then in the skip block: at_line_start=1 but s->ch=' ' (not '#') -> else branch -> bs_adv, at_line_start=0.
# Next char is '#'. But at_line_start=0 now -> '#' not treated as directive!

# The fix: in the skip block, when we see spaces on a line with at_line_start=1,
# we should KEEP at_line_start=1. Only clear it when we see non-space, non-# chars.

python3 << 'PYEOF'
with open('tcc.c', 'r') as f:
    content = f.read()

# Find the skip mode character handling block
old_skip_char = '''            /* Skip this character */
            if (s->ch == '\n') {
                bs_adv(s);
                at_line_start = 1;
            } else {
                bs_adv(s);
                at_line_start = 0;
            }
            continue;'''

new_skip_char = '''            /* Skip this character */
            if (s->ch == 10) { /* newline */
                bs_adv(s);
                at_line_start = 1;
            } else if (s->ch == ' ' || s->ch == '\t') {
                /* Whitespace: preserve at_line_start */
                bs_adv(s);
                /* at_line_start unchanged */
            } else {
                bs_adv(s);
                at_line_start = 0;
            }
            continue;'''

if old_skip_char in content:
    content = content.replace(old_skip_char, new_skip_char, 1)
    print("Fixed skip character handling to preserve at_line_start through whitespace")
else:
    print("Pattern not found")
    idx = content.find('/* Skip this character */')
    print(content[idx:idx+300])

with open('tcc.c', 'w') as f:
    f.write(content)
