# Position 64='@': 0
# Position 65='A': 1
# ...
# Position 90='Z': 1 (25th element)
# Position 91='[': 0
# Position 92='\\': 0
# Position 93=']': 0
# Position 94='^': 0
# Position 95='_': 1 ✓
# 
# So '_' IS in is_idstart. ✓
# 
# Then why does "defined __x86_64__" fail?
# 
# In ppe_primary:
# e->p at "defined __x86_64__..."
# strncmp("defined", 7) ok
# !is_id(e->p[7]): e->p[7] = ' ' (space after "defined")
# !is_id(' ') = !0 = 1 ✓
# 
# e->p += 7 -> now at " __x86_64__"
# ppe_skip_spaces: skip ' ' -> now at "__x86_64__"
# has_paren = ('_' == '(') = 0
# nm = e->p = "__x86_64__"
# while (is_id(*e->p)): reads _, _, x, 8, 6, _, 6, 4, _, _ -> nmlen = 10
# macname = "__x86_64__"
# macro_find(s, "__x86_64__") -> should return the macro!
# 
# BUT WAIT: is_id('8') and is_id('6') - are digits included?
# is_id(c) = is_idstart[c] || (c >= '0' && c <= '9')
# '8' is a digit -> is_id('8') = true ✓
# 
# So nmlen should be 10 (__x86_64__ has 10 chars).
# macro_find(s, "__x86_64__") -> found -> returns 1!
# 
# But the test showed "int x32" is output!
# 
# Wait - let me check the MACRO_EXPAND for "defined":
# In macro_expand, I have special handling for "defined":
# if (name.buf && !strcmp(name.buf, "defined")) {
#     /* Output "defined(ARGNAME)" without macro expansion of arg */
#     cstr_cat(&result, "defined", -1);
#     while (*p == ' ' || *p == '\t') p++;
#     if (*p == '(') { ... copy arg name verbatim ... }
#     cstr_reset(&name); continue;
# }
# 
# When the expression is "!defined __x86_64__":
# macro_expand is called on "!defined __x86_64__"
# We process '!' -> output '!'
# We process "defined" -> NOT a macro, goes to special handling:
#   NO '(' after "defined", so we just output "defined" and continue
# Then we process " __x86_64__" -> identifier "__x86_64__" -> IS a macro!
# macro body = "1"
# push "1" as buffer
# Output "1"
# 
# So macro_expand("!defined __x86_64__") = "!defined 1"!
# Then pp_eval_expr evaluates "!defined 1":
# ppe_primary: "defined 1" -> strncmp ok, skip space, nm = "1"
# is_id('1') - '1' is a digit >= '0' && <= '9'... wait:
# is_id(c) = is_idstart[c] || (c >= '0' && c <= '9')
# is_idstart['1'] = 0, but '1' >= '0' && '1' <= '9' = true -> is_id('1') = true!
# So "1" is read as macro name -> macro_find(s, "1") -> NULL
# Returns 0!
# !0 = 1! True!
# 
# AH HA! The bug is that when "defined __x86_64__" is macro-expanded, __x86_64__ becomes "1".
# Then ppe_primary reads the "1" as a macro name "1" which is not defined -> 0.
# So !defined 1 = !0 = 1 -> True -> includes stubs-32.h.
# 
# The fix: in macro_expand, when we see "defined", we should also handle the NO-PAREN case
# by copying the argument verbatim (no expansion).

python3 << 'PYEOF'
with open('tcc.c', 'r') as f:
    content = f.read()

old = '''            /* Check for "defined" operator - don't expand its argument */
                if (name.buf && !strcmp(name.buf, "defined")) {
                    /* Output "defined(ARGNAME)" without macro expansion of arg */
                    cstr_cat(&result, "defined", -1);
                    /* Skip spaces */
                    while (*p == ' ' || *p == '\\t') p++;
                    if (*p == '(') {
                        cstr_ccat(&result, '(');
                        p++;
                        /* Copy arg name verbatim (no expansion) */
                        while (*p && *p != ')') {
                            cstr_ccat(&result, *p++);
                        }
                        if (*p == ')') { cstr_ccat(&result, ')'); p++; }
                    }
                    cstr_reset(&name);
                    continue;
                }'''

new = '''            /* Check for "defined" operator - don't expand its argument */
                if (name.buf && !strcmp(name.buf, "defined")) {
                    /* Output "defined(ARGNAME)" or "defined ARGNAME"
                     * without macro expansion of arg */
                    cstr_cat(&result, "defined", -1);
                    /* Skip spaces */
                    while (*p == ' ' || *p == '\\t') p++;
                    if (*p == '(') {
                        cstr_ccat(&result, '(');
                        p++;
                        while (*p == ' ' || *p == '\\t') p++;
                        /* Copy arg name verbatim (no expansion) */
                        while (*p && *p != ')') {
                            cstr_ccat(&result, *p++);
                        }
                        if (*p == ')') { cstr_ccat(&result, ')'); p++; }
                    } else {
                        /* No paren form: copy identifier verbatim */
                        cstr_ccat(&result, ' ');
                        while (is_id(*p)) {
                            cstr_ccat(&result, *p++);
                        }
                    }
                    cstr_reset(&name);
                    continue;
                }'''

if old in content:
    content = content.replace(old, new, 1)
    print("Fixed defined no-paren macro expansion")
else:
    print("Pattern not found")

with open('tcc.c', 'w') as f:
    f.write(content)
