new_for = '''case TOK_FOR: {
        cmp_next(c);
        expect(c, '(');
        push_scope(c);

        CodeGen *cg = c->cg;

        /* For loop structure:
         * for (init; cond; incr) body
         * =>
         * init
         * JMP cond_check
         * loop_top:
         *   body
         *   incr_code (jump target for continue)
         * cond_check:
         *   if (cond) JMP loop_top
         * end:
         */

        int loop_top = cg_new_label(cg);
        int incr_label = cg_new_label(cg);
        int cond_label = cg_new_label(cg);
        int end_label = cg_new_label(cg);

        if (c->nb_break >= c->cap_break) {
            c->cap_break = c->cap_break ? c->cap_break*2 : 8;
            c->break_labels = tcc_realloc(c->break_labels, c->cap_break*sizeof(int));
        }
        if (c->nb_cont >= c->cap_cont) {
            c->cap_cont = c->cap_cont ? c->cap_cont*2 : 8;
            c->continue_labels = tcc_realloc(c->continue_labels, c->cap_cont*sizeof(int));
        }
        c->break_labels[c->nb_break++] = end_label;
        c->continue_labels[c->nb_cont++] = incr_label;

        /* Parse and emit init expression */
        if (c->tok != ';') {
            if (is_type_specifier(c)) {
                parse_decl(c, 0);
                /* parse_decl consumes the ';' */
            } else {
                Val v;
                expr(c, &v);
                if (c->tok == ';') cmp_next(c);
            }
        } else {
            cmp_next(c); /* skip ';' */
        }

        /* JMP to condition check */
        emit1(cg, 0xe9);
        cg_emit_ref(cg, cond_label);

        /* Loop top (target for back-edge) */
        cg_define_label(cg, loop_top);

        /* Parse body */
        stmt(c);

        /* Increment label (target for continue) */
        cg_define_label(cg, incr_label);

