            static const int int_arg_regs[] = {TREG_RDI, TREG_RSI, TREG_RDX, TREG_RCX, TREG_R8, TREG_R9};
            int int_arg = 0, flt_arg = 0;
            CodeGen *cg = c->cg;

            /* Strategy: evaluate each arg and IMMEDIATELY move to its target register.
             * We save args[i] in temp locals if they're V_REG_INT (to avoid clobbering).
             * Since arg registers (RDI,RSI,...) don't include RAX, we can:
             * - Load arg[0] into RAX, then mov RAX->RDI
             * - Load arg[1] into RAX (doesn't clobber RDI), then mov RAX->RSI
             * etc.
