            /* (This is needed because evaluating one arg might clobber another) */
            /* Actually, since all our arg evaluation results go through RAX,
             * and arg regs are RDI..R9, we just need to handle the case where
             * an arg is IN a param register (from a previous call result).
             * Solution: if arg.cat==V_REG_INT and arg.reg is RDI..R9, save it. */
            for (int i = 0; i < nb_args; i++) {
                if (args[i].cat == V_REG_INT &&
                    (args[i].reg == TREG_RDI || args[i].reg == TREG_RSI ||
                     args[i].reg == TREG_RDX || args[i].reg == TREG_RCX ||
