# Progress! LEA is now used (0x0b: lea -0x14(%rbp), rax). 
# But the assignment still doesn't work:
# 0x0b: LEA addr of arr[0] -> RAX
# 0x0f-0x18: compute arr+0*4 -> RAX
# 0x1b: MOV (%rax), eax <- DEREFERENCE (WRONG for store!)
# 0x1d: MOV $1, eax <- this is the VALUE to store
# 
# The problem: 'arr[0] = 1' should STORE 1 to arr[0].
# But my code:
# 1. Evaluates arr[0] (the SUBSCRIPT), which dereferences -> gives current value
# 2. Evaluates 1
# 3. Stores 1 to... what? The subscript result is in RAX (current array value), not the address!
# 
# The issue: my array subscript code computes the ADDRESS, dereferences it,
# and returns the VALUE. For assignment, I need the ADDRESS.
# 
# In C, lvalue semantics: arr[0] is an lvalue, so it can be assigned to.
# My subscript code should return a VALUE that, when used as lvalue, stores there.
# 
# The proper approach: after computing the address in RAX, instead of dereferencing,
# mark the value as "lvalue in memory at [RAX]".
# 
# My current code in postfix_expr for '[':
# deref_ptr_to_rax(c, TREG_RAX, &elem_type);  <- this dereferences!
# 
# The fix: for array subscripts used as LVALUES, I should NOT dereference.
# Instead, the address should be kept as the value, and only dereferenced when reading.
# 
# This is the fundamental lvalue/rvalue distinction in C.
# 
# TCC's approach: use a "VT_LVAL" flag to indicate the value is an lvalue that needs
# to be loaded. When we see arr[i] on the LHS of assignment, we keep the address.
# When we see it on the RHS, we load from that address.
# 
# Let me fix this properly. The key insight: after computing the ELEMENT ADDRESS in RAX,
# I should store that as a "pointer that needs dereferencing" (an lvalue).
# Then in assign_expr, I can store to that address.
# 
# Fix approach: instead of dereferencing in the subscript operator, return a
# "lvalue at address in RAX".
# 
# But my Val structure doesn't support "lvalue at address in register".
# Let me add V_LVAL_REG category:
# V_LVAL_REG: the value is AT the address stored in reg.

python3 << 'PYEOF'
with open('tcc-src/tcc.c', 'r') as f:
    content = f.read()

# Fix the array subscript case in postfix_expr
old = '''            /* Now RAX has the address, dereference it */
            deref_ptr_to_rax(c, TREG_RAX, &elem_type);

            v->type = elem_type;
            v->cat = V_REG_INT;
            v->reg = TREG_RAX;
            v->is_lvalue = 1;
            break;
        }'''

new = '''            /* RAX now contains the ELEMENT ADDRESS.
             * We DON'T dereference yet - mark as addressable lvalue.
             * When reading, we'll dereference; when writing, we'll store.
             * Use a temp local to save the address. */
            /* Save address to a temp local for lvalue use */
            int addr_local = alloc_local(c, 8, 8);
            emit_mov_rbp_off_r64(c->cg, addr_local, TREG_RAX);

            v->type = elem_type;
            v->cat = V_LOCAL;  /* addr is at addr_local */
            v->local_off = addr_local;
            v->is_lvalue = 1;

            /* Mark as POINTER that needs dereferencing for reads */
            /* We'll use a special trick: set the type as element type */
            /* When loading, we need to load from [addr_local] (which has the element addr) */
            /* When storing, we need to store to [addr_local] */
            /* Actually: we need to know this is an indirect local (pointer in local) */
            /* For now, load the value from the address */
            {
                /* Save address in RAX */
                emit_mov_r64_rbp_off(c->cg, TREG_RAX, addr_local);
                /* Dereference to get value */
                deref_ptr_to_rax(c, TREG_RAX, &elem_type);
                /* Store dereferenced value to the local */
                /* But we need to keep the ADDRESS too for lvalue assignment! */
                /* Solution: use two locals: one for address, one for value */
                /* Actually, this approach is getting complex.
                 * Let me use a different approach:
                 * Keep V_REG_INT with the ELEMENT ADDRESS in RAX.
                 * Set is_lvalue=1 and a special flag.
                 * In assign_expr, check for this case. */
                /* Revert: just keep the address in RAX */
                emit_mov_r64_rbp_off(c->cg, TREG_RAX, addr_local);
            }

            /* Mark as "indirect value": address of element in RAX, value can be loaded/stored */
            v->cat = V_REG_INT;
            v->reg = TREG_RAX;
            v->is_lvalue = 1;
            /* We mark this specially: RAX holds the ELEMENT ADDRESS (not value) */
            /* type is elem_type but the register holds an address to elem */
            /* Create a pointer-to-elem type for this */
            {
                TypeDef *ptd = calloc(1, sizeof(TypeDef));
                ptd->element_type = elem_type;
                ptd->kind = TK_ARRAY;
                CType ptr_type;
                ptr_type.t = VT_PTR | VT_LVAL; /* mark as lvalue pointer */
                ptr_type.ref = ptd;
                v->type = ptr_type;
            }
            break;
        }'''

if old in content:
    content = content.replace(old, new, 1)
    print("Attempting array subscript fix")
else:
    print("Pattern not found")
    idx = content.find('/* Now RAX has the address, dereference it */')
    print(content[max(0,idx-50):idx+200])

with open('tcc-src/tcc.c', 'w') as f:
    f.write(content)
