# I see a few issues at the end:
# At 0xb6: save address of arr[0] (for reading arr[0])
# At 0xba: save address of arr[4] (for reading arr[4])
# But then at 0xca: mov %rax, %rcx <- puts addr of arr[4] into rcx
# At 0xcd: mov -0x48(%rbp), %eax <- loads saved addr of arr[0]
# At 0xd0: mov %rcx, %rax <- puts addr of arr[4] into rax! WRONG
# At 0xd3: mov (%rax), %eax <- loads arr[4] to eax
# This is wrong - should add arr[0] + arr[4]
# 
# The issue: when computing "arr[0] + arr[4]":
# - arr[0] is is_lvalue=2 with addr in RAX (saved to temp)
# - arr[4] is is_lvalue=2 with addr in RAX (saved to temp)
# 
# In add_expr, I save the first operand to a local if V_REG_INT.
# But when loading arr[0] (indirect, is_lvalue=2), load_val_to_reg dereferences.
# And there's some issue with the dereferencing path.
# 
# Actually looking more carefully at 0xcd-0xd7:
# cd: mov -0x48(%rbp), eax <- eax = addr of arr[0]
# d0: mov %rcx, %rax <- this is wrong! overwrites
# 
# The issue is in the binary op save code. When we save arr[0] to a temp,
# the V_REG_INT with is_lvalue=2 saves the ADDRESS (not the value).
# Then when we load it (in load_val_to_reg for V_LOCAL), it loads the address
# instead of dereferencing through it.
# 
# The problem is: after the add_expr save of arr[0]:
# Original: {V_REG_INT, RAX=addr_of_arr0, is_lvalue=2}
# After save: {V_LOCAL, local_off=temp_addr_of_arr0} <- saves the ADDRESS to local
# 
# Then load_val_to_reg for V_LOCAL reads: temp_addr_of_arr0 (the address value)
# This gives the ADDRESS of arr[0], not the VALUE.
# 
# We need to dereference through the saved address!
# 
# This is getting complicated. Let me take a step back and think about
# a cleaner approach.
# 
# Actually, the real fix: when an array element (is_lvalue=2) is used in an expression,
# we should IMMEDIATELY dereference it to get the value.
# We only need is_lvalue for ASSIGNMENT (the LHS case).
# 
# For the RHS (reading), we should just return the VALUE (after dereferencing).
# 
# The distinction: when arr[0] appears as LHS, return is_lvalue=2 with address.
# When arr[0] appears as RHS, return the VALUE (after dereferencing).
# 
# C semantics: expressions are VALUES unless they need to be assigned to.
# In C, arr[0] has array-element lvalue, but when USED in an expression, it's read.
# Only when used with '=' (or compound assignment) is it an lvalue.
# 
# So the fix: after array subscript, IMMEDIATELY dereference to get the value.
# BUT: we need to retain the "lvalue address" for the assignment case.
# 
# TCC's approach: use "VT_LVAL" type flag to mark lvalues.
# When a VT_LVAL is used in an expression, it's loaded.
# When a VT_LVAL is on the LHS of assignment, it's stored to.
# 
# My simplest fix for now: just track the "address" and "value" separately.
# When reading, dereference. When writing, use the address.
# 
# Let me restructure: after computing the element address,
# I'll keep both the address AND the dereferenced value.
# Actually, let me just always dereference for now and handle assignment specially.

python3 << 'PYEOF'
with open('tcc-src/tcc.c', 'r') as f:
    content = f.read()

# Simpler approach: for array subscripts, keep the address in v and dereference on read.
# Change the add_expr etc. to handle is_lvalue=2 by loading the VALUE before saving.

# Find the add_expr save code:
old_save = '''        if (v->cat == V_REG_INT || v->cat == V_REG_FLT) {
            int sz = 8;
            int saved_off = alloc_local(c, sz, sz);
            if (v->cat == V_REG_INT) {
                emit_mov_rbp_off_r64(c->cg, saved_off, v->reg);
            }
            int old_cat = v->cat;
            v->cat = V_LOCAL;
            v->local_off = saved_off;
        }
        Val v2;
        mul_expr(c, &v2);
        bin_op(c, v, &v2, op);
    }
}'''

new_save = '''        if (v->cat == V_REG_INT || v->cat == V_REG_FLT) {
            /* Before saving to temp local, ensure we have the VALUE (not address) */
            if (v->is_lvalue == 2) {
                /* Indirect lvalue: load the value through the address */
                load_val_to_reg(c, v, TREG_RAX);
                v->is_lvalue = 0;
            }
            int sz = 8;
            int saved_off = alloc_local(c, sz, sz);
            if (v->cat == V_REG_INT) {
                emit_mov_rbp_off_r64(c->cg, saved_off, v->reg);
            }
            v->cat = V_LOCAL;
            v->local_off = saved_off;
        }
        Val v2;
        mul_expr(c, &v2);
        bin_op(c, v, &v2, op);
    }
}'''

count = content.count(old_save)
print(f"Found {count} occurrences of save code")
if count > 0:
    content = content.replace(old_save, new_save)
    print("Fixed add_expr save")

with open('tcc-src/tcc.c', 'w') as f:
    f.write(content)
