                        if (field->addr != 0) {
                            CodeGen *cg = c->cg;
                            if (field->addr <= 127) {
                                emit2(cg, rex_byte(1,0,0,0), 0x83);
                                emit2(cg, modrm(3, 0, v->reg & 7), (uint8_t)field->addr);
                            } else {
                                emit2(cg, rex_byte(1,0,0,0), 0x81);
                                emit1(cg, modrm(3, 0, v->reg & 7));
                                emit4(cg, (uint32_t)field->addr);
                            }
                        }
                        /* RAX now has the field address - keep is_lvalue=2 */
                        v->cat = V_REG_INT;
                        v->reg = TREG_RAX;
                        v->type = field->type;
                        v->is_lvalue = 2;
                        break;
                    } else {
                        /* Direct register: add offset and dereference */
                        if (field->addr != 0) {
                            CodeGen *cg = c->cg;
                            if (field->addr <= 127) {
                                emit3(cg, rex_byte(1,0,0,0), 0x83, modrm(3, 0, v->reg & 7));
                                emit1(cg, (uint8_t)field->addr);
                            } else {
                                emit2(cg, rex_byte(1,0,0,0), 0x81);
                                emit1(cg, modrm(3, 0, v->reg & 7));
                                emit4(cg, (uint32_t)field->addr);
                            }
                        }
                        /* Dereference to get value */
                        deref_ptr_to_rax(c, v->reg, &field->type);
                        v->cat = V_REG_INT;
                        v->reg = TREG_RAX;
                    }
                }
                v->type = field->type;
            }
            v->is_lvalue = 1;'''

