        v->reg = TREG_RAX;
        v->type.t = VT_INT;
        return;
    }
    case '-': {'''

new_not = '''        v->cat = V_REG_INT;
        v->reg = TREG_RAX;
        v->type.t = VT_INT;
        v->is_lvalue = 0; /* Result of ! is never an lvalue */
        return;
    }
    case '-': {'''

content = content.replace(old_not, new_not, 1)
print("Fixed ! operator")

# Also fix: in load_val_to_reg, clear is_lvalue after loading
# Actually, the real fix is: ANY value that results from computation (not a variable reference)
