    v->reg = reg;
}

/* Store a value to a local variable */'''

new_end = '''    v->cat = V_REG_INT;
    v->reg = reg;
    v->is_lvalue = 0; /* Value is now in register, no longer an lvalue */
}

/* Store a value to a local variable */'''

if old_end in content:
    content = content.replace(old_end, new_end, 1)
    print("Fixed load_val_to_reg to clear is_lvalue")

with open('tcc-src/tcc.c', 'w') as f:
    f.write(content)
